(() => {
  const QUESTIONS = [
    {id:'LOC-001',title:'ID locator',question:'Given this HTML:\n<input id="email" type="text">\n\nWhich Selenium statement correctly locates this element?',options:[['A','driver.findElement(By.name("email"));'],['B','driver.findElement(By.id("email"));'],['C','driver.findElement(By.className("email"));'],['D','driver.findElement(By.tagName("email"));']],answer:['B'],expected:'Returns the WebElement representing the input field.',steps:'1. Selenium receives the locator By.id("email").\n2. It searches the DOM for an element with id="email".\n3. It finds the input element.\n4. findElement() returns that WebElement.',concept:'An HTML ID identifies an element. For <input id="email">, use By.id("email").',optionReview:'A: Incorrect — searches the name attribute.\nB: Correct — searches the id attribute.\nC: Incorrect — searches the class attribute.\nD: Incorrect — searches for an HTML tag named email.',takeaway:'id attribute → By.id().'},
    {id:'LOC-002',title:'Class name',question:'Given:\n<button class="login-button primary">Login</button>\n\nWhich statement is correct?',options:[['A','By.className("login-button primary") is valid.'],['B','By.className("login-button") is valid.'],['C','By.id("login-button") is valid.'],['D','By.name("primary") is valid.']],answer:['B'],expected:'The locator identifies the button using its login-button class.',steps:'1. The HTML element has two classes: login-button and primary.\n2. Selenium receives By.className("login-button").\n3. It searches for an element containing that class.\n4. It finds the button.',concept:'An HTML element can have multiple CSS classes. The value "login-button primary" represents two separate class names. By.className() accepts only one class name at a time.',optionReview:'A: Incorrect — space-separated multiple classes are not accepted by By.className().\nB: Correct — this is one valid class name.\nC: Incorrect — no ID attribute exists.\nD: Incorrect — no name attribute exists.',takeaway:'By.className() accepts a single class token, not "class1 class2".'},
    {id:'LOC-003',title:'Name locator',question:'Given:\n<input name="username" id="user1">\n<input name="username" id="user2">\n\nWhat happens when this executes?\nWebElement element = driver.findElement(By.name("username"));',options:[['A','Selenium throws an exception because the name is duplicated.'],['B','Selenium returns both elements.'],['C','Selenium returns the first matching element.'],['D','Selenium returns the last matching element.']],answer:['C'],expected:'The first matching input element, with id="user1", is returned.',steps:'1. Selenium searches for elements with name="username".\n2. It finds two matching elements.\n3. findElement() returns the first match in document order.\n4. The second matching element is not returned.',concept:'findElement(By.name("username")) returns one WebElement — the first match. findElements(By.name("username")) returns a List<WebElement> containing all matches.',optionReview:'A: Incorrect — duplicate names are allowed.\nB: Incorrect — this describes findElements().\nC: Correct — findElement() returns the first matching element.\nD: Incorrect — it does not return the last match.',takeaway:'findElement() → first match. findElements() → all matches.'},
    {id:'LOC-004',title:'Tag name',question:'Given:\n<input type="text">\n<input type="password">\n<button>Login</button>\n\nWhat does this statement return?\nList<WebElement> elements = driver.findElements(By.tagName("input"));',options:[['A','One element'],['B','Two elements'],['C','Three elements'],['D','Compilation error']],answer:['B'],expected:'The list contains 2 WebElements.',steps:'1. Selenium searches for elements with tag name input.\n2. It finds the text input.\n3. It finds the password input.\n4. It ignores the button.\n5. Both input elements are stored in the returned list.',concept:'HTML tag names describe element types: <input> is an input field, <button> is a button, <div> is a container, and <a> is a hyperlink.',optionReview:'A: Incorrect — there are two input elements.\nB: Correct — exactly two.\nC: Incorrect — the button is not an input.\nD: Incorrect — the code is valid.',takeaway:'By.tagName("input") matches input tags; use findElements() to retrieve all matches.'},
    {id:'LOC-005',title:'Link text',question:'Given:\n<a href="/register">Create New Account</a>\n\nWhich locator uses the complete visible link text?',options:[['A','By.linkText("Create New")'],['B','By.partialLinkText("Account")'],['C','By.linkText("Create New Account")'],['D','By.tagName("Create New Account")']],answer:['C'],expected:'Returns the anchor element representing the link.',steps:'1. Selenium identifies the anchor element.\n2. It checks the complete visible link text.\n3. The text matches "Create New Account".\n4. The link is returned.',concept:'linkText() locates links through their complete visible text. Example: driver.findElement(By.linkText("Create New Account"));',optionReview:'A: Incorrect — this is incomplete text for linkText().\nB: Incorrect for this question — it uses partial link text, not complete link text.\nC: Correct — the complete visible text matches.\nD: Incorrect — the tag name is a, not the visible text.',takeaway:'Complete link text → By.linkText(). Partial link text → By.partialLinkText().'},
    {id:'LOC-006',title:'Partial link text · select all that apply',multi:true,question:'Given:\n<a href="/forgot">Forgot Password?</a>\n\nWhich locators can identify this link? Select all that apply.',options:[['A','By.linkText("Forgot Password?")'],['B','By.partialLinkText("Forgot")'],['C','By.partialLinkText("Password")'],['D','By.linkText("Forgot")']],answer:['A','B','C'],expected:'All three valid locators can identify the same anchor element.',steps:'1. The complete visible text is "Forgot Password?".\n2. A searches for that exact complete text.\n3. B searches for the substring "Forgot".\n4. C searches for the substring "Password".\n5. D searches for complete text "Forgot", which does not match.',concept:'Partial link text locates an anchor using only a portion of its visible text.',optionReview:'A: Correct — complete text matches.\nB: Correct — "Forgot" is present in the link text.\nC: Correct — "Password" is present in the link text.\nD: Incorrect — linkText() requires the complete visible link text.',takeaway:'Partial text can match a substring; complete link text must match the full visible text.'},
    {id:'LOC-007',title:'Absolute XPath',question:'Given:\n<html>\n  <body>\n    <div>\n      <input id="search">\n    </div>\n  </body>\n</html>\n\nWhich is an absolute XPath for the input?',options:[['A',"//input[@id='search']"],['B','/html/body/div/input'],['C',"./input[@id='search']"],['D',"input[@id='search']"]],answer:['B'],expected:'The XPath identifies the input element through its full hierarchy.',steps:'1. Start from the root HTML element.\n2. Move to body.\n3. Move to div.\n4. Move to input.\nThe resulting XPath is /html/body/div/input.',concept:'Absolute XPath describes the complete path from the root of the document.',optionReview:'A: Incorrect — this is a relative XPath using //.\nB: Correct — it starts at the document root and follows the hierarchy.\nC: Incorrect — it starts from the current context.\nD: Incorrect — it does not provide a complete absolute path.',takeaway:'Absolute XPath generally starts with a single /.'},
    {id:'LOC-008',title:'Relative XPath',question:'Which XPath locates any input element having ID password, regardless of its position in the document hierarchy?',options:[['A',"/html/body/input[@id='password']"],['B',"//input[@id='password']"],['C',"/input[@id='password']"],['D',"./html/input[@id='password']"]],answer:['B'],expected:'The matching input element with ID password is returned.',steps:'1. // searches through descendants at any depth.\n2. input restricts the search to input elements.\n3. [@id=\'password\'] filters by the ID attribute.\n4. Selenium returns the matching element.',concept:'Relative XPath can identify elements without specifying the complete document hierarchy. //input[@id=\'password\'] is more flexible if the surrounding HTML structure changes.',optionReview:'A: Incorrect — it assumes a specific hierarchy.\nB: Correct — it searches at any descendant depth.\nC: Incorrect — it specifies a root-level input.\nD: Incorrect — it does not represent the intended document-wide search.',takeaway:'//input[@id=\'password\'] is a common relative XPath pattern.'},
    {id:'LOC-009',title:'XPath syntax',question:'What is the main difference between / and // in XPath?',options:[['A','Both always mean the same thing.'],['B','/ selects direct path steps; // searches through descendants at any depth.'],['C','/ searches all descendants; // selects only direct children.'],['D','// is used only for IDs.']],answer:['B'],expected:'There is no code output; this is a syntax and concept question.',steps:'Consider /html/body/div: each / follows a direct child step in the path.\nConsider //div: this searches for matching div elements among descendants at any depth.',concept:'/ means direct path navigation. // means descendant search.',optionReview:'A: Incorrect — they have different meanings.\nB: Correct.\nC: Incorrect — it reverses the meanings.\nD: Incorrect — // is not restricted to IDs.',takeaway:'Single slash / = direct path step. Double slash // = descendant search.'},
    {id:'LOC-010',title:'Locator strategies · select all that apply',multi:true,question:'Which statements about Selenium locators are correct? Select all that apply.',options:[['A','By.id() locates an element using its ID attribute.'],['B','By.name() can match multiple elements.'],['C','By.className() accepts multiple class names separated by spaces.'],['D','By.linkText() is intended for locating links using their complete visible text.']],answer:['A','B','D'],expected:'No code output. Statements A, B and D are correct.',steps:'A: ID locator searches by the ID attribute.\nB: Name attributes can be repeated across elements.\nC: By.className() accepts one class token.\nD: By.linkText() uses complete visible link text.',concept:'A locator tells Selenium how to identify an HTML element. Different locator strategies use different HTML attributes or element properties.',optionReview:'A: Correct.\nB: Correct.\nC: Incorrect — multiple classes separated by spaces are not accepted by By.className().\nD: Correct.',takeaway:'Know the difference between ID, name, class, tag and link-text strategies. These are frequently tested in Selenium MCQs.'},
    {id:'LOC-011',batch:2,title:'Duplicate IDs',question:'Given:\n<input id="city" value="Delhi">\n<input id="city" value="Mumbai">\n\nWebElement element = driver.findElement(By.id("city"));\n\nWhat is returned?',options:[['A','Selenium throws an exception because IDs must be unique.'],['B','Selenium returns the first matching element.'],['C','Selenium returns both elements.'],['D','Selenium returns the second matching element.']],answer:['B'],expected:'Returns the first input element, whose value is Delhi.',steps:'1. Selenium searches for id="city".\n2. It finds the first input.\n3. It finds another matching input.\n4. findElement() returns the first match in document order.',concept:'HTML IDs are intended to be unique, but browsers can still encounter invalid HTML containing duplicate IDs. Selenium does not automatically reject the page because of duplicate IDs.',optionReview:'A: Incorrect — Selenium does not enforce ID uniqueness.\nB: Correct — first matching element.\nC: Incorrect — findElements() returns both.\nD: Incorrect — it does not select the last match.',takeaway:'Even if IDs are duplicated, findElement() returns the first matching element.'},
    {id:'LOC-012',batch:2,title:'Multiple classes',question:'Given:\n<div class="container active highlighted">Welcome</div>\n\nWhich locator correctly identifies this element using its active class?',options:[['A','By.className("container active")'],['B','By.className("active")'],['C','By.className(".active")'],['D','By.className("#active")']],answer:['B'],expected:'Returns the div element.',steps:'1. The element has three classes.\n2. Selenium searches for the class token active.\n3. The element contains that class.\n4. Selenium returns it.',concept:'Class attributes can contain multiple class tokens separated by spaces. By.className() takes the class name without CSS punctuation.',optionReview:'A: Incorrect — multiple class tokens are supplied.\nB: Correct — single class token.\nC: Incorrect — . is CSS selector syntax, not class-name locator syntax.\nD: Incorrect — # is CSS ID syntax.',takeaway:'Use By.className("active"), not By.className(".active").'},
    {id:'LOC-013',batch:2,title:'Name and ID distinction · select all that apply',multi:true,question:'Given:\n<input id="loginField" name="userLogin">\n\nWhich two locators correctly identify the same element? Select all that apply.',options:[['A','By.id("loginField")'],['B','By.name("userLogin")'],['C','By.id("userLogin")'],['D','By.name("loginField")']],answer:['A','B'],expected:'Both A and B locate the same input element.',steps:'A searches for id="loginField".\nB searches for name="userLogin".\nBoth attributes belong to the same HTML element.',concept:'An element can have several attributes. Each locator searches the specific attribute named by its strategy.',optionReview:'A: Correct — ID matches.\nB: Correct — name matches.\nC: Incorrect — no element has that ID.\nD: Incorrect — no element has that name.',takeaway:'Match the locator to the correct HTML attribute. ID and name values are not interchangeable.'},
    {id:'LOC-014',batch:2,title:'Tag name matching',question:'Given:\n<h1>Welcome</h1>\n<h2>Dashboard</h2>\n<h2>Reports</h2>\n<p>Account details</p>\n\nList<WebElement> headings = driver.findElements(By.tagName("h2"));\n\nWhat is the size of the returned list?',options:[['A','1'],['B','2'],['C','3'],['D','4']],answer:['B'],expected:'2',steps:'1. Search for h2.\n2. Find Dashboard.\n3. Find Reports.\n4. Store both in the list.\n5. List size is 2.',concept:'findElements() returns a list. Its size() method tells you how many matching elements were found.',optionReview:'A: Incorrect — there are two h2 tags.\nB: Correct.\nC: Incorrect — the h1 is not an h2.\nD: Incorrect — the paragraph is not an h2.',takeaway:'Count matching HTML tags, not all visible headings or page elements.'},
    {id:'LOC-015',batch:2,title:'Partial link text',question:'Given:\n<a href="/products">View All Products</a>\n<a href="/services">View All Services</a>\n\ndriver.findElement(By.partialLinkText("View All"));\n\nWhat is the likely result?',options:[['A','Returns both links.'],['B','Returns the first matching link.'],['C','Throws an exception because the text is duplicated.'],['D','Returns the second matching link.']],answer:['B'],expected:'Returns the first anchor element: View All Products.',steps:'1. Selenium searches anchor elements.\n2. It checks for visible link text containing View All.\n3. Both links match.\n4. findElement() returns the first match.',concept:'Partial link text can match a substring shared by several links. findElement() still returns only one element.',optionReview:'A: Incorrect — findElement() does not return both.\nB: Correct.\nC: Incorrect — duplicate matching text does not automatically cause an exception.\nD: Incorrect — the first matching element is returned.',takeaway:'Partial text + multiple matches + findElement() = first match.'},
    {id:'LOC-016',batch:2,title:'Link text vs button text',question:'Given:\n<button>Login</button>\n<a href="/login">Login</a>\n\nWhich statement is correct?',options:[['A','By.linkText("Login") can locate the button.'],['B','By.linkText("Login") is intended to locate the anchor element.'],['C','By.partialLinkText("Login") locates both elements.'],['D','By.tagName("Login") locates both elements.']],answer:['B'],expected:'The anchor element is located, not the button.',steps:'1. Selenium applies the link-text strategy.\n2. It searches for an anchor link with visible text Login.\n3. It finds the <a> element.\n4. The button is not treated as a link.',concept:'An anchor element uses <a>. A button uses <button>. They may display identical text but are different HTML elements.',optionReview:'A: Incorrect — link-text locators are intended for links.\nB: Correct.\nC: Incorrect — partial link text does not turn buttons into links.\nD: Incorrect — Login is not an HTML tag name.',takeaway:'Link text locators are for anchor links, not ordinary buttons.'},
    {id:'LOC-017',batch:2,title:'Absolute XPath structure',previousAnswer:['B'],question:'Given:\n<html>\n  <body>\n    <div>\n      <section>\n        <button id="save">Save</button>\n      </section>\n    </div>\n  </body>\n</html>\n\nWhich is the correct absolute XPath for the button?',options:[['A','/html/body/div/section/button'],['B',"//button[@id='save']"],['C','//div/button'],['D',"/button[@id='save']"]],answer:['A'],expected:'A identifies the button using the complete path from the document root: /html/body/div/section/button.',steps:'1. Start at html.\n2. Move to its child body.\n3. Move to div.\n4. Move to section.\n5. Move to button.',concept:'An absolute XPath follows the entire hierarchy from the root. A relative XPath can search for an element without describing every parent.',optionReview:'A: Correct — complete root-based hierarchy.\nB: Incorrect for this question — valid relative XPath, but not absolute.\nC: Incorrect — it does not match the actual direct hierarchy because the button is inside section.\nD: Incorrect — the button is not a direct child of the root.',takeaway:'A valid XPath is not necessarily an absolute XPath. Check whether it starts at the document root and follows the complete hierarchy.'},
    {id:'LOC-018',batch:2,title:'Relative XPath flexibility',question:'Given:\n<div>\n  <section>\n    <form>\n      <input id="email">\n    </form>\n  </section>\n</div>\n\nWhich XPath locates the input without depending on its parent hierarchy?',options:[['A','/html/body/div/section/form/input'],['B',"//input[@id='email']"],['C','/div/input'],['D','./section/input']],answer:['B'],expected:'Returns the input with id="email".',steps:'1. // searches descendants.\n2. input identifies input elements.\n3. [@id=\'email\'] filters by ID.\n4. Selenium returns the match.',concept:'Relative XPath can avoid dependence on a long parent-child hierarchy. This often makes locators less sensitive to changes in page structure.',optionReview:'A: Incorrect — relies on a specific hierarchy.\nB: Correct.\nC: Incorrect — assumes a direct relationship between div and input.\nD: Incorrect — does not describe the actual path from the current context.',takeaway:'Use attribute-based relative XPath when the parent hierarchy is unnecessary.'},
    {id:'LOC-019',batch:2,title:'XPath path symbols',question:'Consider:\n/html/body/div\n\n//div\n\nWhich statement is correct?',options:[['A','Both always select exactly the same elements.'],['B','The first follows a specific root-based path; the second searches for matching descendant div elements.'],['C','The first is relative and the second is absolute.'],['D','Both are invalid XPath expressions.']],answer:['B'],expected:'No program output. This is a comparison of XPath expressions.',steps:'The first expression follows html, then body, then div. The second expression searches for div elements at descendant depth.',concept:'Absolute XPath is structural. Relative XPath can locate an element based on its tag or attributes without specifying its entire path.',optionReview:'A: Incorrect — the expressions can match different elements.\nB: Correct.\nC: Incorrect — the meanings are reversed.\nD: Incorrect — both are valid XPath expressions.',takeaway:'/html/body/div and //div are not interchangeable.'},
    {id:'LOC-020',batch:2,title:'Locator methods · select all that apply',multi:true,question:'Which statements about the locators covered so far are correct? Select all that apply.',options:[['A','findElement() returns a single WebElement even when multiple elements match.'],['B','findElements() returns a list of matching elements.'],['C','By.tagName("a") can locate anchor elements.'],['D','By.partialLinkText() is intended for matching visible text in any HTML element, including buttons.']],answer:['A','B','C'],expected:'No code output. A, B and C are correct.',steps:'A: findElement() returns one matching element.\nB: findElements() returns a list.\nC: a is the HTML tag for anchor links.\nD: Partial link text is for links, not arbitrary elements.',concept:'A locator strategy identifies elements. The retrieval method determines whether Selenium returns one element or a collection.',optionReview:'A: Correct.\nB: Correct.\nC: Correct.\nD: Incorrect — it is not a general-purpose text locator for buttons.',takeaway:'Distinguish locator strategy from retrieval method: By... identifies; findElement(s) retrieves.'},
    {id:'LOC-021',batch:3,title:'ID locator',question:'Given:\n<input id="customerEmail" name="email">\n\nWhich locator uses the id attribute?',options:[['A','By.name("customerEmail")'],['B','By.className("customerEmail")'],['C','By.id("customerEmail")'],['D','By.tagName("customerEmail")']],answer:['C'],expected:'Returns the input WebElement.',steps:'1. Selenium receives By.id("customerEmail").\n2. It searches for the ID attribute.\n3. It finds the matching input.\n4. findElement() returns that element.',concept:'HTML attributes have different purposes. Here, id and name are separate attributes, even though they belong to the same element.',optionReview:'A: Incorrect — searches the name attribute.\nB: Incorrect — searches the class attribute.\nC: Correct — searches the ID attribute.\nD: Incorrect — searches for a tag named customerEmail.',takeaway:'Always identify the exact HTML attribute before choosing a locator.'},
    {id:'LOC-022',batch:3,title:'Class locator',question:'Given:\n<p class="message success">Saved successfully</p>\n\nWhich statement correctly locates this paragraph using its success class?',options:[['A','driver.findElement(By.className("success"));'],['B','driver.findElement(By.className(".success"));'],['C','driver.findElement(By.className("message success"));'],['D','driver.findElement(By.id("success"));']],answer:['A'],expected:'Returns the paragraph WebElement.',steps:'1. The paragraph has two classes: message and success.\n2. Selenium searches for the success class.\n3. The paragraph matches.\n4. Selenium returns it.',concept:'An HTML class attribute can contain multiple class tokens. By.className() accepts one token without CSS punctuation.',optionReview:'A: Correct.\nB: Incorrect — the dot belongs to CSS selector syntax.\nC: Incorrect — two class names separated by a space are not accepted here.\nD: Incorrect — the element has no ID attribute.',takeaway:'By.className("success") is correct; By.className(".success") is not.'},
    {id:'LOC-023',batch:3,title:'Name locator',question:'Given:\n<input name="searchBox">\n<input name="searchBox">\n<input name="submitButton">\n\nList<WebElement> result = driver.findElements(By.name("searchBox"));\n\nWhat is the size of the returned list?',options:[['A','1'],['B','3'],['C','0'],['D','2']],answer:['D'],expected:'2',steps:'1. Selenium searches for name="searchBox".\n2. The first input matches.\n3. The second input matches.\n4. The third input does not match.\n5. The list contains two elements.',concept:'findElements() returns a list of all matching elements. Use result.size() to count them.',optionReview:'A: Incorrect — overlooks the second matching input.\nB: Incorrect — includes an element with a different name.\nC: Incorrect — two matches exist.\nD: Correct — two matching elements.',takeaway:'Count only elements matching the specified attribute and value.'},
    {id:'LOC-024',batch:3,title:'Tag name',question:'Given:\n<div>\n  <span>One</span>\n  <span>Two</span>\n  <span>Three</span>\n</div>\n\nWhich statement returns all three span elements?',options:[['A','driver.findElement(By.tagName("span"));'],['B','driver.findElements(By.tagName("span"));'],['C','driver.findElements(By.className("span"));'],['D','driver.findElement(By.name("span"));']],answer:['B'],expected:'A List<WebElement> containing three elements.',steps:'1. Selenium searches for the span tag.\n2. It finds One.\n3. It finds Two.\n4. It finds Three.\n5. All three are returned in the list.',concept:'By.tagName() searches by HTML tag. findElements() collects all matches.',optionReview:'A: Incorrect — returns only the first match.\nB: Correct — returns all three.\nC: Incorrect — span is being treated as a class name.\nD: Incorrect — span is being treated as a name attribute.',takeaway:'Tag locator identifies the tag; findElements() retrieves all matching tags.'},
    {id:'LOC-025',batch:3,title:'Complete link text',question:'Given:\n<a href="/profile">My User Profile</a>\n\nWhich statement correctly uses complete link text?',options:[['A','By.partialLinkText("My User")'],['B','By.linkText("User Profile")'],['C','By.tagName("My User Profile")'],['D','By.linkText("My User Profile")']],answer:['D'],expected:'Returns the anchor WebElement.',steps:'1. Selenium searches for an anchor link.\n2. It checks the complete visible text.\n3. My User Profile matches.\n4. The link is returned.',concept:'linkText() uses the complete visible text of an anchor element.',optionReview:'A: Uses partial link text, not complete link text.\nB: Incomplete text for linkText().\nC: Incorrect — visible text is not an HTML tag name.\nD: Correct.',takeaway:'Use the exact complete visible text with By.linkText().' },
    {id:'LOC-026',batch:3,title:'Partial link text',question:'Given:\n<a href="/help">Customer Support Center</a>\n\nWhich statement is correct?',options:[['A','By.partialLinkText("Support") can locate the link.'],['B','By.linkText("Support") must locate the link.'],['C','By.className("Support") locates the link based on visible text.'],['D','By.name("Support") locates the link based on visible text.']],answer:['A'],expected:'Returns the anchor element.',steps:'1. Selenium searches anchor links.\n2. It checks whether visible text contains Support.\n3. The link text contains that word.\n4. The element is returned.',concept:'Partial link text allows matching a portion of an anchor’s visible text.',optionReview:'A: Correct.\nB: Incorrect — Support is not the complete visible text.\nC: Incorrect — searches a class attribute.\nD: Incorrect — searches a name attribute.',takeaway:'Partial visible link text → By.partialLinkText().' },
    {id:'LOC-027',batch:3,title:'Absolute XPath',question:'Given:\n<html>\n  <body>\n    <main>\n      <div>\n        <p id="notice">Hello</p>\n      </div>\n    </main>\n  </body>\n</html>\n\nWhich expression is the correct absolute XPath?',options:[['A',"//p[@id='notice']"],['B','/html/body/main/div/p'],['C','//main/p'],['D',"/p[@id='notice']"]],answer:['B'],expected:'Identifies the paragraph through its complete root-based path: /html/body/main/div/p.',steps:'1. Start at html.\n2. Move to body.\n3. Move to main.\n4. Move to div.\n5. Move to p.',concept:'Absolute XPath specifies the complete hierarchy from the root element.',optionReview:'A: Valid relative XPath, not absolute.\nB: Correct absolute XPath.\nC: Relative XPath that does not describe the complete hierarchy.\nD: Incorrect hierarchy; the paragraph is not directly under the root.',takeaway:'Absolute XPath must represent the actual hierarchy from the root.'},
    {id:'LOC-028',batch:3,title:'Relative XPath',question:'Given:\n<div>\n  <article>\n    <section>\n      <button id="continue">Continue</button>\n    </section>\n  </article>\n</div>\n\nWhich XPath identifies the button using its ID without specifying the full hierarchy?',options:[['A','/html/body/div/article/section/button'],['B','/div/article/button'],['C',"//button[@id='continue']"],['D',"/button[@id='continue']"]],answer:['C'],expected:'Returns the button WebElement.',steps:'1. // searches descendants.\n2. button restricts the search to buttons.\n3. [@id=\'continue\'] filters by ID.\n4. The matching button is returned.',concept:'Relative XPath can identify an element using its own attributes without specifying all parent elements.',optionReview:'A: Absolute-style path and assumes a specific document hierarchy.\nB: Incorrect — it does not represent the actual parent-child structure.\nC: Correct.\nD: Incorrect — it assumes a root-level button.',takeaway:'Use //tag[@attribute=\'value\'] for a common attribute-based relative XPath.'},
    {id:'LOC-029',batch:3,title:'XPath hierarchy',question:'Consider:\n/html/body/main/div/button\n\nWhat happens if a new section element is inserted between div and button?',options:[['A','The XPath automatically adapts to the new hierarchy.'],['B','The XPath becomes a relative XPath.'],['C','The XPath still identifies the button because it uses the ID.'],['D','The XPath no longer matches the original hierarchy.']],answer:['D'],expected:'The XPath no longer matches the original path.',steps:'Original hierarchy: div > button.\nNew hierarchy: div > section > button.\nThe XPath expects button to be a direct child of div. It no longer is.',concept:'Absolute XPath is sensitive to changes in the DOM hierarchy. Adding or removing intermediate elements can break it.',optionReview:'A: Incorrect — XPath does not automatically adapt.\nB: Incorrect — its syntax does not change.\nC: Incorrect — the expression contains no ID condition.\nD: Correct.',takeaway:'Absolute XPath can break when the HTML hierarchy changes.'},
    {id:'LOC-030',batch:3,title:'XPath and basic locators · select all that apply',multi:true,question:'Which statements about XPath and basic Selenium locators are correct? Select all that apply.',options:[['A','An absolute XPath starts from the document root.'],['B','A relative XPath can locate an element using its attributes without specifying its complete hierarchy.'],['C','By.tagName("a") targets anchor elements.'],['D','By.linkText() is intended to locate buttons using their visible text.']],answer:['A','B','C'],expected:'No code output. Three statements are correct.',steps:'A: Absolute XPath follows a path from the root.\nB: Relative XPath can use element attributes.\nC: <a> is the HTML anchor tag.\nD: Link-text locators target links, not buttons.',concept:'XPath describes how to locate elements in the DOM. Basic Selenium locators use attributes, tag names or link text.',optionReview:'A: Correct.\nB: Correct.\nC: Correct.\nD: Incorrect — buttons are not anchor links.',takeaway:'Know both the XPath hierarchy and the difference between link locators and tag locators.'},
    {"id":"LOC-041","batch":4,"title":"XPath axes · output analysis","question":"Consider the following HTML:\n<div id=\"A\">\n    <section id=\"B\">\n        <input id=\"C\">\n        <span id=\"D\"></span>\n    </section>\n    <section id=\"E\">\n        <input id=\"F\">\n    </section>\n</div>\n\nWhat will this XPath expression select?\n//input[@id='C']/following::section","options":[["A","No element"],["B","Only section with ID E"],["C","Sections with IDs B and E"],["D","Section with ID B only"]],"answer":["B"],"expected":"The selected element is <section id=\"E\">.","steps":"1. Find the input with ID C.\n2. Move along the following axis.\n3. This axis includes elements after the input in document order.\n4. Section B is an ancestor, so it is excluded.\n5. Section E appears later, so it is selected.","concept":"following:: searches forward through document order, including elements at different DOM levels. It excludes ancestors and descendants of the context node.","optionReview":"A: Incorrect — section E exists after the input.\nB: Correct — section E is the following section.\nC: Incorrect — section B is an ancestor and is excluded.\nD: Incorrect — section B is not following the input.","takeaway":"Do not confuse following:: with following-sibling::. The former searches forward in document order; the latter only selects siblings."},
    {"id":"LOC-042","batch":4,"title":"XPath axes · multi-select","multi":true,"question":"Consider this HTML:\n<div id=\"container\">\n    <p id=\"p1\">First</p>\n    <span id=\"s1\"></span>\n    <p id=\"p2\">Second</p>\n    <div>\n        <p id=\"p3\">Third</p>\n    </div>\n</div>\n\nWhich expressions select both p1 and p2, but not p3? Select all that apply.","options":[["A","//div[@id='container']/child::p"],["B","//div[@id='container']/descendant::p"],["C","//p[@id='p2']/preceding-sibling::p"],["D","//p[@id='p1']/following-sibling::p"]],"answer":["A"],"expected":"Only option A returns both p1 and p2 without p3.","steps":"A selects direct p children p1 and p2.\nB selects every descendant p, including p3.\nC starts from p2 and returns only p1.\nD starts from p1 and returns only p2.","concept":"Evaluate each expression independently and compare the complete result set. C and D each return one paragraph; their results are not combined by the question.","optionReview":"A: Correct — child::p selects the two direct p children of the container.\nB: Incorrect — descendant::p also includes nested p3.\nC: Incorrect — returns only p1.\nD: Incorrect — returns only p2.","takeaway":"For multi-select XPath questions, test each expression separately. Do not combine results from separate choices."},
    {"id":"LOC-043","batch":4,"title":"XPath positional predicates","question":"Consider this HTML:\n<div>\n    <input id=\"i1\">\n    <input id=\"i2\">\n    <input id=\"i3\">\n    <input id=\"i4\">\n</div>\n\nWhat is the difference between these expressions?\n(//input)[2]\n\n//input[2]","options":[["A","Both always select the second input in the entire document."],["B","The first selects the second input in the document; the second selects the second input child of each matching parent."],["C","The first selects all inputs except the first; the second selects only the last input."],["D","Both expressions are invalid XPath."]],"answer":["B"],"expected":"In this particular HTML, both expressions select input i2.","steps":"(//input)[2] first collects the matching inputs, then selects the second overall.\n//input[2] selects an input that is the second matching input child of its parent.\nWith multiple parents, the second expression may return multiple elements.","concept":"Parentheses change the scope of the positional predicate: one position is applied to the complete result; the other is applied in each parent context.","optionReview":"A: Incorrect — the expressions can produce different results when there are multiple parents.\nB: Correct — this describes the global and per-parent positions.\nC: Incorrect — neither expression has that meaning.\nD: Incorrect — both are valid XPath.","takeaway":"Distinguish position in the complete result from position within each parent."},
    {"id":"LOC-044","batch":4,"title":"XPath contains()","question":"Given this HTML:\n<button>Click here to Continue application</button>\n\nWhich XPath locates a button whose visible text contains Continue, even if additional text appears before or after it?","options":[["A","//button[text()='Continue']"],["B","//button[starts-with(text(),'Continue')]"],["C","//button[contains(text(),'Continue')]"],["D","//button[@text()='Continue']"]],"answer":["C"],"expected":"The button is selected.","steps":"1. Locate the button.\n2. Read its text node.\n3. Check whether the text contains Continue.\n4. The condition succeeds because Continue occurs inside the text.","concept":"contains() checks whether a substring occurs anywhere within a value.","optionReview":"A: Incorrect — requires an exact text match.\nB: Incorrect — requires the text to begin with Continue.\nC: Correct — Continue occurs within the button text.\nD: Incorrect — text() is an XPath function, not an HTML attribute named text.","takeaway":"Use contains() for partial text matching."},
    {"id":"LOC-045","batch":4,"title":"XPath text matching · normalize-space()","multi":true,"question":"Consider this HTML:\n<div>\n    <button>Submit</button>\n    <button>Submit Form</button>\n    <button>Final Submit</button>\n    <button>Submission Complete</button>\n</div>\n\nWhich XPath expressions select exactly the first button only? Select all that apply.","options":[["A","//button[text()='Submit']"],["B","//button[contains(text(),'Submit')]"],["C","//button[starts-with(text(),'Submit')]"],["D","//button[normalize-space(text())='Submit']"]],"answer":["A","D"],"expected":"Options A and D both select only the first button.","steps":"A compares the exact text; only Submit matches.\nB is partial and also matches Submit Form and Final Submit.\nC matches text beginning with Submit, including Submit Form and Submission Complete.\nD normalizes whitespace, then compares exactly with Submit.","concept":"normalize-space() removes leading and trailing whitespace and collapses repeated whitespace inside a string. This helps exact text matching when HTML spacing is inconsistent.","optionReview":"A: Correct — exact text match.\nB: Incorrect — matches three buttons.\nC: Incorrect — matches three buttons.\nD: Correct — normalizes whitespace before exact comparison; it can match text such as a button containing padded spaces around Submit.","takeaway":"Do not overlook normalize-space() in exact-text questions, especially when the source HTML may contain inconsistent whitespace."},
    {"id":"LOC-046","batch":4,"title":"CSS attribute operators","multi":true,"question":"Consider these elements:\n<input id=\"user_login\">\n<input id=\"login_user\">\n<input id=\"user\">\n<input id=\"admin_login\">\n\nWhich CSS selectors match exactly two elements? Select all that apply.","options":[["A","input[id^='user']"],["B","input[id$='login']"],["C","input[id*='user']"],["D","input[id='user']"]],"answer":["A","B"],"expected":"A and B each match exactly two input elements.","steps":"A (^=) matches user_login and user.\nB ($=) matches user_login and admin_login.\nC (*=) matches user_login, login_user and user — three elements.\nD (=) matches only the ID user.","concept":"CSS attribute selectors support exact and partial matching: ^= starts with, $= ends with, *= contains, and = exact equality.","optionReview":"A: Correct — two IDs start with user.\nB: Correct — two IDs end with login.\nC: Incorrect — three IDs contain user.\nD: Incorrect — only one ID equals user.","takeaway":"Remember the CSS attribute operator mapping: ^= prefix, $= suffix, *= substring, = exact."},
    {"id":"LOC-047","batch":4,"title":"CSS sibling combinators","question":"Consider this HTML:\n<div id=\"parent\">\n    <span id=\"s1\"></span>\n    <p id=\"p1\">\n        <span id=\"s2\"></span>\n    </p>\n    <span id=\"s3\"></span>\n    <span id=\"s4\"></span>\n</div>\n\nWhich CSS selector selects s3 and s4, but not s1 or s2?","options":[["A","div#parent > span"],["B","div#parent span"],["C","p + span"],["D","p ~ span"]],"answer":["D"],"expected":"p ~ span selects s3 and s4.","steps":"1. Find the p element.\n2. Identify its following siblings.\n3. Both s3 and s4 are later siblings of p.\n4. s1 precedes p.\n5. s2 is inside p, so it is a descendant, not a sibling.","concept":"The + combinator selects the immediately following matching sibling. The ~ combinator selects all following matching siblings.","optionReview":"A: Incorrect — selects direct child spans s1, s3 and s4.\nB: Incorrect — selects all descendant spans, including s2.\nC: Incorrect — selects only the immediately following sibling s3.\nD: Correct — selects both following sibling spans s3 and s4.","takeaway":"Use ~ for all following siblings; use + only for the immediately following sibling."},
    {"id":"LOC-048","batch":4,"title":"XPath vs CSS · select all that apply","multi":true,"question":"Which statements about XPath and CSS selectors are correct? Select all that apply.","options":[["A","CSS selectors can locate elements using ID and class attributes."],["B","XPath supports traversing to parent elements using axes."],["C","CSS selectors support the following-sibling:: XPath axis directly."],["D","XPath can locate an element based on its visible text using text()."]],"answer":["A","B","D"],"expected":"Statements A, B and D are correct.","steps":"A: CSS supports #id and .class.\nB: XPath supports parent:: and ancestor::.\nC: following-sibling:: is XPath syntax; CSS uses combinators such as + and ~.\nD: XPath supports text matching through text().","concept":"XPath and CSS are both locator strategies, but their syntax and traversal features differ. Similar capabilities do not mean identical syntax.","optionReview":"A: Correct.\nB: Correct.\nC: Incorrect — following-sibling:: is an XPath axis, not CSS syntax.\nD: Correct.","takeaway":"CSS ~ is not written as XPath's following-sibling::. Know both the capability and its syntax."},
    {"id":"LOC-049","batch":4,"title":"Selenium locator debugging","question":"Java code:\nWebElement element = driver.findElement(\n    By.cssSelector(\"div > input[name='email']\")\n);\n\nHTML:\n<div id=\"form\">\n    <section>\n        <input name=\"email\">\n    </section>\n</div>\n\nWhat happens?","options":[["A","Selenium finds the input because it is a descendant of the div."],["B","Selenium throws NoSuchElementException because the input is not a direct child of the div."],["C","Selenium throws InvalidSelectorException because CSS does not support attribute selectors."],["D","Selenium finds the section instead of the input."]],"answer":["B"],"expected":"findElement() throws NoSuchElementException because no element matches the selector.","steps":"1. Selenium looks for a div.\n2. The > combinator requires a direct child input.\n3. The direct child is section.\n4. The input is nested inside section.\n5. No element matches the selector.","concept":"In CSS, a space means descendant at any depth. The > combinator means an immediate child only.","optionReview":"A: Incorrect — a descendant relationship is not enough for >.\nB: Correct — the input is not a direct child of the div, so findElement() finds no match.\nC: Incorrect — CSS supports attribute selectors.\nD: Incorrect — the selector asks for an input, not a section.","takeaway":"To find the nested input, use By.cssSelector(\"div input[name='email']\")."},
    {"id":"LOC-050","batch":4,"title":"XPath reverse-axis position · multi-select","multi":true,"question":"Consider this HTML:\n<div id=\"root\">\n    <section id=\"s1\">\n        <p id=\"p1\"></p>\n        <p id=\"p2\"></p>\n    </section>\n    <section id=\"s2\">\n        <p id=\"p3\"></p>\n    </section>\n</div>\n\nStarting from p2, which expressions select p1? Select all that apply.","options":[["A","./preceding-sibling::p"],["B","./ancestor::section/child::p[1]"],["C","./preceding::p[1]"],["D","./following-sibling::p"]],"answer":["A","B","C"],"expected":"A, B and C all select p1.","steps":"A: preceding-sibling::p finds p1.\nB: ancestor::section finds s1; its first p child is p1.\nC: preceding::p[1] selects the nearest preceding p, which is p1.\nD: following-sibling::p searches after p2 and does not select p1.","concept":"preceding is a reverse axis. Its positional predicate [1] selects the nearest preceding matching element, not the earliest one in document order.","optionReview":"A: Correct — selects preceding sibling p1.\nB: Correct — moves to section s1, then selects its first p child.\nC: Correct — selects the nearest preceding p, p1.\nD: Incorrect — searches following siblings.","takeaway":"Reverse-axis trap: preceding::p[1] is the nearest preceding p; following::p[1] is the first following p in document order."},
    {"id":"LOC-051","batch":5,"title":"XPath ancestor axis","multi":false,"question":"<div>\n    <p id=\"p1\">One</p>\n    <div>\n        <p id=\"p2\">Two</p>\n    </div>\n    <p id=\"p3\">Three</p>\n</div>\n\n\nWhat does this select?\n//p[@id='p2']/ancestor::div[1]","options":[["A","The outermost div"],["B","The nearest ancestor div containing p2"],["C","Both div elements"],["D","No element"]],"answer":["B"],"expected":"The inner div, which directly contains p2.","steps":"1. Locate p2.\n2. ancestor::div finds its ancestor div elements.\n3. There are two: the inner div and the outer div.\n4. ancestor is a reverse axis, so [1] selects the nearest matching ancestor.","concept":"XPath axes have direction. For reverse axes such as ancestor, positional predicate [1] selects the nearest matching element.","optionReview":"A — Incorrect: this is the outermost ancestor.\nB — Correct: the nearest ancestor is the inner div.\nC — Incorrect: [1] restricts the result to one element.\nD — Incorrect: two matching ancestors exist.","takeaway":"ancestor::div[1] means nearest ancestor div. Be especially careful with [1] on reverse axes."},
    {"id":"LOC-052","batch":5,"title":"XPath reverse-axis position","multi":false,"question":"<div>\n    <p id=\"p1\"></p>\n    <p id=\"p2\"></p>\n    <p id=\"p3\"></p>\n    <p id=\"p4\"></p>\n</div>\n\n\nStarting from p4, what does this select?\n./preceding-sibling::p[2]","options":[["A","p1"],["B","p2"],["C","p3"],["D","p4"]],"answer":["B"],"expected":"p2.","steps":"Starting at p4:\n1. The nearest preceding p is p3.\n2. The second nearest preceding p is p2.\n3. Therefore [2] selects p2.","concept":"preceding-sibling is a reverse axis. Its positions are counted backwards from the context element.","optionReview":"A — Incorrect: third preceding sibling.\nB — Correct: second preceding sibling.\nC — Incorrect: first preceding sibling.\nD — Incorrect: the context element is not its own preceding sibling.","takeaway":"For preceding-sibling::p[2], count backwards, not from the beginning of the HTML."},
    {"id":"LOC-053","batch":5,"title":"XPath starts-with and contains","multi":true,"question":"<input id=\"user_123\" name=\"username\">\n<input id=\"admin_456\" name=\"admin\">\n<input id=\"user_789\" name=\"user\">\n\n\nWhich expressions select the first and third inputs, but not the second?","options":[["A","//input[starts-with(@id,'user')]"],["B","//input[contains(@id,'user')]"],["C","//input[contains(@name,'user')]"],["D","//input[starts-with(@name,'user')]"]],"answer":["A","B","C","D"],"expected":"All four expressions select the first and third inputs only.","steps":"- A: IDs user_123 and user_789 start with user.\n- B: Both IDs contain user.\n- C: Both names, username and user, contain user.\n- D: Both names start with user.","concept":"starts-with() checks the beginning of a string. contains() checks whether a substring appears anywhere.","optionReview":"A — Correct.\nB — Correct.\nC — Correct.\nD — Correct.","takeaway":"Always inspect the actual attribute values. A question can have multiple valid expressions even when they use different functions or attributes."},
    {"id":"LOC-054","batch":5,"title":"XPath whitespace handling","multi":false,"question":"<button>\n    Submit\n</button>\n\n\nWhich XPath is most suitable when whitespace around the text may vary?","options":[["A","//button[text()='Submit']"],["B","//button[normalize-space(.)='Submit']"],["C","//button[contains(@id,'Submit')]"],["D","//button[starts-with(@id,'Submit')]"]],"answer":["B"],"expected":"The button is selected.","steps":"1. //button finds button elements.\n2. . refers to the string value of the current element, including descendant text.\n3. normalize-space(.) trims leading and trailing whitespace and collapses internal whitespace.\n4. The resulting text equals Submit.","concept":". refers to the current context node. text() selects direct text nodes. normalize-space(.) is often more robust when text may contain whitespace or nested elements.","optionReview":"A — Incorrect for this whitespace-sensitive scenario: exact text-node comparison can fail.\nB — Correct: normalises whitespace before comparing.\nC — Incorrect: checks an ID attribute, not visible text.\nD — Incorrect: also checks an ID attribute, not visible text.","takeaway":"For reliable text matching where spacing may vary, consider normalize-space(.)."},
    {"id":"LOC-055","batch":5,"title":"CSS selectors","multi":true,"question":"<input type=\"text\" id=\"username\" class=\"form-control active\">\n<input type=\"password\" id=\"password\" class=\"form-control\">\n<button id=\"login\" class=\"active\"></button>\n\n\nWhich selectors match exactly the first input?","options":[["A","input.form-control.active"],["B","input[type='text'][id='username']"],["C",".form-control"],["D","input#username"]],"answer":["A","B","D"],"expected":"A, B and D each select only the first input.\n\nC selects both the first and second inputs.","steps":"- A requires an input with both classes form-control and active.\n- B requires an input with both specified attributes.\n- C selects any element with class form-control, regardless of tag.\n- D requires an input with ID username.","concept":"CSS selectors can combine conditions. Multiple class selectors without spaces mean the same element must have all those classes.","optionReview":"A — Correct: only the first input has both classes.\nB — Correct: only the first input has both attributes.\nC — Incorrect: matches two inputs.\nD — Correct: only the first input has that ID.","takeaway":"A space changes the meaning of CSS selectors. For example:\n- .form-control.active means one element having both classes.\n- .form-control .active means an element with class active nested inside an element with class form-control."},
    {"id":"LOC-056","batch":5,"title":"CSS adjacent sibling","multi":false,"question":"<div id=\"main\">\n    <section id=\"s1\">\n        <p id=\"p1\"></p>\n    </section>\n    <section id=\"s2\"></section>\n    <p id=\"p2\"></p>\n</div>\n\n\nWhat does this selector match?\nsection + p","options":[["A","p1 only"],["B","p2 only"],["C","Both p1 and p2"],["D","No paragraph"]],"answer":["B"],"expected":"Only p2.","steps":"1. Find a section.\n2. Find a p that is its immediately following sibling.\n3. s1 is followed by another section, not a paragraph.\n4. s2 is immediately followed by p2.","concept":"5. Concept from basics\n\nThe + CSS combinator selects an immediately following sibling.","optionReview":"A — Incorrect: p1 is a descendant of a section.\nB — Correct: p2 immediately follows s2.\nC — Incorrect: p1 does not match.\nD — Incorrect: p2 matches.","takeaway":"The adjacent sibling selector + does not search inside an element. It only checks the next sibling."},
    {"id":"LOC-057","batch":5,"title":"XPath vs CSS capabilities","multi":true,"question":"Which statements are correct?","options":[["A","XPath can navigate from a child to its parent."],["B","CSS selectors can use ^= to match attribute values beginning with a specified string."],["C","XPath supports matching elements based on their text content."],["D","CSS selectors support arbitrary ancestor traversal equivalent to XPath's ancestor:: axis."]],"answer":["A","B","C"],"expected":"A, B and C are correct.","steps":"- A: XPath parent:: navigates to an immediate parent.\n- B: CSS [attribute^='value'] matches values starting with the specified string.\n- C: XPath text() can match element text.\n- D: CSS does not provide arbitrary ancestor traversal equivalent to XPath's ancestor:: axis.","concept":"XPath offers more extensive DOM navigation through axes. CSS supports many useful relationships, but its combinators do not provide unrestricted ancestor-axis traversal.","optionReview":"A — Correct.\nB — Correct.\nC — Correct.\nD — Incorrect: CSS has child, descendant and sibling combinators, but not a general ancestor axis.","takeaway":"Don't assume CSS can do everything XPath can do. In particular, arbitrary parent/ancestor traversal and text-node matching are important XPath strengths."},
    {"id":"LOC-058","batch":5,"title":"XPath positional scope","multi":false,"question":"<div>\n    <ul>\n        <li id=\"a\"></li>\n        <li id=\"b\"></li>\n    </ul>\n    <ul>\n        <li id=\"c\"></li>\n        <li id=\"d\"></li>\n    </ul>\n</div>\n\n\nWhat does this XPath select?\n//li[1]","options":[["A","Only a"],["B","Only c"],["C","a and c"],["D","a and b"]],"answer":["C"],"expected":"The selected elements are a and c.","steps":"1. Find all li elements.\n2. Apply the positional predicate [1] to the li child relationship.\n3. Each ul has two li children.\n4. The first li of the first ul is a.","concept":"5. Concept from basics\n\n//li[1] is not the same as (//li)[1].\n- //li[1] selects the first matching li under each relevant parent.\n- (//li)[1] selects only the first li from the overall result.","optionReview":"A — Incorrect: misses c.\nB — Incorrect: misses a.\nC — Correct: first li in each ul.\nD — Incorrect: b is the second li in its parent.","takeaway":"Parentheses change positional scope. This is a frequent advanced XPath question."},
    {"id":"LOC-059","batch":5,"title":"Selenium findElements()","multi":false,"question":"List<WebElement> elements =\n    driver.findElements(By.cssSelector(\"input.required\"));\n\nSystem.out.println(elements.size());\n\n\nIf no element matches the selector, what happens?","options":[["A","NoSuchElementException is thrown."],["B","InvalidSelectorException is thrown."],["C","An empty list is returned and 0 is printed."],["D","null is returned and a NullPointerException occurs."]],"answer":["C"],"expected":"0","steps":"1. findElements() searches for all matching elements.\n2. No matching element is found.\n3. Selenium returns an empty list.\n4. elements.size() returns 0.","concept":"5. Concept from basics\n\nfindElement() returns one matching element and throws NoSuchElementException if none is found.\n\nfindElements() returns a list and gives an empty list when there are no matches.","optionReview":"A — Incorrect: this is the usual behaviour of findElement().\nB — Incorrect: the selector is valid.\nC — Correct.\nD — Incorrect: an empty list is not null.","takeaway":"Method\tNo match\nfindElement()\tNoSuchElementException\nfindElements()\tEmpty list"},
    {"id":"LOC-060","batch":6,"title":"XPath axes","multi":true,"question":"<div id=\"root\">\n    <section id=\"s1\">\n        <p id=\"p1\"></p>\n        <span id=\"s2\"></span>\n        <p id=\"p3\"></p>\n    </section>\n    <section id=\"s4\">\n        <p id=\"p5\"></p>\n    </section>\n</div>\n\n\nStarting from the element with ID p3, which expressions select s1?","options":[["A","./parent::section"],["B","./ancestor::section"],["C","./preceding-sibling::section"],["D","./ancestor::div"]],"answer":["A","B"],"expected":"Both expressions select section s1.","steps":"- A: Moves from p3 to its immediate parent, section s1.\n- B: Finds all ancestor sections of p3; here, that is s1.\n- C: Searches for preceding sibling sections of p3; there are none.\n- D: Selects the ancestor div with ID root, not section s1.","concept":"parent:: selects one immediate parent. ancestor:: can select any matching ancestor level.","optionReview":"A — Correct.\nB — Correct.\nC — Incorrect: p3 has no preceding sibling section.\nD — Incorrect: selects the root div rather than the requested section.","takeaway":"If the required element is the immediate parent, parent:: is more specific. If it could be higher in the DOM, use ancestor::.\n\nUpdated progress register\nBatch 2\n7/10\nBatch 1\n7/10\n\nCombined performance\n14/20\n70% across the two reviewed batches\nQuestion IDs\tStatus\nLOC-041–050\tReviewed\nLOC-051–060\tReviewed\nLOC-031–040\tExcluded as repetitive\nDefective questions in these two batches\tNone identified\n\n\nConcepts to revise before moving ahead:\n1. Reverse-axis predicates: ancestor::div[1] and preceding-sibling::p[2].\n2. CSS multiple-class and attribute selectors.\n3. CSS + vs ~ and XPath ancestor navigation.\nOne unresolved detail: Batch 1 Q2 is still recorded as incorrect because your submitted answer was A, C and D. If you intended A only, tell me and I'll adjust that earlier score.\n\nNext, we can move to the final three Locator topics: CSS vs XPath, dynamic elements and locators, and multiple matching elements."},
    {"id":"LOC-061","batch":6,"title":"XPath ancestor axis","multi":false,"question":"<div id=\"outer\">\n    <section id=\"s1\">\n        <div id=\"inner\">\n            <input id=\"username\">\n        </div>\n    </section>\n</div>\n\n\nWhat does this XPath select?\n//input[@id='username']/ancestor::div[1]","options":[["A","outer"],["B","s1"],["C","inner"],["D","Both outer and inner"]],"answer":["C"],"expected":"The selected element is <div id=\"inner\">.","steps":"1. Locate the input with ID username.\n2. Find its ancestor elements that are div.\n3. The matching ancestors are inner and outer.\n4. ancestor is a reverse axis.","concept":"5. Concept from basics\n\nancestor:: searches upwards through the DOM hierarchy. On this reverse axis, [1] means the nearest matching ancestor.","optionReview":"A — Incorrect: outer is farther away.\nB — Incorrect: s1 is a section, not a div.\nC — Correct: inner is the nearest ancestor div.\nD — Incorrect: [1] selects one element.","takeaway":"ancestor::div[1] means the nearest ancestor div, not the outermost one."},
    {"id":"LOC-062","batch":6,"title":"XPath reverse axis and wildcard","multi":false,"question":"<div>\n    <p id=\"p1\"></p>\n    <span id=\"s1\"></span>\n    <p id=\"p2\"></p>\n    <p id=\"p3\"></p>\n</div>\n\n\nStarting from p3, what does this select?\n./preceding-sibling::*[2]","options":[["A","p1"],["B","s1"],["C","p2"],["D","p3"]],"answer":["B"],"expected":"The selected element is <span id=\"s1\">.","steps":"Starting at p3:\n1. preceding-sibling::* finds all preceding element siblings, regardless of tag.\n2. In reverse-axis order, the nearest is p2.\n3. The second nearest is s1.\n4. Therefore [2] selects s1.","concept":"The wildcard * means any element. The preceding-sibling axis moves backwards through siblings.","optionReview":"A — Incorrect: p1 is third in reverse order.\nB — Correct: s1 is second in reverse order.\nC — Incorrect: p2 is first.\nD — Incorrect: p3 is the context element, not its preceding sibling.","takeaway":"Always check whether the XPath uses * or a specific tag. Here, * means the intervening span counts in the position."},
    {"id":"LOC-063","batch":6,"title":"XPath axes","multi":true,"question":"<div id=\"root\">\n    <section id=\"s1\">\n        <p id=\"p1\"></p>\n        <span id=\"sp1\"></span>\n    </section>\n    <section id=\"s2\">\n        <p id=\"p2\"></p>\n    </section>\n</div>\n\n\nStarting from p2, which expressions select s2?","options":[["A","./parent::section"],["B","./ancestor::section[1]"],["C","./preceding-sibling::section"],["D","./ancestor::div"]],"answer":["A","B"],"expected":"Both expressions select section s2.","steps":"- A: Moves to the immediate parent, which is s2.\n- B: Finds ancestor sections; the nearest one is s2.\n- C: Searches for preceding sibling sections of p2; its siblings are not sections.\n- D: Finds the ancestor div root.","concept":"parent:: moves exactly one level upwards. ancestor:: searches all levels upwards.","optionReview":"A — Correct.\nB — Correct.\nC — Incorrect: no preceding sibling section exists for p2.\nD — Incorrect: returns the root div.","takeaway":"parent:: and ancestor::... [1] can produce the same result when the immediate parent is the required element."},
    {"id":"LOC-064","batch":6,"title":"XPath functions: defective single-correct question","multi":true,"question":"<input id=\"customer_123\">\n<input id=\"123_customer\">\n<input id=\"customer\">\n\n\nWhich XPath selects only the first and third inputs?","options":[["A","//input[contains(@id,'customer')]"],["B","//input[starts-with(@id,'customer')]"],["C","//input[ends-with(@id,'customer')]"],["D","//input[@id='customer']"]],"answer":["A","B"],"expected":"- A selects the first and third inputs.\n- B also selects the first and third inputs.","steps":"- A: Both customer_123 and customer contain customer.\n- B: Both customer_123 and customer begin with customer.\n- C: ends-with() is not part of XPath 1.0, which Selenium's standard XPath support uses.\n- D: Selects only the third input.","concept":"contains() checks for a substring anywhere. starts-with() checks only the beginning.","optionReview":"A — Correct: selects first and third.\nB — Correct: also selects first and third.\nC — Not valid in standard XPath 1.0.\nD — Incorrect: selects only the third.","takeaway":"A single-correct question must have exactly one valid answer. This one had two. Your B answer is valid, and the question will not reduce your score."},
    {"id":"LOC-065","batch":6,"title":"XPath text and whitespace","multi":true,"question":"<button>  Login  </button>\n<button>Login Now</button>\n<button>Click Login</button>\n<button>Logout</button>\n\n\nWhich expressions select only the first button?","options":[["A","//button[normalize-space(.)='Login']"],["B","//button[contains(.,'Login')]"],["C","//button[starts-with(normalize-space(.),'Login')]"],["D","//button[normalize-space(text())='Login']"]],"answer":["A","D"],"expected":"Both expressions select only the first button.","steps":"- A normalises the entire string value of the button and compares it with Login.\n- B matches the first, second and third buttons.\n- C matches the first and second buttons.\n- D normalises the button's direct text node and compares it exactly with Login.","concept":". represents the current element's string value, including descendant text. text() selects direct text-node children.","optionReview":"A — Correct: whitespace is normalised and text is compared exactly.\nB — Incorrect: partial match.\nC — Incorrect: beginning match also includes Login Now.\nD — Correct: normalises direct text and compares exactly.","takeaway":"Use normalize-space(.) when you want to match the full text of an element, including text nested inside child elements. normalize-space(text()) is useful when the relevant text is directly inside the element."},
    {"id":"LOC-066","batch":6,"title":"CSS attribute selectors","multi":false,"question":"<input id=\"user_name\">\n<input id=\"admin_user\">\n<input id=\"username\">\n<input id=\"user_admin\">\n\n\nWhich selectors match exactly two elements?","options":[["A","input[id^='user']"],["B","input[id$='user']"],["C","input[id*='user']"],["D","input[id*='admin']"]],"answer":["D"],"expected":"D selects admin_user and user_admin.","steps":"- A matches IDs starting with user: user_name, username, user_admin — three.\n- B matches IDs ending with user: admin_user — one.\n- C matches IDs containing user — all four.\n- D matches IDs containing admin: admin_user and user_admin — two.","concept":"CSS attribute selectors can check whether an attribute starts with, ends with, contains, or exactly equals a value.","optionReview":"A — Incorrect: three matches.\nB — Incorrect: one match.\nC — Incorrect: four matches.\nD — Correct: exactly two matches.","takeaway":"Count actual matches instead of relying on the appearance of a selector. The *= operator is particularly easy to miscount."},
    {"id":"LOC-067","batch":6,"title":"CSS sibling combinators","multi":false,"question":"<div id=\"container\">\n    <h2 id=\"heading\"></h2>\n    <p id=\"p1\"></p>\n    <span id=\"s1\"></span>\n    <p id=\"p2\"></p>\n</div>\n\n\nWhat does this CSS selector match?\nh2 ~ p","options":[["A","Only p1"],["B","Only p2"],["C","Both p1 and p2"],["D","No element"]],"answer":["C"],"expected":"Both p1 and p2.","steps":"1. Find the h2.\n2. Find all following sibling elements that are p.\n3. p1 is a following sibling.\n4. p2 is also a following sibling, even though a span comes between them.","concept":"5. Concept from basics\n\nThe general sibling combinator ~ selects all matching following siblings, not just the immediately next one.","optionReview":"A — Incorrect: misses p2.\nB — Incorrect: misses p1.\nC — Correct.\nD — Incorrect: matching paragraphs exist.","takeaway":"h2 + p would select only the immediately following paragraph p1. h2 ~ p selects both paragraphs."},
    {"id":"LOC-068","batch":6,"title":"CSS vs XPath","multi":true,"question":"Which statements are correct?","options":[["A","XPath can locate an element using exact visible text."],["B","CSS supports matching an element using a partial attribute value."],["C","XPath supports the ancestor axis."],["D","CSS supports the XPath preceding-sibling:: axis using identical syntax."]],"answer":["A","B","C"],"expected":"A, B and C are correct.","steps":"- A: XPath can use text() to compare element text.\n- B: CSS can use operators such as *=, ^= and $=.\n- C: XPath supports ancestor::.\n- D: CSS has sibling combinators, but not XPath's axis syntax.","concept":"XPath and CSS overlap in many locator capabilities, but they have different navigation models and syntax.","optionReview":"A — Correct.\nB — Correct.\nC — Correct.\nD — Incorrect: CSS does not use preceding-sibling::.","takeaway":"CSS + and ~ select following siblings. They are not identical to XPath's preceding-sibling:: axis."},
    {"id":"LOC-069","batch":6,"title":"Dynamic elements","multi":false,"question":"A web application generates IDs such as:\n<input id=\"emp_78421_name\">\n<input id=\"emp_92635_name\">\n\n\nThe numeric portion changes on every page load, but the prefix emp_ and suffix _name remain stable.\n\nWhich CSS selector matches both elements?","options":[["A","input[id='emp_*_name']"],["B","input[id^='emp_'][id$='_name']"],["C","input[id*='emp_'][id='_name']"],["D","input[id$='emp_'][id^='_name']"]],"answer":["B"],"expected":"Both inputs are selected.","steps":"1. input restricts the selection to input elements.\n2. [id^='emp_'] checks that the ID starts with emp_.\n3. [id$='_name'] checks that the ID ends with _name.\n4. Both inputs satisfy both conditions.","concept":"Dynamic IDs often contain a variable section and stable sections. You can combine CSS attribute conditions to match the stable parts.","optionReview":"A — Incorrect: CSS does not treat * as a wildcard inside an exact attribute value.\nB — Correct: checks both stable parts.\nC — Incorrect: requires the entire ID to equal _name.\nD — Incorrect: reverses the required beginning and ending conditions.","takeaway":"Combine attribute selectors when the beginning and ending of an attribute are stable but its middle changes."},
    {"id":"LOC-070","batch":7,"title":"Multiple matching elements and Java output","multi":false,"question":"HTML:\n<button class=\"action\">Save</button>\n<button class=\"action\">Cancel</button>\n<button class=\"action\">Submit</button>\n\n\nJava:\nList<WebElement> elements =\n    driver.findElements(By.className(\"action\"));\n\nSystem.out.println(elements.get(1).getText());\nSystem.out.println(elements.size());\n\n\nWhat is the output?","options":[["A","Save 3"],["B","Cancel 3"],["C","Cancel 2"],["D","IndexOutOfBoundsException"]],"answer":["B"],"expected":"Cancel\n3","steps":"1. findElements() finds all three buttons.\n2. They are stored in document order in the list.\n3. elements.get(1) accesses the second element because Java list indexes start at zero.\n4. The second button's text is Cancel.","concept":"5. Concept from basics\n\nJava lists use zero-based indexing:\nIndex\tButton\n0\tSave\n1\tCancel\n2\tSubmit","optionReview":"A — Incorrect: get(1) returns Cancel, not Save.\nB — Correct: Cancel and three elements.\nC — Incorrect: there are three elements.\nD — Incorrect: index 1 exists.","takeaway":"Whenever you see findElements() followed by .get(n), remember that n is zero-based. Also, .size() counts all matching elements.\n\nBatch 1 assessment record\n8/9\nValid questions only — 88.9%\n\nMeasure\tResult\nQuestions reviewed\t10\nCorrect\t8\nIncorrect\t1\nDefective/excluded\t1\nReconstructed questions\t0\n\nGenuine error: LOC-070. Defective item: LOC-064.\n\nNext batch\nThe next ten questions will be LOC-071 to LOC-080. I'll increase the variety and difficulty, especially in:\n- XPath reverse-axis and predicate evaluation.\n- Dynamic locator strategies.\n- CSS combinator and attribute-selector combinations.\n- Selenium findElement() / findElements() behaviour.\n- Stale elements and DOM updates.\nYour first batch is strong. Let's see whether that accuracy holds across the remaining 40 questions."},
    {"id":"LOC-071","batch":7,"title":"XPath reverse axis","multi":false,"question":"<div>\n    <section id=\"s1\">\n        <p id=\"p1\"></p>\n    </section>\n    <section id=\"s2\">\n        <p id=\"p2\"></p>\n    </section>\n</div>\n\n\nStarting from p2, what does this expression select?\n./preceding::section[1]","options":[["A","s1"],["B","s2"],["C","Both s1 and s2"],["D","No element"]],"answer":["A"],"expected":"section s1.","steps":"1. Start from p2.\n2. preceding::section searches for section elements before p2 in document order.\n3. s1 is before p2.\n4. s2 is an ancestor of p2, so it is excluded from the preceding axis.","concept":"5. Concept from basics\n\npreceding:: selects elements earlier in document order, excluding ancestors. It is a reverse axis, so [1] selects the nearest matching preceding element.","optionReview":"A — Correct: s1 is the nearest preceding section.\nB — Incorrect: s2 is an ancestor of p2.\nC — Incorrect: s2 is excluded and [1] selects one result.\nD — Incorrect: s1 exists before p2.","takeaway":"Remember the difference:\n- preceding::section[1] = nearest preceding section, excluding ancestors.\n- ancestor::section[1] = nearest ancestor section.\n- preceding-sibling::section[1] = nearest preceding sibling section."},
    {"id":"LOC-072","batch":7,"title":"XPath following axis","multi":false,"question":"<div>\n    <p id=\"p1\"></p>\n    <section>\n        <span id=\"s1\"></span>\n    </section>\n    <p id=\"p2\"></p>\n</div>\n\n\nStarting from p1, what does this XPath select?\n./following::p[1]","options":[["A","p1"],["B","p2"],["C","No element"],["D","Both paragraphs"]],"answer":["B"],"expected":"p2.","steps":"1. Start at p1.\n2. following::p finds paragraph elements after p1 in document order.\n3. p2 is the only following paragraph.\n4. [1] selects it.","concept":"following:: searches forward through document order, excluding descendants.","optionReview":"A — Incorrect: p1 is the context element.\nB — Correct.\nC — Incorrect: p2 exists.\nD — Incorrect: [1] selects one matching paragraph.","takeaway":"following::p[1] means the first following paragraph, not the first paragraph in the whole document."},
    {"id":"LOC-073","batch":7,"title":"XPath text matching","multi":true,"question":"<button>Submit</button>\n<button>Submit Form</button>\n<button>Final Submit</button>\n<button> Cancel </button>\n\n\nWhich expressions select exactly the first button?","options":[["A","//button[text()='Submit']"],["B","//button[normalize-space(.)='Submit']"],["C","//button[contains(.,'Submit')]"],["D","//button[starts-with(normalize-space(.),'Submit') and string-length(normalize-space(.))=6]"]],"answer":["A","B","D"],"expected":"All three expressions select only the first button.","steps":"- A: exact text comparison matches Submit.\n- B: normalises whitespace, then performs exact comparison.\n- C: matches all three buttons containing Submit.\n- D: checks that text starts with Submit and has length six. Only the first button meets both conditions.","concept":"XPath functions can be combined using logical operators. Here, and requires both conditions to be true.","optionReview":"A — Correct: exact text match.\nB — Correct: whitespace-normalised exact match.\nC — Incorrect: also matches Submit Form and Final Submit.\nD — Correct: the text begins with Submit and has exactly six characters.","takeaway":"A locator can combine starts-with(), string-length() and and to create a more precise condition."},
    {"id":"LOC-074","batch":7,"title":"CSS positional selectors","multi":false,"question":"<div>\n    <p id=\"p1\"></p>\n    <span id=\"s1\"></span>\n    <p id=\"p2\"></p>\n    <p id=\"p3\"></p>\n</div>\n\n\nWhich selector selects only p2?","options":[["A","p:nth-child(2)"],["B","p:nth-of-type(2)"],["C","p:first-child"],["D","p:last-child"]],"answer":["B"],"expected":"p2.","steps":"The child sequence is:\n1. p1 — first child\n2. s1 — second child\n3. p2 — third child\n4. p3 — fourth child\nBut among p elements, p2 is the second paragraph.","concept":"- :nth-child(n) counts all element siblings.\n- :nth-of-type(n) counts only siblings of the same tag type.","optionReview":"A — Incorrect: the second child is a span.\nB — Correct: p2 is the second paragraph.\nC — Incorrect: p1 is the first child.\nD — Incorrect: p3 is the last child.","takeaway":"When different tags are mixed together, be careful about nth-child() versus nth-of-type()."},
    {"id":"LOC-075","batch":7,"title":"CSS vs XPath","multi":true,"question":"<div id=\"form\">\n    <label>Email</label>\n    <input id=\"email\">\n</div>\n\n\nWhich statements are correct?","options":[["A","//input[@id='email']/parent::div selects the parent div."],["B","#email selects the input using CSS."],["C","input:parent is a standard CSS selector for selecting the parent div."],["D","//label[text()='Email']/following-sibling::input selects the input."]],"answer":["A","B","D"],"expected":"A, B and D are correct.","steps":"- A: Finds the email input and moves to its parent div.\n- B: #email is a CSS ID selector.\n- C: :parent is not a standard CSS pseudo-class.\n- D: Finds the label with exact text Email, then selects its following sibling input.","concept":"XPath axes allow navigation between related elements. CSS uses simpler selectors and combinators.","optionReview":"A — Correct.\nB — Correct.\nC — Incorrect: no standard CSS :parent pseudo-class.\nD — Correct: the label and input are siblings.","takeaway":"Know the difference between XPath axes and CSS pseudo-classes. Don't confuse parent:: with a CSS pseudo-class."},
    {"id":"LOC-076","batch":7,"title":"Dynamic locators","multi":false,"question":"<button id=\"submit_83921\">Submit</button>\n<button id=\"submit_72845\">Submit</button>\n\n\nThe ID always starts with submit_, but the numeric part changes. Which locator finds both buttons?","options":[["A","By.id(\"submit_83921\")"],["B","By.cssSelector(\"button[id^='submit_']\")"],["C","By.cssSelector(\"button[id='submit_*']\")"],["D","By.xpath(\"//button[@id='submit_']\")"]],"answer":["B"],"expected":"Both buttons are found.","steps":"1. button restricts the match to button elements.\n2. [id^='submit_'] requires the ID to start with submit_.\n3. Both IDs satisfy the condition.\n4. The selector matches both buttons.","concept":"Dynamic IDs often contain changing values. Stable prefixes or suffixes can be used instead of hardcoding the entire ID.","optionReview":"A — Incorrect: hardcodes one changing ID.\nB — Correct: matches both stable prefixes.\nC — Incorrect: * is not a wildcard inside an exact attribute comparison.\nD — Incorrect: requires the complete ID to equal submit_.","takeaway":"For a stable ID prefix, CSS ^= or XPath starts-with() is useful."},
    {"id":"LOC-077","batch":7,"title":"Stale elements","multi":false,"question":"A Selenium script locates a button. The web application then refreshes a section of the page by replacing that button with a newly created button having identical HTML attributes.\n\nThe script tries to click the previously stored WebElement reference.\n\nWhat is the most likely result?","options":[["A","NoSuchElementException"],["B","StaleElementReferenceException"],["C","InvalidSelectorException"],["D","The old reference automatically points to the new button."]],"answer":["B"],"expected":"StaleElementReferenceException.","steps":"1. Selenium locates the original button and stores its reference.\n2. The application replaces that button in the DOM.\n3. The stored reference still represents the old DOM element.\n4. Selenium attempts to interact with that old reference.","concept":"5. Concept from basics\n\nA WebElement reference does not automatically update when the page replaces an element. Selenium needs a fresh lookup for the new DOM element.","optionReview":"A — Incorrect: this is not simply a failed initial lookup.\nB — Correct: the previously located element has become stale.\nC — Incorrect: the locator syntax is not invalid.\nD — Incorrect: Selenium does not automatically redirect an old reference to a replacement element.","takeaway":"If an element is replaced after it has been located, consider StaleElementReferenceException. Re-locate the element before interacting with it."},
    {"id":"LOC-078","batch":7,"title":"Multiple matching elements and Java indexing","multi":false,"question":"<button class=\"item\">One</button>\n<button class=\"item\">Two</button>\n<button class=\"item\">Three</button>\n\n\nJava:\nList<WebElement> list =\n    driver.findElements(By.className(\"item\"));\n\nSystem.out.println(list.get(2).getText());\nSystem.out.println(list.get(3).getText());\n\n\nWhat happens?","options":[["A","Prints Three, then throws IndexOutOfBoundsException."],["B","Prints Three, then prints null."],["C","Throws IndexOutOfBoundsException before printing anything."],["D","Prints Two, then throws IndexOutOfBoundsException."]],"answer":["A"],"expected":"Three\n\n\nThen an IndexOutOfBoundsException occurs.","steps":"1. findElements() returns three buttons.\n2. list.get(2) accesses the third button.\n3. Its text is Three, which is printed.\n4. list.get(3) attempts to access a fourth element.","concept":"","optionReview":"5. Concept from basics\n\nJava list indexing starts at zero. The size of a list is not its last valid index.\n\n6. All options analysed\nA — Correct: prints Three, then fails on index 3.\nB — Incorrect: an invalid index doesn't return null.\nC — Incorrect: the first print executes successfully.\nD — Incorrect: index 2 is the third element, not the second.","takeaway":"For a list of size n, valid indexes are from 0 through n-1."},
    {"id":"LOC-079","batch":7,"title":"findElement() and multiple matches","multi":false,"question":"<button class=\"action\">Save</button>\n<button class=\"action\">Cancel</button>\n<button class=\"action\">Submit</button>\n\n\nJava:\nWebElement element =\n    driver.findElement(By.className(\"action\"));\n\nSystem.out.println(element.getText());\n\n\nWhat is printed?","options":[["A","Save"],["B","Cancel"],["C","Submit"],["D","All three texts"]],"answer":["A"],"expected":"Save","steps":"1. Selenium searches for elements with class action.\n2. Three elements match.\n3. findElement() returns the first matching element in document order.\n4. The first button's text is Save.","concept":"5. Concept from basics\n\nfindElement() returns one element, not a collection of all matching elements.","optionReview":"A — Correct: first matching button.\nB — Incorrect: second matching button.\nC — Incorrect: third matching button.\nD — Incorrect: that would require collecting all matches.","takeaway":"- findElement() → first matching element.\n- findElements() → list of all matching elements."},
    {"id":"LOC-080","batch":8,"title":"Locator debugging","multi":true,"question":"<div id=\"main\">\n    <section class=\"form\">\n        <input id=\"email\" name=\"email\">\n        <input id=\"password\" name=\"password\">\n    </section>\n    <button class=\"submit\">Submit</button>\n</div>\n\n\nWhich locators correctly identify the email input?","options":[["A","By.id(\"email\")"],["B","By.cssSelector(\"section.form > input[name='email']\")"],["C","By.xpath(\"//section[@class='form']//input[@id='email']\")"],["D","By.cssSelector(\"#main > input#email\")"]],"answer":["A","B","C"],"expected":"All three expressions locate the email input.","steps":"- A: Finds the element by its ID.\n- B: Finds an input that is a direct child of the section with class form, with name email.\n- C: Finds an input with ID email inside the section whose class is exactly form.\n- D: Looks for an input that is a direct child of #main. The actual input is nested inside section, so it does not match.","concept":"Different locator strategies can identify the same element. The key is checking the actual DOM hierarchy and conditions.","optionReview":"A — Correct: ID matches.\nB — Correct: direct child relationship and name both match.\nC — Correct: XPath finds the email input inside the specified section.\nD — Incorrect: the input is not a direct child of #main.","takeaway":"A locator can be syntactically valid but still fail because its assumed DOM relationship is incorrect.\n\nBatch 2 results\n9/10\n90% accuracy\nMeasure\tResult\nQuestions reviewed\t10\nCorrect\t9\nIncorrect\t1\nDefective\t0\nReconstructed\t0\n\n\nGenuine error: LOC-071 — reverse-axis preceding:: and ancestor exclusion.\n\nFinal assessment progress\nBatch\tScore\nLOC-061–070\t9/10\nLOC-071–080\t9/10\nCombined\t18/20 (90%)\n\nTwo batches completed; 30 questions remain.\n\nYour main revision point so far is reverse-axis evaluation, especially the distinction between preceding::, preceding-sibling:: and ancestor::.\n\nNext: LOC-081 to LOC-090."},
    {"id":"LOC-091","batch":9,"title":"Nearest ancestor","multi":false,"question":"<div id=\"outer\">\n    <div id=\"inner\">\n        <button id=\"save\"></button>\n    </div>\n</div>\n\n\nStarting from button#save, which XPath selects the nearest ancestor div?","options":[["A","./ancestor::div[1]"],["B","./ancestor::div[last()]"],["C","./parent::div[2]"],["D","./preceding::div[1]"]],"answer":["A"],"expected":"Selects div#inner.","steps":"1. Start at button#save.\n2. ancestor::div searches upwards for ancestor div elements.\n3. It finds div#inner and then div#outer.\n4. [1] on this reverse axis selects the nearest matching ancestor: div#inner.","concept":"ancestor searches all parent levels. ancestor::div[1] selects the nearest ancestor that is a div.","optionReview":"A — Correct: nearest ancestor div.\nB — Incorrect: [last()] selects the last node in the reverse-axis result, which is the farthest matching ancestor here, outer.\nC — Incorrect: parent::div can select only the immediate parent, and [2] cannot make it select a grandparent.\nD — Incorrect: preceding does not select ancestors.","takeaway":"ancestor::tag[1] means nearest matching ancestor. ancestor::tag[last()] means farthest matching ancestor in this reverse-axis selection."},
    {"id":"LOC-092","batch":9,"title":"Following siblings and positions","multi":true,"question":"<div>\n    <h2 id=\"heading\"></h2>\n    <p id=\"p1\"></p>\n    <span id=\"s1\"></span>\n    <p id=\"p2\"></p>\n    <span id=\"s2\"></span>\n</div>\n\n\nStarting from p1, which expressions select s2?","options":[["A","./following-sibling::span[2]"],["B","./following::span[2]"],["C","./following-sibling::*[3]"],["D","./following-sibling::span[1]"]],"answer":["A","B","C"],"expected":"All three expressions select span#s2.","steps":"Starting at p1, the following siblings in document order are:\n1. s1\n2. p2\n3. s2\n- A: following-sibling::span[2] counts only spans. First is s1, second is s2.\n- B: following::span[2] counts following spans. First is s1, second is s2.\n- C: following-sibling::*[3] counts all following element siblings. Third is s2.\n- D: following-sibling::span[1] selects the first following span, s1.","concept":"following-sibling selects later siblings of the current element. following selects later nodes in document order, including elements that are not siblings.\n\nThese are forward axes, so positional counting proceeds in document order.","optionReview":"A — Correct: second following sibling that is a span.\nB — Correct: second following span in document order.\nC — Correct: third following element sibling.\nD — Incorrect: selects s1, the first following span.","takeaway":"For forward axes, [1] is the nearest matching node. Always check whether the node test is * or a specific tag such as span."},
    {"id":"LOC-093","batch":9,"title":"XPath starts-with()","multi":false,"question":"<div data-status=\"active-user\"></div>\n<div data-status=\"inactive-user\"></div>\n<div data-status=\"active-admin\"></div>\n\n\nWhich XPath selects only the first and third elements?","options":[["A","//div[starts-with(@data-status,'active')]"],["B","//div[contains(@data-status,'user')]"],["C","//div[normalize-space(@data-status)='active']"],["D","//div[starts-with(@data-status,'user')]"]],"answer":["A"],"expected":"The first and third div elements.","steps":"1. //div finds all three div elements.\n2. starts-with() checks whether data-status begins with active.\n3. active-user and active-admin match.\n4. inactive-user does not start with active.","concept":"starts-with(attribute, value) checks the beginning of an attribute's value. It does not require the entire value to be equal.","optionReview":"A — Correct: first and third values begin with active.\nB — Incorrect: first and second values contain user.\nC — Incorrect: no attribute value is exactly active.\nD — Incorrect: none of the values begins with user.","takeaway":"Use starts-with() for a stable prefix. Use contains() when the required text can appear anywhere in the attribute."},
    {"id":"LOC-094","batch":9,"title":"XPath text matching","multi":true,"question":"<button>Login Now</button>\n<button>Login</button>\n<button>Proceed to Login</button>\n\n\nWhich expressions select the first two buttons but not the third?","options":[["A","//button[starts-with(normalize-space(.),'Login')]"],["B","//button[contains(normalize-space(.),'Login')]"],["C","//button[normalize-space(.)='Login' or starts-with(normalize-space(.),'Login ')]"],["D","//button[normalize-space(.)='Login']"]],"answer":["A","C"],"expected":"Both A and C select:\n- Login Now\n- Login","steps":"Let's evaluate the text of each button:\nButton\tnormalize-space(.)\nFirst\tLogin Now\nSecond\tLogin\nThird\tProceed to Login\n\n- A: starts-with(...,'Login') matches the first two.\n- B: contains(...,'Login') matches all three.\n- C: matches text exactly equal to Login, OR text starting with Login  (Login followed by a space). That matches the first two.\n- D: exact equality matches only the second.","concept":"The dot . represents the current node's string value. For a button, it gives its text content.\n\nnormalize-space() cleans up whitespace. starts-with() checks the beginning, while contains() checks anywhere in the string.","optionReview":"A — Correct: both first and second start with Login.\nB — Incorrect: third also contains Login.\nC — Correct: covers both exact Login and text beginning Login .\nD — Incorrect: selects only the second button.","takeaway":"A multiple-correct question may have two different expressions that achieve the same result. Don't stop after finding one correct option. Check every option independently."},
    {"id":"LOC-095","batch":9,"title":"CSS direct children","multi":false,"question":"<div class=\"panel\">\n    <p id=\"p1\"></p>\n    <section>\n        <p id=\"p2\"></p>\n    </section>\n    <p id=\"p3\"></p>\n</div>\n\n\nWhich CSS selector selects only p1 and p3?","options":[["A",".panel > p"],["B",".panel p"],["C","section > p"],["D","section + p"]],"answer":["A"],"expected":"Selects p1 and p3.","steps":"- p1 is directly inside .panel.\n- p2 is inside section, which is inside .panel.\n- p3 is directly inside .panel.\nThe > combinator selects only direct children, so it excludes p2.","concept":"A direct child is exactly one level below its parent. A descendant can be at any depth below its ancestor.","optionReview":"A — Correct: selects direct child paragraphs p1 and p3.\nB — Incorrect: selects all descendant paragraphs, including p2.\nC — Incorrect: selects only p2.\nD — Incorrect: selects p3, because it immediately follows the section, but not p1.","takeaway":"Use .parent > child when you want only one DOM level. Use .parent child when you want all matching descendants."},
    {"id":"LOC-096","batch":9,"title":"CSS attribute selectors","multi":true,"question":"<input type=\"text\" name=\"user_email\">\n<input type=\"text\" name=\"user_phone\">\n<input type=\"text\" name=\"admin_email\">\n\n\nWhich selectors match only the first two inputs?","options":[["A","input[name^='user_']"],["B","input[name*='user']"],["C","input[name$='_email']"],["D","input[name='user_email'], input[name='user_phone']"]],"answer":["A","B","D"],"expected":"The first two inputs: user_email and user_phone.","steps":"- A checks whether name starts with user_.\n- B checks whether name contains user.\n- C checks whether name ends with _email.\n- D explicitly lists the two exact attribute values.","concept":"CSS attribute selectors can match the beginning, ending, presence or exact value of an attribute.","optionReview":"A — Correct: both first and second start with user_.\nB — Correct: both contain user.\nC — Incorrect: matches user_email and admin_email.\nD — Correct: explicitly selects the first two values.","takeaway":"Memorise:\n- ^= starts with.\n- $= ends with.\n- *= contains.\n- = exact match."},
    {"id":"LOC-097","batch":9,"title":"CSS vs XPath","multi":false,"question":"Which statement is correct?","options":[["A","CSS selectors support the XPath ancestor:: axis."],["B","XPath can locate an element based on its visible text content."],["C","CSS ~ selects only the immediately following sibling."],["D","XPath cannot locate elements using attributes."]],"answer":["B"],"expected":"Only statement B is correct.","steps":"Consider:\n//button[text()='Login']\n\n\nThis searches for a button whose text is exactly Login.","concept":"XPath can use text functions and axes. CSS has its own selectors and combinators, but does not support XPath axes such as ancestor::.","optionReview":"A — Incorrect: ancestor:: is an XPath axis.\nB — Correct: XPath can match elements using text.\nC — Incorrect: CSS ~ selects all following siblings that match, not just the immediately following one. + selects the immediately following sibling.\nD — Incorrect: XPath supports attribute matching, for example //input[@type='text'].","takeaway":"CSS + means immediately following sibling; CSS ~ means all matching following siblings. XPath can match visible text and attributes."},
    {"id":"LOC-098","batch":9,"title":"Dynamic XPath locator","multi":false,"question":"A website generates IDs such as:\n<input id=\"login_4521_field\">\n<input id=\"login_9824_field\">\n\n\nThe number changes on every page load. Which XPath matches both?","options":[["A","//input[@id='login_*_field']"],["B","//input[starts-with(@id,'login_') and contains(@id,'_field')]"],["C","//input[ends-with(@id,'login_')]"],["D","//input[contains(@id,'4521')]"]],"answer":["B"],"expected":"Both input elements are selected.","steps":"1. //input finds input elements.\n2. starts-with(@id,'login_') checks the stable prefix.\n3. contains(@id,'_field') checks that the suffix text is present.\n4. Both IDs satisfy the two conditions.","concept":"Dynamic locators avoid relying on the changing part of an attribute. Instead, they use stable portions of the value.","optionReview":"A — Incorrect: * is not a wildcard inside an XPath equality comparison.\nB — Correct: both conditions match both IDs.\nC — Incorrect: XPath 1.0 does not provide the standard ends-with() function; this expression is also checking the wrong ending.\nD — Incorrect: matches only the ID containing 4521, so it is not stable.","takeaway":"For Selenium's standard XPath 1.0 support, use starts-with() and contains() when you need to handle dynamic attribute values."},
    {"id":"LOC-099","batch":9,"title":"Java list indexing and output","multi":false,"question":"HTML:\n<button class=\"action\">Save</button>\n<button class=\"action\">Edit</button>\n<button class=\"action\">Delete</button>\n<button class=\"action\">Cancel</button>\n\n\nJava:\nList<WebElement> buttons =\n    driver.findElements(By.className(\"action\"));\n\nSystem.out.print(buttons.get(0).getText());\nSystem.out.print(buttons.get(buttons.size() - 1).getText());\nSystem.out.print(buttons.size());\n\n\nWhat is printed?","options":[["A","SaveCancel4"],["B","SaveDelete4"],["C","EditCancel3"],["D","SaveCancel3"]],"answer":["A"],"expected":"SaveCancel4","steps":"findElements() returns four buttons.\n- buttons.get(0) → Save\n- buttons.size() → 4\n- buttons.size() - 1 → 3\n- buttons.get(3) → Cancel\n- buttons.size() prints 4\nAll three print statements run consecutively without spaces or line breaks.","concept":"Java lists are zero-indexed. For a list of size 4, the valid indexes are 0, 1, 2 and 3.\n\nThe last element's index is always size() - 1.","optionReview":"A — Correct: prints Save, Cancel, and 4.\nB — Incorrect: Delete is at index 2, not the last index.\nC — Incorrect: the first element is Save, and the list has four elements.\nD — Incorrect: the list size is 4, not 3.","takeaway":"For the last element of a list, use get(size() - 1). Remember that size() is the number of elements, not the last index."},
    {"id":"LOC-100","batch":10,"title":"findElement() vs findElements()","multi":true,"question":"HTML:\n<div class=\"item\">One</div>\n<div class=\"item\">Two</div>\n<div class=\"item\">Three</div>\n\n\nWhich statements are correct?","options":[["A","findElement(By.className(\"item\")) returns the first matching element."],["B","findElements(By.className(\"item\")) returns a list containing three elements."],["C","findElements(By.id(\"missing\")) throws NoSuchElementException when no element matches."],["D","Calling get(3) on the returned three-element list causes IndexOutOfBoundsException."]],"answer":["A","B","D"],"expected":"There is no fixed printed output. These statements describe Selenium and Java behaviour.","steps":"1. findElement() returns the first matching element.\n2. findElements() returns all matching elements in a list.\n3. There are three matching elements, so the list has size 3.\n4. Valid indexes are 0, 1 and 2.","concept":"5. Concept explained from basics\n\nThe key difference:\nMethod\tResult when matches exist\tResult when no match exists\nfindElement()\tFirst matching WebElement\tNoSuchElementException\nfindElements()\tList of matching elements\tEmpty list","optionReview":"A — Correct: findElement() returns the first match.\nB — Correct: there are three matching elements.\nC — Incorrect: findElements() returns an empty list when no match exists.\nD — Correct: index 3 is invalid for a three-element list.","takeaway":"Never confuse findElement() with findElements(). One returns an element; the other returns a list. An empty list is not the same as an exception.\n\nFinal assessment progress\nBatch\tScore\nBatch 1\t9/10\nBatch 2\t9/10\nBatch 3\t8/9 valid\nBatch 4\t9/10\nTotal\t35/39 valid (89.7%)\n\nOne defective question excluded from Batch 3. No other questions excluded.\n\nYour main revision point from this batch: distinguish starts-with() from contains() and check every option in multiple-correct questions. LOC-094 was the only genuine error.\n\n10 questions remain. After Batch 5, we'll assess your performance across all six locator topics and decide whether they can be marked complete."},
    {"id":"LOC-101","batch":10,"title":"XPath ancestor axis","multi":false,"question":"<div id=\"a\">\n    <section id=\"b\">\n        <div id=\"c\">\n            <button id=\"save\"></button>\n        </div>\n    </section>\n</div>\n\n\nStarting from button#save, which XPath selects section#b?","options":[["A","./ancestor::section[1]"],["B","./parent::section"],["C","./ancestor::div[1]"],["D","./preceding-sibling::section[1]"]],"answer":["A"],"expected":"Selects section#b.","steps":"1. Start at button#save.\n2. Its immediate parent is div#c.\n3. Above that is section#b.\n4. ancestor::section searches upwards for section elements.","concept":"5. Concept explained from basics\n\nancestor searches all levels above an element. parent searches only one level above it.","optionReview":"A — Correct: selects the nearest ancestor section.\nB — Incorrect: the immediate parent is div#c, not a section.\nC — Incorrect: selects the nearest ancestor div, div#c.\nD — Incorrect: there is no preceding sibling section.","takeaway":"Use ancestor::tag[1] to find the nearest matching ancestor. Use parent::tag for only the immediate parent."},
    {"id":"LOC-102","batch":10,"title":"XPath following axes","multi":true,"question":"<div>\n    <p id=\"p1\"></p>\n    <p id=\"p2\"></p>\n    <span id=\"s1\"></span>\n    <p id=\"p3\"></p>\n</div>\n\n\nStarting from p1, which expressions select p3?","options":[["A","./following-sibling::p[2]"],["B","./following::p[2]"],["C","./following-sibling::*[3]"],["D","./following-sibling::p[1]"]],"answer":["A","B","C"],"expected":"All three select p3.","steps":"Starting at p1, the following siblings in document order are:\n1. p2\n2. s1\n3. p3\n- A counts paragraphs only: p2 first, p3 second.\n- B counts following paragraphs: p2 first, p3 second.\n- C counts all following element siblings: p2 first, s1 second, p3 third.\n- D selects the first following paragraph, p2.","concept":"following-sibling looks at later siblings only. following looks at later nodes in document order, not just siblings.\n\nBoth are forward axes, so positions are counted in document order.","optionReview":"A — Correct: second following sibling paragraph.\nB — Correct: second following paragraph.\nC — Correct: third following element sibling.\nD — Incorrect: first following paragraph is p2.","takeaway":"Check whether the expression counts all elements (*) or only a particular tag (p). That changes positional indexes."},
    {"id":"LOC-103","batch":10,"title":"XPath starts-with()","multi":false,"question":"<input id=\"user_email_field\">\n<input id=\"user_phone_field\">\n<input id=\"admin_email_field\">\n\n\nWhich XPath selects only the first two inputs?","options":[["A","//input[contains(@id,'email')]"],["B","//input[starts-with(@id,'user_')]"],["C","//input[contains(@id,'field')]"],["D","//input[starts-with(@id,'admin_')]"]],"answer":["B"],"expected":"The first two inputs.","steps":"1. //input finds all input elements.\n2. starts-with(@id,'user_') checks whether the ID begins with user_.\n3. The first two IDs match.\n4. The third begins with admin_, so it is excluded.","concept":"starts-with() is useful when an attribute has a fixed beginning and a variable ending.","optionReview":"A — Incorrect: selects the first and third inputs because both contain email.\nB — Correct: selects the first two IDs.\nC — Incorrect: all three IDs contain field.\nD — Incorrect: selects only the third input.","takeaway":"For stable prefixes, use starts-with(). For text appearing anywhere, use contains()."},
    {"id":"LOC-104","batch":10,"title":"XPath text functions","multi":true,"question":"<span>  Account Created  </span>\n<span>Account</span>\n<span>Create Account</span>\n\n\nWhich expressions select the first and second spans, but not the third?","options":[["A","//span[starts-with(normalize-space(.),'Account')]"],["B","//span[contains(normalize-space(.),'Account')]"],["C","//span[normalize-space(.)='Account' or starts-with(normalize-space(.),'Account ')]"],["D","//span[normalize-space(.)='Account Created']"]],"answer":["A","C"],"expected":"Both A and C select:\n- First span: Account Created\n- Second span: Account\nThey exclude Create Account.","steps":"First, apply normalize-space(.):\nOriginal text\tNormalized text\nAccount Created\tAccount Created\nAccount\tAccount\nCreate Account\tCreate Account\n\nNow evaluate the expressions:\n- A: starts-with(...,'Account') matches the first two.\n- B: contains(...,'Account') matches all three.\n- C: exact Account OR starts with Account  matches the first two.\n- D: exact Account Created matches only the first.","concept":"normalize-space() cleans whitespace. starts-with() checks the beginning of the cleaned text. contains() checks whether a substring appears anywhere.","optionReview":"A — Correct: both first and second start with Account.\nB — Incorrect: third also contains Account.\nC — Correct: handles both exact Account and longer text beginning with Account .\nD — Incorrect: matches only the first span.","takeaway":"A multiple-correct question can have two different expressions that achieve the same result. Check every option independently."},
    {"id":"LOC-105","batch":10,"title":"CSS positional selector · multi-select","multi":true,"question":"<div id=\"main\">\n    <p class=\"note\">A</p>\n    <section>\n        <p class=\"note\">B</p>\n    </section>\n    <p class=\"note\">C</p>\n</div>\n\n\nWhich selector selects only paragraph C?","options":[["A","#main > p.note:last-child"],["B","#main p.note"],["C","section + p.note"],["D","#main > section p.note"]],"answer":["A","C"],"expected":"Only paragraph C.","steps":"1. #main selects the main div.\n2. > restricts the search to its direct children.\n3. p.note restricts the result to paragraphs with class note.\n4. :last-child requires the paragraph to be the last child of its parent.","concept":"5. Concept explained from basics\n\n:last-child selects an element if it is the final child of its parent. It is different from :last-of-type, which selects the last element of its particular tag type.","optionReview":"A — Correct: paragraph C is a direct child and the last child of #main.\nB — Incorrect: selects A, B and C because all are descendants.\nC — Incorrect: selects C because it immediately follows section, but this selector also happens to select C.\nCorrection: This means C is also correct. The question was labelled single-correct but has two valid answers, A and C. Your answer A is valid, so I am excluding LOC-105 from the score rather than marking it wrong.\n\nD — Incorrect: selects B, which is inside section.","takeaway":"Watch for overlapping CSS selectors. A selector can be more specific without being the only selector that matches the requested element."},
    {"id":"LOC-106","batch":10,"title":"CSS attribute suffix","multi":false,"question":"<a href=\"/reports/annual.pdf\">Annual</a>\n<a href=\"/reports/monthly.pdf\">Monthly</a>\n<a href=\"/reports/annual\">Annual Web</a>\n\n\nWhich CSS selector selects only the first two links?","options":[["A","a[href^='/reports/']"],["B","a[href$='.pdf']"],["C","a[href*='annual']"],["D","a[href='/reports/annual.pdf']"]],"answer":["B"],"expected":"The Annual and Monthly PDF links.","steps":"1. a selects anchor elements.\n2. [href$='.pdf'] checks whether the href value ends in .pdf.\n3. The first two URLs end in .pdf.\n4. The third does not.","concept":"CSS attribute operators:\n- ^= starts with.\n- $= ends with.\n- *= contains.\n- = exact value.","optionReview":"A — Incorrect: all three URLs start with /reports/.\nB — Correct: only the first two end with .pdf.\nC — Incorrect: selects the first and third because both contain annual.\nD — Incorrect: selects only the first link.","takeaway":"When the stable part is at the end of an attribute, use $=."},
    {"id":"LOC-107","batch":10,"title":"CSS vs XPath","multi":true,"question":"Which statements are correct?","options":[["A","XPath can move from a child element to its parent using parent::."],["B","CSS + selects all following siblings."],["C","CSS ~ selects matching following siblings that share the same parent."],["D","XPath can combine conditions using and."]],"answer":["A","C","D"],"expected":"A, C and D are correct.","steps":"- A: parent:: selects the immediate parent of the current element.\n- B: + selects only the immediately following sibling.\n- C: ~ selects matching later siblings with the same parent.\n- D: XPath supports logical operators such as and.","concept":"For CSS sibling combinators:\ndiv + p\n\n\nSelects a p immediately after a div.\ndiv ~ p\n\n\nSelects all matching p siblings that follow a div.\n\nXPath also supports combined conditions, such as:\n//input[@type='text' and @name='email']","optionReview":"A — Correct: parent:: selects the immediate parent.\nB — Incorrect: + selects only the immediately following sibling.\nC — Correct: ~ selects all matching following siblings sharing the same parent.\nD — Correct: XPath supports and.","takeaway":"Do not mix up CSS + and ~. Also remember that XPath can combine attribute conditions with and and or."},
    {"id":"LOC-108","batch":10,"title":"Dynamic elements","multi":false,"question":"<button data-action=\"submit_12345\">\n<button data-action=\"submit_98765\">\n<button data-action=\"cancel_12345\">\n\n\nWhich XPath selects the first two buttons?","options":[["A","//button[contains(@data-action,'submit')]"],["B","//button[@data-action='submit_*']"],["C","//button[starts-with(@data-action,'cancel')]"],["D","//button[contains(@data-action,'12345')]"]],"answer":["A"],"expected":"The first two buttons.","steps":"1. //button finds all buttons.\n2. contains(@data-action,'submit') checks whether the attribute contains submit.\n3. The first two values contain submit.\n4. The third contains cancel, so it is excluded.","concept":"contains() can locate dynamic attributes when a stable substring remains unchanged.","optionReview":"A — Correct: matches both submit buttons.\nB — Incorrect: XPath equality does not treat * as a wildcard.\nC — Incorrect: selects only the cancel button.\nD — Incorrect: selects the first and third because both contain 12345.","takeaway":"Do not use * as a wildcard inside XPath equality. Use contains() or starts-with() for changing values."},
    {"id":"LOC-109","batch":10,"title":"Java loop and list indexing","multi":false,"question":"HTML:\n<li class=\"menu\">Home</li>\n<li class=\"menu\">About</li>\n<li class=\"menu\">Services</li>\n<li class=\"menu\">Contact</li>\n\n\nJava:\nList<WebElement> items =\n    driver.findElements(By.className(\"menu\"));\n\nfor (int i = 0; i < items.size(); i += 2) {\n    System.out.print(items.get(i).getText() + \" \");\n}\n\n\nWhat is printed?","options":[["A","Home About Services Contact"],["B","Home Services"],["C","About Contact"],["D","Home Services Contact"]],"answer":["B"],"expected":"Home Services \n\n\nThere is a trailing space after Services.","steps":"The list has four elements:\nIndex\tText\n0\tHome\n1\tAbout\n2\tServices\n3\tContact\n\nThe loop starts at zero and increases by two:\n- i = 0: prints Home.\n- i = 2: prints Services.\n- i = 4: condition 4 < 4 is false, so the loop stops.","concept":"i += 2 skips every other index. Starting from zero means the loop visits even indexes: 0, 2, 4 and so on.","optionReview":"A — Incorrect: would require visiting every index.\nB — Correct: selects indexes 0 and 2.\nC — Incorrect: these are indexes 1 and 3.\nD — Incorrect: index 4 is not valid, and the loop stops before reaching it.","takeaway":"Always check the loop's starting index, condition and increment. Together they determine which elements are visited."},
    {"id":"LOC-110","batch":11,"title":"List size and valid indexes","multi":true,"question":"List<WebElement> elements =\n    driver.findElements(By.tagName(\"input\"));\n\n\nSuppose the page contains five input elements. Which statements are correct?","options":[["A","elements.size() returns 5."],["B","elements.get(4) accesses the fifth element."],["C","elements.get(5) accesses the fifth element."],["D","findElements() returns elements in document order."]],"answer":["A","B","D"],"expected":"- elements.size() returns 5.\n- elements.get(4) accesses the fifth element.\n- elements.get(5) throws IndexOutOfBoundsException.","steps":"A five-element list has indexes:\n0, 1, 2, 3, 4\n\n\n- A: size() counts all five elements.\n- B: index 4 is the fifth element.\n- C: index 5 is outside the valid range.\n- D: Selenium returns matching elements in document order.","concept":"Java lists start at index zero. The last valid index is always size() - 1.","optionReview":"A — Correct: there are five elements.\nB — Correct: index 4 is the fifth element.\nC — Incorrect: index 5 would be a sixth position.\nD — Correct: matching elements are returned in document order.","takeaway":"For a list of size n, valid indexes are from 0 to n - 1. Never confuse the number of elements with the last index.\n\nFinal assessment summary: LOC-061–110\nI also audited the earlier batch scores and corrected two scoring mistakes rather than carrying them forward.\nBatch\tCorrect\tValid questions\nBatch 1\t9\t10\nBatch 2\t9\t10\nBatch 3\t7\t9\nBatch 4\t8\t9\nBatch 5\t7\t8 answered\nTotal\t40\t46 graded\n\nCurrent verified score\n40/46\n87.0%\n3 defective questions excluded; 1 question awaiting your answer.\n\nConcepts to revise\n1. Reverse XPath axes and positional predicates — LOC-082.\n2. XPath starts-with() vs contains() — LOC-094.\n3. CSS + vs ~ and sibling relationships — LOC-107.\n4. Multiple-correct questions: check every option, not just the first valid one.\nOne question to close the assessment\nFor LOC-104, which answer did you intend?\n- A only\n- C only\n- Both A and C\nOnce you confirm, I'll calculate the final score and decide whether topics 4–9 are ready to be marked complete."},
    {"id":"WDM-001","topic":"WebDriver methods","batch":1,"title":"Return types","multi":false,"question":"Which statement about the following methods is correct?","options":[["A","getTitle() returns void."],["B","click() returns boolean."],["C","isDisplayed() returns boolean."],["D","getCurrentUrl() returns WebElement."]],"answer":["C"],"expected":"No printed output. The question tests method return types.","steps":"- getTitle() returns a String.\n- click() returns void.\n- isDisplayed() returns boolean.\n- getCurrentUrl() returns a String.","concept":"A return type tells you what a method gives back after execution. boolean means the result is either true or false.","optionReview":"A — Incorrect: getTitle() returns String.\nB — Incorrect: click() returns void.\nC — Correct: isDisplayed() returns boolean.\nD — Incorrect: getCurrentUrl() returns String.","takeaway":"Memorise the return types of common Selenium methods. In particular, isDisplayed(), isEnabled() and isSelected() all return boolean."},
    {"id":"WDM-002","topic":"WebDriver methods","batch":1,"title":"Browser navigation","multi":false,"question":"A browser is currently on Page B. The user previously visited Page A, then navigated to Page B using Selenium.\n\nWhat does this statement do?\ndriver.navigate().back();","options":[["A","Closes Page B and terminates the browser session."],["B","Navigates to Page A using browser history."],["C","Reloads Page B."],["D","Opens a new browser window showing Page A."]],"answer":["B"],"expected":"The browser navigates back to Page A.","steps":"1. The browser is on Page B.\n2. navigate() accesses the browser navigation interface.\n3. back() moves one step backwards in browser history.\n4. The browser returns to Page A.","concept":"Browser history stores previously visited pages. back() and forward() move through that history.","optionReview":"A — Incorrect: back() does not close the browser.\nB — Correct: it navigates to the previous history entry.\nC — Incorrect: refresh() reloads the current page.\nD — Incorrect: back() does not open a new window.","takeaway":"Remember: back() = previous page, forward() = next history entry, refresh() = reload current page."},
    {"id":"WDM-003","topic":"WebDriver methods","batch":1,"title":"sendKeys() and clear()","multi":false,"question":"Assume the input field is initially empty.\nWebElement input = driver.findElement(By.id(\"name\"));\n\ninput.sendKeys(\"Java\");\ninput.sendKeys(\"Selenium\");\nSystem.out.println(input.getAttribute(\"value\"));\n\n\nWhat is printed, assuming the field accepts the text normally?","options":[["A","Java"],["B","Selenium"],["C","JavaSelenium"],["D","Empty string"]],"answer":["C"],"expected":"JavaSelenium","steps":"1. The input starts empty.\n2. First sendKeys(\"Java\") enters Java.\n3. Second sendKeys(\"Selenium\") appends Selenium.\n4. getAttribute(\"value\") retrieves the input's current value.","concept":"5. Concept explained from basics\n\nsendKeys() does not automatically replace existing text. To replace text, clear the field first.","optionReview":"A — Incorrect: ignores the second sendKeys().\nB — Incorrect: assumes the second call replaces the first.\nC — Correct: both strings are appended.\nD — Incorrect: the field contains text.","takeaway":"Multiple sendKeys() calls generally append text. Use clear() before entering replacement text."},
    {"id":"WDM-004","topic":"WebDriver methods","batch":1,"title":"Element state","multi":true,"question":"Consider a checkbox that is visible, enabled and currently unchecked.\n\nWhich statements are correct?","options":[["A","isDisplayed() returns true."],["B","isEnabled() returns false."],["C","isSelected() returns false."],["D","click() cannot be called on it because it is unchecked."]],"answer":["A","C"],"expected":"- isDisplayed() → true\n- isEnabled() → true\n- isSelected() → false","steps":"1. The checkbox is visible, so isDisplayed() is true.\n2. It is enabled, so isEnabled() is true.\n3. It is unchecked, so isSelected() is false.\n4. An enabled checkbox can be clicked even when unchecked.","concept":"Visibility, enabled state and selected state are three independent properties. One does not automatically determine the others.","optionReview":"A — Correct: it is visible.\nB — Incorrect: it is enabled.\nC — Correct: it is unchecked.\nD — Incorrect: clicking an unchecked checkbox is a normal way to select it.","takeaway":"A checkbox can be visible, enabled and unchecked simultaneously. Do not confuse isEnabled() with isSelected()."},
    {"id":"WDM-005","topic":"WebDriver methods","batch":1,"title":"findElement() vs findElements()","multi":false,"question":"The page contains four elements matching a locator.\nWebElement element =\n    driver.findElement(By.className(\"item\"));\n\n\nWhat does element represent?","options":[["A","A list containing all four elements."],["B","The first matching element in document order."],["C","The last matching element in document order."],["D","A random matching element."]],"answer":["B"],"expected":"No printed output. element holds a reference to the first matching WebElement.","steps":"1. Selenium searches for elements with class item.\n2. It finds four matches.\n3. findElement() returns the first match in document order.\n4. The returned object is stored in element.","concept":"findElement() returns one WebElement, whereas findElements() returns a List<WebElement> containing all matches.","optionReview":"A — Incorrect: that describes findElements().\nB — Correct: findElement() returns the first match.\nC — Incorrect: it does not return the last match.\nD — Incorrect: selection is not random.","takeaway":"findElement() = first matching element. findElements() = all matching elements."},
    {"id":"WDM-006","topic":"WebDriver methods","batch":1,"title":"getText() vs getAttribute()","multi":false,"question":"HTML:\n<input id=\"email\" value=\"user@example.com\">\n\n\nWhich statement retrieves the input's current value in the commonly used Selenium approach?","options":[["A","element.getText()"],["B","element.getAttribute(\"value\")"],["C","element.getTitle()"],["D","driver.getCurrentUrl()"]],"answer":["B"],"expected":"user@example.com","steps":"1. Selenium locates the input.\n2. getAttribute(\"value\") requests its value.\n3. The returned value is a String.\n4. The result is user@example.com.","concept":"Input fields generally hold their entered content in the value property. getText() is normally used for visible text between an element's opening and closing tags.","optionReview":"A — Incorrect: an input's value is not normally retrieved through getText().\nB — Correct: retrieves the input value.\nC — Incorrect: getTitle() belongs to WebDriver, not WebElement.\nD — Incorrect: returns the current page URL, not an input value.","takeaway":"For input fields, remember getAttribute(\"value\"). For visible text inside elements, remember getText()."},
    {"id":"WDM-007","topic":"WebDriver methods","batch":1,"title":"close() vs quit()","multi":true,"question":"Which statements are correct?","options":[["A","close() closes the current browser window."],["B","quit() closes all windows associated with the WebDriver session and ends that session."],["C","close() always terminates the WebDriver session, even when other windows remain open."],["D","quit() is generally used when the test execution is finished."]],"answer":["A","B","D"],"expected":"No printed output. The question tests browser-window and session behaviour.","steps":"- close() closes the currently focused window.\n- quit() closes the windows associated with the session and ends the session.\n- After quit(), the WebDriver session is no longer active.","concept":"A browser window and a WebDriver session are not the same thing. A session can manage multiple windows or tabs. Closing one window does not necessarily end the session.","optionReview":"A — Correct: closes the current window.\nB — Correct: closes associated windows and ends the session.\nC — Incorrect: other windows may remain, and the session may continue.\nD — Correct: quit() is commonly used for test cleanup.","takeaway":"close() = current window. quit() = all session windows and session termination."},
    {"id":"WDM-008","topic":"WebDriver methods","batch":1,"title":"Navigation to a URL","multi":false,"question":"Which statement navigates the browser to the given URL using the WebDriver navigation interface?","options":[["A","driver.navigate(\"https://example.com\");"],["B","driver.navigate().to(\"https://example.com\");"],["C","driver.to(\"https://example.com\");"],["D","driver.getCurrentUrl(\"https://example.com\");"]],"answer":["B"],"expected":"The browser navigates to:\nhttps://example.com","steps":"1. driver.navigate() obtains the Navigation interface.\n2. .to(\"https://example.com\") navigates to the supplied URL.\n3. The browser loads the requested page.","concept":"There are two common ways to navigate to a URL:\ndriver.get(\"https://example.com\");\n\n\nand\ndriver.navigate().to(\"https://example.com\");\n\n\nBoth navigate to the URL.","optionReview":"A — Incorrect: navigate() does not accept the URL directly.\nB — Correct: this is the proper navigation method call.\nC — Incorrect: WebDriver does not provide this to() call.\nD — Incorrect: getCurrentUrl() retrieves the current URL; it does not accept a destination URL.","takeaway":"Remember the exact syntax: driver.navigate().to(url). The dot after navigate() matters."},
    {"id":"WDM-009","topic":"WebDriver methods","batch":1,"title":"Element state and Java output","multi":false,"question":"Assume the checkbox is displayed, enabled and initially unchecked.\nWebElement checkbox =\n    driver.findElement(By.id(\"terms\"));\n\nSystem.out.print(checkbox.isDisplayed());\nSystem.out.print(checkbox.isEnabled());\n\ncheckbox.click();\n\nSystem.out.print(checkbox.isSelected());\n\n\nWhat is printed, assuming the click succeeds?","options":[["A","truetruefalse"],["B","truetruetrue"],["C","falsefalsetrue"],["D","truefalsefalse"]],"answer":["B"],"expected":"truetruetrue","steps":"1. isDisplayed() returns true.\n2. isEnabled() returns true.\n3. click() clicks the unchecked checkbox, selecting it.\n4. isSelected() now returns true.","concept":"5. Concept explained from basics\n\nA checkbox changes its selected state when clicked, assuming the click succeeds and the page does not immediately change it back.","optionReview":"A — Incorrect: assumes the checkbox remains unchecked after clicking.\nB — Correct: all three printed values are true.\nC — Incorrect: contradicts the initial visible and enabled state.\nD — Incorrect: the checkbox is enabled, and clicking it selects it.","takeaway":"When tracing Selenium code, calculate the state before and after each action. A click can change the result of a later isSelected() call."},
    {"id":"WDM-010","topic":"WebDriver methods","batch":1,"title":"WebDriver vs WebElement methods","multi":true,"question":"Which statements are correct?","options":[["A","driver.getTitle() is a WebDriver method."],["B","element.getText() is a WebElement method."],["C","driver.click() is used to click a webpage button."],["D","element.isEnabled() returns a boolean."]],"answer":["A","B","D"],"expected":"No printed output. This question tests method ownership and return types.","steps":"- driver.getTitle() retrieves the browser page title.\n- element.getText() retrieves the element's visible text.\n- driver.click() is not a valid standard WebDriver method.\n- element.isEnabled() checks whether the element is enabled and returns a boolean.","concept":"There are two important objects:\n- WebDriver controls the browser.\n- WebElement represents a particular webpage element.\nThe method must be called on the appropriate object.","optionReview":"A — Correct: getTitle() belongs to WebDriver.\nB — Correct: getText() belongs to WebElement.\nC — Incorrect: use element.click() to click an element.\nD — Correct: isEnabled() returns boolean.","takeaway":"Always identify whether a method operates on the browser or an individual element before choosing the object that calls it.\n\nProgress tracker\nWebDriver methods\nIn progress\n\n10/10\nBatch 1 · 100%\n\n\n\nTracking\tStatus\nConcept check\t5/5\nMCQs reviewed\t10/10\nDefective questions\t0\nGenuine errors\t0\n\n\nNext: Batch 2 (WDM-011–020) will be more challenging, with mixed Java output, return types, navigation, element states, and practical Selenium scenarios. I'll avoid simply repeating the patterns from this batch."},
    {"id":"WDM-021","topic":"WebDriver methods","batch":2,"title":"Clearing and entering text","multi":true,"question":"Assume the input field initially contains `Test`.\n\n```\nWebElement input = driver.findElement(By.id(\"search\"));\n\ninput.clear();\ninput.sendKeys(\"Java\");\ninput.sendKeys(\" Exam\");\n\nSystem.out.println(input.getAttribute(\"value\"));\n```\n\nWhich statements are correct?","options":[["A","The final value is `Java Exam`."],["B","The final value is `TestJava Exam`."],["C","`clear()` removes the initial value."],["D","`sendKeys()` automatically replaces the previous text every time."]],"answer":["A","C"],"expected":"```\nJava Exam\n```","steps":"1. Initial value is `Test`.\n2. `clear()` removes `Test`.\n3. First `sendKeys(\"Java\")` enters `Java`.\n4. Second `sendKeys(\" Exam\")` appends a space and `Exam`.","concept":"5\\. Concept explained\n\n- `clear()` empties an editable field.\n- `sendKeys()` types into the field.\n- Repeated `sendKeys()` calls append text unless the existing content is cleared or selected first.","optionReview":"- A — Correct: final value is `Java Exam`.\n- B — Incorrect: `Test` was removed by `clear()`.\n- C — Correct: `clear()` removes the existing content.\n- D — Incorrect: `sendKeys()` does not automatically replace existing text.","takeaway":"Remember: `clear()` removes; `sendKeys()` enters or appends."},
    {"id":"WDM-022","topic":"WebDriver methods","batch":2,"title":"Browser navigation history","multi":false,"question":"A browser visits pages in this order:\n\n```\ndriver.get(\"https://site.com/A\");\ndriver.navigate().to(\"https://site.com/B\");\ndriver.navigate().to(\"https://site.com/C\");\ndriver.navigate().back();\ndriver.navigate().back();\ndriver.navigate().forward();\n```\n\nWhich page is current at the end?","options":[["A","Page A"],["B","Page B"],["C","Page C"],["D","No page is open"]],"answer":["B"],"expected":"No output is printed. The current browser page is Page B.","steps":"| Operation   | Current page |\n| ----------- | ------------ |\n| `get(A)`    | A            |\n| `to(B)`     | B            |\n| `to(C)`     | C            |\n| `back()`    | B            |\n| `back()`    | A            |\n| `forward()` | B            |","concept":"Browser navigation maintains a history stack. `back()` moves one step backwards, while `forward()` moves one step forwards.","optionReview":"- A — Incorrect: the browser moves forward once after reaching A.\n- B — Correct: the final position is B.\n- C — Incorrect: C was left after the two backward operations.\n- D — Incorrect: navigation does not close the browser.","takeaway":"Trace navigation one operation at a time. Don't confuse the number of pages visited with the final history position."},
    {"id":"WDM-023","topic":"WebDriver methods","batch":2,"title":"Method return types","multi":true,"question":"Which statements are correct?","options":[["A","`getText()` returns `String`."],["B","`isSelected()` returns `boolean`."],["C","`clear()` returns `boolean`."],["D","`findElements()` returns `List<WebElement>`."]],"answer":["A","B","D"],"expected":"Not applicable — this is a return-type question.","steps":"There is no code to execute. Identify the return type of each method:\n\n| Method           | Return type        |\n| ---------------- | ------------------ |\n| `getText()`      | `String`           |\n| `isSelected()`   | `boolean`          |\n| `clear()`        | `void`             |\n| `findElements()` | `List<WebElement>` |","concept":"A method's return type tells Java what value it gives back to the calling code. `void` means it does not return a value.","optionReview":"- A — Correct: `getText()` returns visible text as a String.\n- B — Correct: `isSelected()` returns true or false.\n- C — Incorrect: `clear()` returns `void`.\n- D — Correct: `findElements()` returns a list of matching elements.","takeaway":"Memorise the return types of common Selenium methods. Questions often mix up `void`, `boolean`, `String`, and `List<WebElement>`."},
    {"id":"WDM-024","topic":"WebDriver methods","batch":2,"title":"Checkbox state","multi":false,"question":"A checkbox is displayed and enabled but unchecked.\n\n```\nWebElement checkbox = driver.findElement(By.id(\"terms\"));\n\nif (checkbox.isDisplayed() && checkbox.isEnabled()) {\n    checkbox.click();\n}\n\nSystem.out.println(checkbox.isSelected());\n```\n\nAssuming the click succeeds, what is printed?","options":[["A","`false`"],["B","`true`"],["C","`null`"],["D","`NoSuchElementException`"]],"answer":["B"],"expected":"```\ntrue\n```","steps":"1. `isDisplayed()` returns `true`.\n2. `isEnabled()` returns `true`.\n3. Both conditions are true, so the `if` block executes.\n4. `click()` selects the unchecked checkbox.","concept":"5\\. Concept explained\n\nThese three methods test different properties:\n\n- `isDisplayed()` — Is the element visible?\n- `isEnabled()` — Can the user interact with it?\n- `isSelected()` — Is it selected or checked?","optionReview":"- A — Incorrect: the checkbox was clicked and selected.\n- B — Correct: it is now checked.\n- C — Incorrect: `isSelected()` returns a boolean, not null.\n- D — Incorrect: the element was successfully located.","takeaway":"A click can change checkbox or radio-button state. Always trace the state before and after clicking."},
    {"id":"WDM-025","topic":"WebDriver methods","batch":2,"title":"Reading an input's current value","multi":false,"question":"HTML:\n\n```\n<input id=\"city\" value=\"Indore\">\n```\n\nJava:\n\n```\nWebElement city = driver.findElement(By.id(\"city\"));\n\ncity.clear();\ncity.sendKeys(\"Bhopal\");\n\nSystem.out.println(city.getAttribute(\"value\"));\n```\n\nWhat is printed?","options":[["A","`Indore`"],["B","`Bhopal`"],["C","`IndoreBhopal`"],["D","Empty string"]],"answer":["B"],"expected":"```\nBhopal\n```","steps":"1. The input initially contains `Indore`.\n2. `clear()` removes it.\n3. `sendKeys(\"Bhopal\")` enters the new value.\n4. `getAttribute(\"value\")` reads the current value.","concept":"For an input field, `getText()` is generally not the way to retrieve what the user typed. Use `getAttribute(\"value\")` in the conventional Selenium pattern. Selenium 4 also provides `getDomProperty(\"value\")` for reading the DOM property explicitly.","optionReview":"- A — Incorrect: the original value was cleared.\n- B — Correct: the current value is Bhopal.\n- C — Incorrect: the original value was removed.\n- D — Incorrect: new text was entered.","takeaway":"For input fields, remember the distinction between visible element text and the input's `value`."},
    {"id":"WDM-026","topic":"WebDriver methods","batch":2,"title":"`close()` vs `quit()`","multi":true,"question":"Which statements are correct?","options":[["A","`quit()` ends the WebDriver session."],["B","`close()` always closes every browser window."],["C","`close()` closes the current window."],["D","After `quit()`, the same WebDriver session can continue executing commands normally."]],"answer":["A","C"],"expected":"Not applicable — conceptual question.","steps":"There is no code to trace. Understand the two operations:\n\n- `driver.close()` closes the current browser window.\n- `driver.quit()` closes all windows associated with the session and terminates that session.","concept":"A WebDriver session represents the active automation connection to the browser. Once `quit()` terminates it, you cannot continue using that same session normally.","optionReview":"- A — Correct: `quit()` terminates the session.\n- B — Incorrect: `close()` targets the current window.\n- C — Correct: this is the purpose of `close()`.\n- D — Incorrect: the session has already been terminated.","takeaway":"`close()` = current window.\n\n`quit()` = all associated windows + session termination."},
    {"id":"WDM-027","topic":"WebDriver methods","batch":2,"title":"`findElements()` and list indexing","multi":false,"question":"Suppose there are three matching elements.\n\n```\nList<WebElement> items =\n    driver.findElements(By.className(\"item\"));\n\nSystem.out.println(items.size());\n\nSystem.out.println(items.get(2).getText());\n```\n\nAssume their texts in document order are `Red`, `Green`, `Blue`.\n\nWhat is printed?","options":[["A"," ``` 3 Green ```"],["B"," ``` 2 Blue ```"],["C"," ``` 3 Blue ```"],["D"," ``` 3 Red ```"]],"answer":["C"],"expected":"```\n3\nBlue\n```","steps":"1. `findElements()` finds three matching elements.\n2. `items.size()` returns `3`.\n3. Java list indexing starts at zero.\n4. Index `0` = Red.","concept":"","optionReview":"","takeaway":"5\\. Concept explained\n\n`findElements()` returns a list, and Java lists use zero-based indexing.\n\n6\\. All options analysed\n\n- A — Incorrect: index 2 is Blue, not Green.\n- B — Incorrect: the list contains three elements.\n- C — Correct: size is 3 and index 2 contains Blue.\n- D — Incorrect: Red is at index 0.\n\n7\\. Exam takeaway\n\nFor a list of \\\\(n\\\\) elements, valid indexes run from \\\\(0\\\\) to \\\\(n-1\\\\)."},
    {"id":"WDM-028","topic":"WebDriver methods","batch":2,"title":"`getText()` vs `getAttribute()`","multi":true,"question":"HTML:\n\n```\n<button id=\"save\" title=\"Save record\">Save</button>\n<input id=\"username\" value=\"Admin\">\n```\n\nWhich statements are correct?","options":[["A","`getText()` on the button returns `Save`."],["B","`getAttribute(\"title\")` on the button returns `Save record`."],["C","`getText()` on the input necessarily returns `Admin`."],["D","`getAttribute(\"value\")` on the input returns `Admin`."]],"answer":["A","B","D"],"expected":"Not applicable — multiple statements about returned values.","steps":"- Button's visible text is `Save`.\n- Button's `title` attribute is `Save record`.\n- Input's `value` is `Admin`.\n- The input's value is not necessarily returned by `getText()`.","concept":"`getText()` reads visible text content. `getAttribute()` reads an attribute or, depending on the attribute and Selenium implementation, the corresponding property value.","optionReview":"- A — Correct: `Save` is the button's visible text.\n- B — Correct: the title attribute is `Save record`.\n- C — Incorrect: an input's typed value is not its visible text content.\n- D — Correct: the input value is `Admin`.","takeaway":"For buttons and labels, consider `getText()`. For input values, consider `getAttribute(\"value\")` or Selenium 4's `getDomProperty(\"value\")`."},
    {"id":"WDM-029","topic":"WebDriver methods","batch":2,"title":"Getting the page title","multi":false,"question":"Which method is used to retrieve the title of the current webpage?","options":[["A","`driver.getCurrentUrl()`"],["B","`driver.getTitle()`"],["C","`driver.getText()`"],["D","`driver.navigate().getTitle()`"]],"answer":["B"],"expected":"The output depends on the webpage. For example, if the browser title is `Google`, `getTitle()` returns:\n\n```\nGoogle\n```","steps":"```\nString title = driver.getTitle();\nSystem.out.println(title);\n```\n\n1. `getTitle()` asks the browser for the current page title.\n2. It returns a String.\n3. `println()` prints that String.","concept":"`getTitle()` and `getCurrentUrl()` both retrieve page information, but they retrieve different things.","optionReview":"- A — Incorrect: retrieves the current URL.\n- B — Correct: retrieves the page title.\n- C — Incorrect: `getText()` is a WebElement method.\n- D — Incorrect: this is not the standard Selenium navigation API for retrieving a title.","takeaway":"Remember the pair:\n\n- `getTitle()` → page title.\n- `getCurrentUrl()` → current URL."},
    {"id":"WDM-030","topic":"WebDriver methods","batch":2,"title":"Combining WebElement methods","multi":true,"question":"Assume the button is displayed and enabled, and clicking it does not change the page.\n\n```\nWebElement button = driver.findElement(By.id(\"submit\"));\n\nSystem.out.println(button.isDisplayed());\n\nbutton.click();\n\nSystem.out.println(button.isEnabled());\n\nbutton.clear();\n```\n\nWhich statements are correct?","options":[["A","The first printed value is `true`."],["B","The second printed value is `true`."],["C","`click()` returns a boolean."],["D","`clear()` is not generally an appropriate operation for a button."]],"answer":["A","B","D"],"expected":"```\ntrue\ntrue\n```\n\nThe final `clear()` does not print anything. For a typical button, clearing is not an appropriate operation and may result in an `InvalidElementStateException`.","steps":"1. `findElement()` locates the button.\n2. `isDisplayed()` returns `true`, which is printed.\n3. `click()` clicks the button.\n4. The question states that the click does not change the page.","concept":"","optionReview":"5\\. Concept explained\n\nWebElement methods have different purposes:\n\n- `isDisplayed()` checks visibility.\n- `isEnabled()` checks whether the element is enabled.\n- `click()` performs a click.\n- `clear()` clears editable text fields.\n\n6\\. All options analysed\n\n- A — Correct: the button is displayed.\n- B — Correct: it remains enabled after clicking.\n- C — Incorrect: `click()` returns `void`.\n- D — Correct: `clear()` is intended for editable fields, not ordinary buttons.","takeaway":"Don't assume every WebElement method works meaningfully on every type of element. Check the element's nature and the method's purpose.\n\n## Batch 3 result and running progress\n\n# 10/10\n\nBatch 3 score\n\n# 30/30\n\nOverall MCQ score\n\nConcept check\\\n5/5\n\nBatch 1\\\n10/10\n\nBatch 2\\\n10/10\n\nBatch 3\\\n10/10\n\nNo genuine errors · No defective questions\n\nAll 30 questions have their seven-part explanations recorded. Your next batch will focus on more challenging mixed scenarios, including exceptions, method chaining and edge cases rather than repeating these same patterns."},
    {"id":"WDM-031","topic":"WebDriver methods","batch":3,"title":"findElement() exception","multi":false,"question":"No element with ID login exists on the page.\ntry {\n    WebElement element = driver.findElement(By.id(\"login\"));\n    System.out.println(\"Found\");\n} catch (NoSuchElementException e) {\n    System.out.println(\"Not Found\");\n}\n\n\nWhat happens?","options":[["A","Prints Found"],["B","Prints Not Found"],["C","Prints nothing"],["D","Returns an empty WebElement"]],"answer":["B"],"expected":"Not Found","steps":"1. Java enters the try block.\n2. findElement() searches for ID login.\n3. No matching element exists.\n4. Selenium throws NoSuchElementException.","concept":"","optionReview":"5. Concept explained\n\nfindElement() returns one matching WebElement. If no match exists, it throws NoSuchElementException.\n\n6. All options analysed\n- A — Incorrect: the element was not found.\n- B — Correct: the exception is caught and this message is printed.\n- C — Incorrect: the catch block prints a message.\n- D — Incorrect: an empty WebElement is not returned.","takeaway":"findElement() → one element or exception.\n\nfindElements() → list of elements or an empty list."},
    {"id":"WDM-032","topic":"WebDriver methods","batch":3,"title":"Empty result from findElements()","multi":true,"question":"No elements have the class name product.\nList<WebElement> products =\n    driver.findElements(By.className(\"product\"));\n\nSystem.out.println(products.size());\nSystem.out.println(products.isEmpty());\n\n\nWhich statements are correct?","options":[["A","The first output is 0."],["B","The second output is true."],["C","findElements() throws NoSuchElementException."],["D","products is an empty list."]],"answer":["A","B","D"],"expected":"0\ntrue","steps":"1. findElements() searches for all elements with class product.\n2. No matching elements are found.\n3. Selenium returns an empty list.\n4. size() returns 0.","concept":"5. Concept explained\n\nAn empty list is still a valid list object. It simply contains zero elements.","optionReview":"- A — Correct: the list has zero elements.\n- B — Correct: an empty list's isEmpty() returns true.\n- C — Incorrect: findElements() does not throw this exception when no matches exist.\n- D — Correct: the returned list is empty.","takeaway":"This is one of the most important Selenium distinctions:\nMethod\tNo match\nfindElement()\tNoSuchElementException\nfindElements()\tEmpty list"},
    {"id":"WDM-033","topic":"WebDriver methods","batch":3,"title":"Method ownership","multi":false,"question":"Which option correctly identifies the owner of all three methods?","options":[["A","getTitle() — WebElement; getText() — WebDriver; click() — WebDriver"],["B","getTitle() — WebDriver; getText() — WebElement; click() — WebElement"],["C","getTitle() — WebElement; getText() — WebElement; click() — WebDriver"],["D","All three belong to WebDriver."]],"answer":["B"],"expected":"Not applicable.","steps":"Identify what each method operates on:\n- getTitle() retrieves the browser page title.\n- getText() retrieves text from a page element.\n- click() performs an action on a page element.","concept":"WebDriver represents the browser automation session. WebElement represents an individual HTML element.","optionReview":"- A — Incorrect: ownership of all three methods is misassigned.\n- B — Correct: all three ownership assignments are accurate.\n- C — Incorrect: getTitle() and click() are assigned incorrectly.\n- D — Incorrect: getText() and click() belong to WebElement.","takeaway":"Ask yourself: Is the method operating on the whole browser or one element?"},
    {"id":"WDM-034","topic":"WebDriver methods","batch":3,"title":"Selenium 4 DOM methods","multi":true,"question":"Which statements about these methods are correct?","options":[["A","getDomAttribute(\"value\") retrieves the specified DOM attribute."],["B","getDomProperty(\"value\") retrieves the DOM property."],["C","getDomProperty() is a method of WebDriver."],["D","getDomAttribute() is a method of WebElement."]],"answer":["A","B","D"],"expected":"Not applicable.","steps":"These are WebElement methods:\nelement.getDomAttribute(\"value\");\nelement.getDomProperty(\"value\");\n\n\n- getDomAttribute() reads the DOM attribute.\n- getDomProperty() reads the DOM property.","concept":"An HTML attribute is part of the element's markup. A DOM property is part of the browser's live representation of that element. They can differ, particularly when JavaScript changes an element's current state.","optionReview":"- A — Correct: retrieves the specified DOM attribute.\n- B — Correct: retrieves the DOM property.\n- C — Incorrect: it belongs to WebElement.\n- D — Correct: it is a WebElement method.","takeaway":"Remember these Selenium 4 methods and their ownership. Don't confuse DOM attributes and DOM properties."},
    {"id":"WDM-035","topic":"WebDriver methods","batch":3,"title":"Clearing a non-editable element","multi":false,"question":"Consider:\nWebElement heading = driver.findElement(By.id(\"heading\"));\nheading.clear();\n\n\nAssume the element is a normal, non-editable h1 heading. What is the most likely result?","options":[["A","The heading text is cleared successfully."],["B","The method returns false."],["C","Selenium may throw InvalidElementStateException."],["D","Selenium automatically converts the heading into an input field."]],"answer":["C"],"expected":"No normal output is produced. The operation may throw InvalidElementStateException.","steps":"1. Selenium locates the heading.\n2. It attempts to execute clear().\n3. The heading is not an editable text field.\n4. Selenium may reject the operation with an invalid element state exception.","concept":"clear() is intended for editable elements such as text inputs and text areas. It is not a general-purpose method for removing text from any HTML element.","optionReview":"- A — Incorrect: a normal heading is not editable.\n- B — Incorrect: clear() does not return a boolean.\n- C — Correct: the operation may throw this exception.\n- D — Incorrect: Selenium does not change an element's HTML type.","takeaway":"Method availability does not mean every element supports that operation."},
    {"id":"WDM-036","topic":"WebDriver methods","batch":3,"title":"Navigation and URL","multi":true,"question":"Consider:\ndriver.get(\"https://example.com/home\");\ndriver.navigate().to(\"https://example.com/profile\");\ndriver.navigate().refresh();\n\nSystem.out.println(driver.getCurrentUrl());\n\n\nWhich statements are correct?","options":[["A","The current URL is expected to be the profile URL."],["B","refresh() navigates back to the home page."],["C","getCurrentUrl() returns a String."],["D","navigate().to() and get() can both navigate to a URL."]],"answer":["A","C","D"],"expected":"https://example.com/profile","steps":"1. get() navigates to /home.\n2. navigate().to() navigates to /profile.\n3. refresh() reloads the current page, /profile.\n4. getCurrentUrl() retrieves the current URL.","concept":"5. Concept explained\n\nRefreshing does not mean going back. It reloads the current page.","optionReview":"- A — Correct: the current page is profile.\n- B — Incorrect: refresh does not navigate to the previous page.\n- C — Correct: the return type is String.\n- D — Correct: both methods can navigate to a URL.","takeaway":"refresh() reloads. back() moves backwards in history. forward() moves forwards."},
    {"id":"WDM-037","topic":"WebDriver methods","batch":3,"title":"Java list indexing","multi":false,"question":"A page contains two elements with class name menu.\nList<WebElement> menus =\n    driver.findElements(By.className(\"menu\"));\n\nSystem.out.println(menus.get(1).getText());\n\n\nAssume their texts in document order are Home and Services. What is printed?","options":[["A","Home"],["B","Services"],["C","2"],["D","IndexOutOfBoundsException"]],"answer":["B"],"expected":"Services","steps":"- findElements() returns two elements.\n- Index 0 contains Home.\n- Index 1 contains Services.\n- get(1) retrieves the second element.\n- getText() retrieves its text.","concept":"Java collections use zero-based indexing.","optionReview":"- A — Incorrect: Home is at index 0.\n- B — Correct: Services is at index 1.\n- C — Incorrect: the code prints text, not the list size.\n- D — Incorrect: index 1 is valid for a two-element list.","takeaway":"For two elements, valid indexes are 0 and 1."},
    {"id":"WDM-038","topic":"WebDriver methods","batch":3,"title":"Checkbox state change","multi":true,"question":"A checkbox is initially selected and enabled.\nWebElement check = driver.findElement(By.id(\"accept\"));\n\nSystem.out.println(check.isSelected());\n\ncheck.click();\n\nSystem.out.println(check.isSelected());\n\n\nAssuming the click succeeds, which statements are correct?","options":[["A","The first output is true."],["B","The second output is false."],["C","click() returns boolean."],["D","isSelected() returns boolean."]],"answer":["A","B","D"],"expected":"true\nfalse","steps":"1. Initially, the checkbox is selected.\n2. First isSelected() returns true.\n3. click() toggles the checkbox off.\n4. Second isSelected() returns false.","concept":"Checkbox clicks usually toggle the selected state. An initially selected checkbox becomes unselected after one successful click.","optionReview":"- A — Correct: the checkbox starts selected.\n- B — Correct: clicking it deselects it.\n- C — Incorrect: click() returns void.\n- D — Correct: isSelected() returns boolean.","takeaway":"Always consider the initial checkbox state before tracing a click."},
    {"id":"WDM-039","topic":"WebDriver methods","batch":3,"title":"Terminating a browser session","multi":false,"question":"A Selenium script has opened three browser windows under the same WebDriver session. The requirement is to close all windows and terminate the automation session.\n\nWhich command should be used?","options":[["A","driver.close()"],["B","driver.quit()"],["C","driver.navigate().back()"],["D","driver.closeAll()"]],"answer":["B"],"expected":"Not applicable.","steps":"Calling:\ndriver.quit();\n\n\ncloses all windows associated with that WebDriver session and terminates the session.","concept":"A browser session can have multiple windows. close() targets the current window; quit() terminates the entire session.","optionReview":"- A — Incorrect: closes only the current window.\n- B — Correct: closes all associated windows and ends the session.\n- C — Incorrect: moves back in browser history.\n- D — Incorrect: closeAll() is not a standard WebDriver method.","takeaway":"If the question says all windows and terminate session, the answer is quit()."},
    {"id":"WDM-040","topic":"WebDriver methods","batch":3,"title":"Combined execution","multi":true,"question":"Assume the page contains:\n<input id=\"search\" value=\"Bank\">\n<button id=\"submit\">Search</button>\n\n\nJava:\nWebElement search = driver.findElement(By.id(\"search\"));\nWebElement submit = driver.findElement(By.id(\"submit\"));\n\nsearch.sendKeys(\" Exam\");\n\nSystem.out.println(search.getAttribute(\"value\"));\nSystem.out.println(submit.getText());\n\nSystem.out.println(submit.isDisplayed());\n\n\nWhich statements are correct?","options":[["A","The first output is Bank Exam."],["B","The second output is Search."],["C","The third output is true, assuming the button is visible."],["D","sendKeys() replaces Bank automatically."]],"answer":["A","B","C"],"expected":"Bank Exam\nSearch\ntrue","steps":"1. Selenium locates the input field.\n2. Selenium locates the button.\n3. sendKeys(\" Exam\") appends a space and Exam to the existing Bank.\n4. getAttribute(\"value\") returns Bank Exam.","concept":"","optionReview":"5. Concept explained\n\nThis question combines three different WebElement operations:\n- sendKeys() — enters text.\n- getAttribute(\"value\") — retrieves the input's current value.\n- getText() — retrieves visible text.\n- isDisplayed() — checks visibility.\n6. All options analysed\n- A — Correct: sendKeys() appends to the existing input value.\n- B — Correct: the button's visible text is Search.\n- C — Correct: the question explicitly says the button is visible.\n- D — Incorrect: sendKeys() does not automatically replace existing text. Use clear() first if replacement is intended.","takeaway":"When you see sendKeys() without a preceding clear(), check whether the input already contains text. It normally appends rather than replaces.\n\nUpdated WebDriver progress\n39/40\nMCQs across four batches\n\n97.5%\nOverall accuracy\n\n\n\nAssessment\tScore\nConcept check\t5/5\nBatch 1\t10/10\nBatch 2\t10/10\nBatch 3\t10/10\nBatch 4\t9/10\n\n40 questions reviewed · 0 defective questions\n\nRevision point: sendKeys() appends text; it does not automatically replace existing input content.\n\nYour next batch will be a harder mixed set, with more code tracing and realistic Selenium scenarios."},
    {"id":"WDM-041","topic":"WebDriver methods","batch":4,"title":"Empty list and indexing","multi":false,"question":"No element with class name result exists on the page.\nList<WebElement> results =\n    driver.findElements(By.className(\"result\"));\n\nSystem.out.println(results.size());\nSystem.out.println(results.get(0).getText());\n\n\nWhat happens?","options":[["A"," 0 Then the program continues normally."],["B"," 0 Then an IndexOutOfBoundsException occurs."],["C","A NoSuchElementException occurs before the first print."],["D","An empty String is printed."]],"answer":["B"],"expected":"0\n\n\nThen an IndexOutOfBoundsException occurs.","steps":"1. findElements() finds no matching elements.\n2. It returns an empty list.\n3. results.size() returns 0.\n4. The first print executes.","concept":"","optionReview":"5. Concept explained\n\nAn empty list is not an exception. However, accessing an invalid index in that list causes an exception.\n\n6. All options analysed\n- A — Incorrect: execution cannot continue normally after accessing index 0.\n- B — Correct: zero is printed before the indexing exception.\n- C — Incorrect: findElements() does not throw NoSuchElementException for no matches.\n- D — Incorrect: the code does not print an empty String.","takeaway":"findElements() can return an empty list, but accessing an element that doesn't exist causes IndexOutOfBoundsException."},
    {"id":"WDM-042","topic":"WebDriver methods","batch":4,"title":"Input value and clearing","multi":true,"question":"HTML:\n<input id=\"email\" value=\"user@example.com\">\n\n\nJava:\nWebElement email = driver.findElement(By.id(\"email\"));\n\nemail.sendKeys(\".in\");\nSystem.out.println(email.getAttribute(\"value\"));\n\nemail.clear();\nSystem.out.println(email.getAttribute(\"value\"));\n\n\nWhich statements are correct?","options":[["A","The first printed value is user@example.com.in."],["B","The second printed value is an empty String."],["C","sendKeys() automatically removes the original value."],["D","clear() returns void."]],"answer":["A","B","D"],"expected":"user@example.com.in\n\n\nThe second line is empty.","steps":"1. Initial value is user@example.com.\n2. sendKeys(\".in\") appends .in.\n3. First getAttribute(\"value\") returns user@example.com.in.\n4. clear() empties the field.","concept":"5. Concept explained\n\nclear() is an action method. It changes the element's contents but does not return a result.\n\nIts return type is void.","optionReview":"- A — Correct: .in is appended to the original value.\n- B — Correct: clear() empties the field.\n- C — Incorrect: sendKeys() does not automatically remove existing text.\n- D — Correct: clear() returns void.","takeaway":"Memorise this:\nMethod\tReturn type\nclear()\tvoid\nsendKeys()\tvoid\nclick()\tvoid\ngetAttribute()\tString\n\nYour mistake was not in understanding the output; you missed a return-type statement."},
    {"id":"WDM-043","topic":"WebDriver methods","batch":4,"title":"Navigation sequence","multi":false,"question":"driver.get(\"https://test.com/one\");\ndriver.navigate().to(\"https://test.com/two\");\ndriver.navigate().to(\"https://test.com/three\");\n\ndriver.navigate().back();\ndriver.navigate().forward();\ndriver.navigate().refresh();\n\nSystem.out.println(driver.getCurrentUrl());\n\n\nWhat is the expected final URL?","options":[["A","https://test.com/one"],["B","https://test.com/two"],["C","https://test.com/three"],["D","The browser returns an empty URL."]],"answer":["C"],"expected":"https://test.com/three","steps":"Operation\tCurrent page\nget(one)\tone\nto(two)\ttwo\nto(three)\tthree\nback()\ttwo\nforward()\tthree\nrefresh()\tthree","concept":"refresh() reloads the current page without moving to another history entry.","optionReview":"- A — Incorrect: the browser never navigates back twice.\n- B — Incorrect: forward moves from two to three.\n- C — Correct: three remains the current page.\n- D — Incorrect: refreshing does not produce an empty URL.","takeaway":"Trace every navigation operation in order. Refresh does not change the current history position."},
    {"id":"WDM-044","topic":"WebDriver methods","batch":4,"title":"Return types and assignment","multi":true,"question":"Consider the following statements:","options":[["A"," String title = driver.getTitle(); This is valid."],["B"," boolean visible = element.isDisplayed(); This is valid."],["C"," boolean result = element.click(); This is valid."],["D"," List<WebElement> elements = driver.findElements(By.tagName(\"a\")); This is valid."]],"answer":["A","B","D"],"expected":"Not applicable — this tests Java type compatibility.","steps":"- A: getTitle() returns String, so assignment is valid.\n- B: isDisplayed() returns boolean, so assignment is valid.\n- C: click() returns void, so it cannot be assigned to a boolean.\n- D: findElements() returns List<WebElement>, so assignment is valid.","concept":"Java requires the receiving variable's type to be compatible with the method's return type.","optionReview":"- A — Correct: String matches String.\n- B — Correct: boolean matches boolean.\n- C — Incorrect: void cannot be assigned.\n- D — Correct: list return type matches the declared variable.","takeaway":"When a question asks whether a statement compiles, check the method's return type first."},
    {"id":"WDM-045","topic":"WebDriver methods","batch":4,"title":"Checkbox logic","multi":false,"question":"A checkbox is initially unchecked and enabled.\nWebElement check = driver.findElement(By.id(\"news\"));\n\nif (!check.isSelected()) {\n    check.click();\n}\n\nif (check.isSelected()) {\n    check.click();\n}\n\nSystem.out.println(check.isSelected());\n\n\nWhat is printed?","options":[["A","true"],["B","false"],["C","null"],["D","NoSuchElementException"]],"answer":["B"],"expected":"false","steps":"1. Initially unchecked: isSelected() returns false.\n2. !false becomes true, so the first click selects it.\n3. The second condition now evaluates to true.\n4. The second click deselects it.","concept":"5. Concept explained\n\nA checkbox toggles its state when clicked. The ! operator reverses a boolean value.","optionReview":"- A — Incorrect: the checkbox is clicked twice.\n- B — Correct: two clicks return it to its original unchecked state.\n- C — Incorrect: isSelected() returns boolean.\n- D — Incorrect: the element is successfully located.","takeaway":"For a checkbox, two successful clicks normally restore its initial state."},
    {"id":"WDM-046","topic":"WebDriver methods","batch":4,"title":"Browser windows","multi":true,"question":"A WebDriver session has two open windows: Window A and Window B. Window B is currently active.\n\nWhich statements are correct?","options":[["A","driver.close() closes Window B."],["B","driver.quit() terminates the session and closes its associated windows."],["C","driver.close() necessarily terminates the entire WebDriver session."],["D","After closing Window B, Window A may remain open."]],"answer":["A","B","D"],"expected":"Not applicable.","steps":"- close() closes the current active window, B.\n- Window A may remain open.\n- quit() closes all windows associated with the session and terminates it.","concept":"A browser session can contain multiple windows. Closing one window and terminating the session are different operations.","optionReview":"- A — Correct: B is the active window.\n- B — Correct: quit() terminates the session.\n- C — Incorrect: close() does not necessarily terminate the entire session.\n- D — Correct: A can remain open.","takeaway":"Remember the distinction between closing the active window and ending the whole WebDriver session."},
    {"id":"WDM-047","topic":"WebDriver methods","batch":4,"title":"Visible text vs input value","multi":false,"question":"HTML:\n<input id=\"amount\" value=\"500\">\n\n\nJava:\nWebElement amount = driver.findElement(By.id(\"amount\"));\n\nSystem.out.println(amount.getText());\nSystem.out.println(amount.getAttribute(\"value\"));\n\n\nWhich is the expected result for this ordinary input element?","options":[["A"," 500 500"],["B"," 500"],["C"," 500"],["D"," null 500"]],"answer":["B"],"expected":"500","steps":"1. getText() reads visible text content. An ordinary input does not expose its entered value as visible text content.\n2. Therefore, the first output is empty.\n3. getAttribute(\"value\") retrieves the input value.\n4. The second output is 500.","concept":"An input's value and its visible text content are different things. This distinction is especially important in Selenium questions.","optionReview":"- A — Incorrect: getText() does not normally return the input value.\n- B — Correct: first line empty, second line 500.\n- C — Incorrect: the outputs are reversed.\n- D — Incorrect: the expected first result is an empty String, not the literal text null.","takeaway":"For an ordinary input field, use getAttribute(\"value\") to retrieve its current value in the conventional Selenium pattern."},
    {"id":"WDM-048","topic":"WebDriver methods","batch":4,"title":"Method behaviour","multi":true,"question":"Which statements are correct?","options":[["A","driver.getTitle() retrieves the title of the current page."],["B","element.getText() retrieves the current browser URL."],["C","driver.navigate().refresh() reloads the current page."],["D","element.isEnabled() returns a boolean."]],"answer":["A","C","D"],"expected":"Not applicable.","steps":"There is no code to trace. Identify the purpose of each method.","concept":"- getTitle() → browser page title.\n- getText() → element's visible text.\n- refresh() → reload current page.\n- isEnabled() → element enabled state.","optionReview":"- A — Correct.\n- B — Incorrect: getText() does not retrieve the browser URL.\n- C — Correct.\n- D — Correct.","takeaway":"Know the difference between browser-level methods and element-level methods."},
    {"id":"WDM-049","topic":"WebDriver methods","batch":4,"title":"Exception and control flow","multi":false,"question":"Assume the element with ID submit does not exist.\ntry {\n    WebElement button = driver.findElement(By.id(\"submit\"));\n    button.click();\n    System.out.println(\"Clicked\");\n} catch (NoSuchElementException e) {\n    System.out.println(\"Missing\");\n} finally {\n    System.out.println(\"Finished\");\n}\n\n\nWhat is printed?","options":[["A"," Clicked Finished"],["B"," Missing Finished"],["C"," Missing"],["D"," Finished Clicked"]],"answer":["B"],"expected":"Missing\nFinished","steps":"1. Java enters the try block.\n2. findElement() cannot find the element.\n3. It throws NoSuchElementException.\n4. The click() and Clicked print statements are skipped.","concept":"","optionReview":"5. Concept explained\n\nJava exception handling:\n- try contains code that may throw an exception.\n- catch handles a matching exception.\n- finally executes after the try/catch flow, including when an exception is caught.\n6. All options analysed\n- A — Incorrect: Clicked is never printed.\n- B — Correct: both catch and finally messages appear.\n- C — Incorrect: the finally block also executes.\n- D — Incorrect: Clicked cannot execute after the failed element lookup.","takeaway":"Remember that finally normally executes whether an exception occurs or not."},
    {"id":"WDM-050","topic":"WebDriver methods","batch":4,"title":"Selenium 4 DOM methods","multi":true,"question":"HTML:\n<input id=\"quantity\" value=\"10\">\n\n\nAssume JavaScript changes the input's current DOM property value to 25 without changing its original HTML attribute.\n\nWhich statements are correct?","options":[["A","getDomAttribute(\"value\") can return 10."],["B","getDomProperty(\"value\") can return 25."],["C","getDomProperty(\"value\") is a WebDriver method."],["D","getDomAttribute() and getDomProperty() are WebElement methods."]],"answer":["A","B","D"],"expected":"If printed separately:\n10\n25","steps":"1. The original HTML attribute is value=\"10\".\n2. JavaScript changes the live DOM property to 25.\n3. getDomAttribute(\"value\") reads the original attribute, which remains 10.\n4. getDomProperty(\"value\") reads the live property, which is 25.","concept":"This is an important Selenium 4 distinction:\nMethod\tReads\ngetDomAttribute()\tDOM attribute\ngetDomProperty()\tDOM property\n\nBoth are methods of WebElement.","optionReview":"- A — Correct: the original attribute remains 10.\n- B — Correct: the live property is 25.\n- C — Incorrect: it belongs to WebElement.\n- D — Correct: both methods belong to WebElement.","takeaway":"When JavaScript changes an input's current value, the DOM property can differ from the original HTML attribute.\n\nUpdated WebDriver progress\n48/50\nAll five batches combined, including concept check\n\n96%\nOverall accuracy\n\n\n\nAssessment\tScore\nConcept check\t5/5\nBatch 1\t10/10\nBatch 2\t10/10\nBatch 3\t10/10\nBatch 4\t9/10\nBatch 5\t9/10\n\n50 questions reviewed · 0 defective questions\n\nYour revision point: Return types of Selenium action methods, especially clear(), click() and sendKeys() — all return void.\n\nThe seven-part explanations for WDM-001 through WDM-050 are now covered. Next, we can do a final mixed assessment before marking this combined WebDriver methods unit complete."},
    {"id":"WDM-051","topic":"WebDriver methods","batch":5,"title":"Java execution and URL retrieval","multi":false,"question":"```\ndriver.get(\"https://example.com\");\n\nString first = driver.getCurrentUrl();\ndriver.navigate().to(\"https://google.com\");\nString second = driver.getCurrentUrl();\n\nSystem.out.println(first.contains(\"example\"));\nSystem.out.println(second.contains(\"google\"));\n```\n\nWhat is printed?","options":[["A"," ``` false true ```"],["B"," ``` true true ```"],["C"," ``` true false ```"],["D"," ``` false false ```"]],"answer":["B"],"expected":"```\ntrue\ntrue\n```","steps":"1. Browser navigates to example.com.\n2. `first` stores its URL.\n3. Browser navigates to google.com.\n4. `second` stores the new URL.","concept":"5\\. Concept explained\n\n`getCurrentUrl()` returns the current URL as a String. Assigning it to a variable preserves that value even after subsequent navigation.","optionReview":"- A — Incorrect: both conditions are true.\n- B — Correct.\n- C — Incorrect: `first` contains `example`.\n- D — Incorrect: both URLs contain their tested words.","takeaway":"A String variable stores the value retrieved at that moment; later browser navigation does not change the already stored String."},
    {"id":"WDM-052","topic":"WebDriver methods","batch":5,"title":"Element method return types","multi":true,"question":"Which statements are correct?","options":[["A","`getText()` returns a String.\\"],["B","`isDisplayed()` returns a boolean.\\"],["C","`sendKeys()` returns a String.\\"],["D","`clear()` returns void."]],"answer":["A","B","D"],"expected":"Not applicable.","steps":"Identify each return type:\n\n- `getText()` → String\n- `isDisplayed()` → boolean\n- `sendKeys()` → void\n- `clear()` → void","concept":"Return types tell Java what a method gives back to its caller. `void` means no value is returned.","optionReview":"- A — Correct.\n- B — Correct.\n- C — Incorrect: `sendKeys()` returns void.\n- D — Correct.","takeaway":"Remember the return types of action methods versus information-retrieval methods."},
    {"id":"WDM-053","topic":"WebDriver methods","batch":5,"title":"Browser navigation history","multi":false,"question":"The browser has visited A, B and C in that order.\n\n```\ndriver.navigate().back();\ndriver.navigate().back();\ndriver.navigate().forward();\ndriver.navigate().refresh();\n```\n\nWhich page is displayed after all operations?","options":[["A","A\\"],["B","B\\"],["C","C\\"],["D","No page"]],"answer":["B"],"expected":"The current page is B.","steps":"| Operation   | Current page |\n| ----------- | ------------ |\n| Initially   | C            |\n| First back  | B            |\n| Second back | A            |\n| Forward     | B            |\n| Refresh     | B            |","concept":"Navigation history moves backward and forward. Refresh reloads the current entry without changing its position.","optionReview":"- A — Incorrect: forward moves from A to B.\n- B — Correct.\n- C — Incorrect: the browser does not move forward to C.\n- D — Incorrect: the page remains open.","takeaway":"Always trace history in order. Refresh does not change the current page."},
    {"id":"WDM-054","topic":"WebDriver methods","batch":5,"title":"Empty `findElements()` result","multi":false,"question":"```\nList<WebElement> elements =\n    driver.findElements(By.tagName(\"xyz\"));\n\nSystem.out.println(elements.size());\n```\n\nAssume there are no matching elements. What happens?","options":[["A","`NoSuchElementException`\\"],["B","`IndexOutOfBoundsException`\\"],["C","Prints `0`\\"],["D","Prints `null`"]],"answer":["C"],"expected":"```\n0\n```","steps":"1. `findElements()` searches for matching elements.\n2. No matches are found.\n3. It returns an empty list.\n4. `size()` returns zero.","concept":"5\\. Concept explained\n\nAn empty list is a valid collection, not an exception.","optionReview":"- A — Incorrect: this is the typical no-match behaviour of `findElement()`.\n- B — Incorrect: no invalid index is accessed.\n- C — Correct.\n- D — Incorrect: the returned list is not null.","takeaway":"`findElements()` with no matches returns an empty list."},
    {"id":"WDM-055","topic":"WebDriver methods","batch":5,"title":"Clearing and entering input","multi":true,"question":"HTML:\n\n```\n<input id=\"user\" value=\"Admin\">\n```\n\nJava:\n\n```\nWebElement user = driver.findElement(By.id(\"user\"));\nuser.sendKeys(\"123\");\nuser.clear();\nuser.sendKeys(\"Guest\");\n\nSystem.out.println(user.getAttribute(\"value\"));\n```\n\nWhich statements are correct?","options":[["A","Final value is `Guest`.\\"],["B","Final value is `Admin123Guest`.\\"],["C","`clear()` removes the previous value.\\"],["D","The printed value is an empty String."]],"answer":["A","C"],"expected":"```\nGuest\n```","steps":"1. Initial value: `Admin`.\n2. `sendKeys(\"123\")` appends `123`.\n3. Current value: `Admin123`.\n4. `clear()` removes the entire value.","concept":"","optionReview":"5\\. Concept explained\n\n`sendKeys()` appends to existing content; `clear()` empties the editable field.\n\n6\\. All options analysed\n\n- A — Correct.\n- B — Incorrect: `clear()` removes `Admin123`.\n- C — Correct.\n- D — Incorrect: Guest is entered after clearing.","takeaway":"When several input operations appear together, trace the value after every operation."},
    {"id":"WDM-056","topic":"WebDriver methods","batch":5,"title":"Repeated checkbox clicks","multi":false,"question":"A checkbox starts unchecked.\n\n```\nWebElement box = driver.findElement(By.id(\"terms\"));\n\nbox.click();\nbox.click();\nbox.click();\n\nSystem.out.println(box.isSelected());\n```\n\nWhat is printed?","options":[["A","`true`\\"],["B","`false`\\"],["C","`null`\\"],["D","Compilation error"]],"answer":["A"],"expected":"```\ntrue\n```","steps":"- Initially unchecked.\n- First click: selected.\n- Second click: deselected.\n- Third click: selected.\n- `isSelected()` returns true.","concept":"A checkbox normally toggles between selected and unselected after each successful click.","optionReview":"- A — Correct: three clicks leave it selected.\n- B — Incorrect: this would be the result after two clicks.\n- C — Incorrect: return type is boolean.\n- D — Incorrect: the code is valid.","takeaway":"An odd number of successful checkbox clicks reverses its initial state; an even number restores it."},
    {"id":"WDM-057","topic":"WebDriver methods","batch":5,"title":"Closing browser windows","multi":true,"question":"Which statements are correct?","options":[["A","`close()` closes the current window.\\"],["B","`quit()` terminates the WebDriver session.\\"],["C","`close()` and `quit()` always have identical effects.\\"],["D","`quit()` closes all windows associated with the session."]],"answer":["A","B","D"],"expected":"Not applicable.","steps":"- `close()` closes the current window.\n- `quit()` closes all windows associated with the session and terminates the session.","concept":"A WebDriver session may contain multiple windows. Closing one window does not necessarily terminate the entire session.","optionReview":"- A — Correct.\n- B — Correct.\n- C — Incorrect: their effects differ.\n- D — Correct.","takeaway":"`close()` means current window; `quit()` means session termination."},
    {"id":"WDM-058","topic":"WebDriver methods","batch":5,"title":"Return-type compilation error","multi":false,"question":"Which statement will cause a compilation error?","options":[["A"," ``` String url = driver.getCurrentUrl(); ```"],["B"," ``` boolean enabled = element.isEnabled(); ```"],["C"," ``` String result = element.click(); ```"],["D"," ``` String text = element.getText(); ```"]],"answer":["C"],"expected":"Not applicable — the question concerns compilation.","steps":"- A: String returned, String variable — valid.\n- B: boolean returned, boolean variable — valid.\n- C: void returned, String variable — invalid.\n- D: String returned, String variable — valid.","concept":"Java does not allow a void method call to be assigned to a variable.","optionReview":"- A — Valid.\n- B — Valid.\n- C — Compilation error.\n- D — Valid.","takeaway":"If you see an assignment involving a Selenium method, check the return type before considering anything else."},
    {"id":"WDM-059","topic":"WebDriver methods","batch":5,"title":"Visibility and enabled state","multi":false,"question":"Assume the button is displayed and enabled.\n\n```\nWebElement button = driver.findElement(By.id(\"save\"));\n\nif (button.isDisplayed()) {\n    System.out.println(\"Visible\");\n}\n\nif (button.isEnabled()) {\n    System.out.println(\"Enabled\");\n}\n\nbutton.click();\n```\n\nWhat is printed?","options":[["A"," ``` Visible ```"],["B"," ``` Enabled ```"],["C"," ``` Visible Enabled ```"],["D","Nothing"]],"answer":["C"],"expected":"```\nVisible\nEnabled\n```","steps":"1. The button is displayed, so the first condition is true.\n2. `Visible` is printed.\n3. The button is enabled, so the second condition is true.\n4. `Enabled` is printed.","concept":"5\\. Concept explained\n\nVisibility and enabled state are independent properties. A button can be visible but disabled, or hidden but enabled.","optionReview":"- A — Incorrect: the second condition is also true.\n- B — Incorrect: the first condition is also true.\n- C — Correct.\n- D — Incorrect: both print statements execute.","takeaway":"Never treat `isDisplayed()` and `isEnabled()` as interchangeable."},
    {"id":"WDM-060","topic":"WebDriver methods","batch":5,"title":"DOM attributes and properties","multi":true,"question":"Assume the original HTML is:\n\n```\n<input id=\"age\" value=\"20\">\n```\n\nJavaScript changes the live DOM property to `30` but leaves the original HTML attribute unchanged.\n\nWhich statements are correct?","options":[["A","`getDomAttribute(\"value\")` can return `20`.\\"],["B","`getDomProperty(\"value\")` can return `30`.\\"],["C","Both methods belong to WebElement.\\"],["D","`getDomProperty()` returns the current browser URL."]],"answer":["A","B","C"],"expected":"If both values are printed:\n\n```\n20\n30\n```","steps":"1. Original HTML attribute is 20.\n2. JavaScript changes the live DOM property to 30.\n3. `getDomAttribute()` reads the attribute.\n4. `getDomProperty()` reads the property.","concept":"DOM attributes and properties represent related but distinct information. The attribute can preserve the original markup value while the property reflects the current live state.","optionReview":"- A — Correct.\n- B — Correct.\n- C — Correct.\n- D — Incorrect: browser URL retrieval uses `driver.getCurrentUrl()`.","takeaway":"Remember the difference between the original HTML attribute and the live DOM property."},
    {"id":"WDM-061","topic":"WebDriver methods","batch":6,"title":"`findElement()` vs `findElements()`","multi":false,"question":"There are five elements matching a locator.\n\n```\nWebElement first = driver.findElement(By.className(\"card\"));\nList<WebElement> all = driver.findElements(By.className(\"card\"));\n\nSystem.out.println(all.size());\nSystem.out.println(first.getText());\n```\n\nWhich statement is correct?","options":[["A","The first line prints `1`.\\"],["B","The first line prints `5`, and the second prints the first matching element's text.\\"],["C","Both methods return lists.\\"],["D","`findElement()` throws an exception because there are multiple matches."]],"answer":["B"],"expected":"The first line is:\n\n```\n5\n```\n\nThe second line is the text of the first matching card.","steps":"1. `findElement()` returns the first matching WebElement.\n2. `findElements()` returns all five matching elements.\n3. `all.size()` returns five.\n4. `first.getText()` retrieves the first matching element's text.","concept":"`findElement()` does not fail just because multiple elements match. It returns the first one.","optionReview":"- A — Incorrect: the list has five matches.\n- B — Correct.\n- C — Incorrect: `findElement()` returns one WebElement.\n- D — Incorrect: multiple matches are allowed.","takeaway":"Multiple matches are not an exception for `findElement()`; it returns the first match."},
    {"id":"WDM-062","topic":"WebDriver methods","batch":6,"title":"Navigation methods","multi":true,"question":"Which statements are correct?","options":[["A","`driver.navigate().back()` moves to the previous history entry.\\"],["B","`driver.navigate().forward()` moves to the next history entry.\\"],["C","`driver.navigate().refresh()` terminates the browser session.\\"],["D","`driver.navigate().to(url)` navigates to the specified URL."]],"answer":["A","B","D"],"expected":"Not applicable.","steps":"- `back()` → previous history entry.\n- `forward()` → next history entry.\n- `refresh()` → reload current page.\n- `to(url)` → navigate to specified URL.","concept":"The navigation interface controls browser history and page navigation. It does not terminate the session.","optionReview":"- A — Correct.\n- B — Correct.\n- C — Incorrect: refresh reloads the current page.\n- D — Correct.","takeaway":"Know the four navigation operations and their distinct purposes."},
    {"id":"WDM-063","topic":"WebDriver methods","batch":6,"title":"Button text and title attribute","multi":false,"question":"HTML:\n\n```\n<button id=\"login\" title=\"Login button\">Sign In</button>\n```\n\nWhat does this code print?\n\n```\nWebElement login = driver.findElement(By.id(\"login\"));\n\nSystem.out.println(login.getText());\nSystem.out.println(login.getAttribute(\"title\"));\n```","options":[["A"," ``` Login button Sign In ```"],["B"," ``` Sign In Login button ```"],["C"," ``` Sign In Sign In ```"],["D"," ``` Login button Login button ```"]],"answer":["B"],"expected":"```\nSign In\nLogin button\n```","steps":"1. `getText()` retrieves visible button text: `Sign In`.\n2. `getAttribute(\"title\")` retrieves the title attribute: `Login button`.\n3. Both values are printed in order.","concept":"Visible text and HTML attributes are separate pieces of information.","optionReview":"- A — Incorrect: the two values are reversed.\n- B — Correct.\n- C — Incorrect: title is not the button's visible text.\n- D — Incorrect: visible text is not the title attribute.","takeaway":"Read the HTML carefully. Identify which value is visible text and which is an attribute."},
    {"id":"WDM-064","topic":"WebDriver methods","batch":6,"title":"Element states","multi":true,"question":"Which statements are correct?","options":[["A","A hidden element can be enabled.\\"],["B","A visible checkbox can be unchecked.\\"],["C","`isSelected()` is used to check whether an element is visible.\\"],["D","`isDisplayed()` checks visibility."]],"answer":["A","B","D"],"expected":"Not applicable.","steps":"There is no code to execute. Consider the properties independently.","concept":"- Visibility and enabled state are different.\n- A checkbox can be visible and unchecked.\n- Selection state and visibility are not the same.","optionReview":"- A — Correct: visibility does not necessarily determine enabled state.\n- B — Correct: a visible checkbox can be unchecked.\n- C — Incorrect: `isSelected()` checks selection state.\n- D — Correct: `isDisplayed()` checks visibility.","takeaway":"Memorise the three independent checks: displayed, enabled and selected."},
    {"id":"WDM-065","topic":"WebDriver methods","batch":6,"title":"Command after `quit()`","multi":false,"question":"Assume the element exists, but the browser session has already been terminated using `driver.quit()`.\n\n```\nWebElement element = driver.findElement(By.id(\"name\"));\n```\n\nWhat is the most likely result?","options":[["A","`NoSuchElementException`\\"],["B","`NoSuchSessionException`\\"],["C","An empty WebElement\\"],["D","The element is returned normally"]],"answer":["B"],"expected":"No element is returned. A `NoSuchSessionException` is the expected result when attempting to use a terminated WebDriver session.","steps":"1. `quit()` has already terminated the session.\n2. A new WebDriver command is issued.\n3. Selenium cannot use the terminated session.\n4. A session-related exception is raised.","concept":"`NoSuchElementException` means the session is active but the requested element cannot be found. `NoSuchSessionException` indicates that the WebDriver session is no longer available.","optionReview":"- A — Incorrect: this describes an active session with a missing element.\n- B — Correct.\n- C — Incorrect: Selenium does not return an empty WebElement.\n- D — Incorrect: the session is terminated.","takeaway":"Distinguish element lookup failure from session failure."},
    {"id":"WDM-066","topic":"WebDriver methods","batch":6,"title":"String length and `sendKeys()`","multi":false,"question":"Assume the input initially contains `RBI`.\n\n```\nWebElement input = driver.findElement(By.id(\"exam\"));\n\ninput.sendKeys(\" Grade\");\ninput.sendKeys(\" B\");\n\nSystem.out.println(input.getAttribute(\"value\").length());\n```\n\nWhat is printed?","options":[["A","`3`\\"],["B","`8`\\"],["C","`10`\\"],["D","`11`"]],"answer":["D"],"expected":"```\n11\n```","steps":"Final String:\n\n```\nRBI Grade B\n```\n\nCharacter count:\n\n- `RBI` = 3\n- First space = 1\n- `Grade` = 5\n- Second space = 1\n- `B` = 1\n\nTotal = 11.","concept":"Java's String `length()` method counts all characters, including spaces.","optionReview":"- A — Incorrect: counts only RBI.\n- B — Incorrect: misses some characters.\n- C — Incorrect: one character is missing from the count.\n- D — Correct.","takeaway":"When calculating String length, count spaces too. `sendKeys()` appends unless the field is cleared."},
    {"id":"WDM-067","topic":"WebDriver methods","batch":6,"title":"Browser session termination","multi":true,"question":"Which statements are correct?","options":[["A","After `driver.quit()`, commands on that terminated session normally fail.\\"],["B","`driver.close()` closes every window associated with the session.\\"],["C","`driver.quit()` is generally appropriate at the end of a test session.\\"],["D","`driver.close()` closes the current window."]],"answer":["A","C","D"],"expected":"Not applicable.","steps":"This is a conceptual question about browser lifecycle:\n\n- A terminated session cannot normally accept further commands.\n- `quit()` is the usual cleanup operation at the end of a test.\n- `close()` targets the current window.","concept":"Session cleanup is important in automation because it releases browser resources and ends the automation connection.","optionReview":"- A — Correct.\n- B — Incorrect: `close()` targets the current window.\n- C — Correct.\n- D — Correct.","takeaway":"Use `quit()` for final session cleanup; don't confuse it with `close()`."},
    {"id":"WDM-068","topic":"WebDriver methods","batch":6,"title":"Checking checkbox selection","multi":false,"question":"You need to verify that a checkbox is checked before submitting a form. Which method should you use?","options":[["A","`isDisplayed()`\\"],["B","`isEnabled()`\\"],["C","`isSelected()`\\"],["D","`getCurrentUrl()`"]],"answer":["C"],"expected":"The method returns either `true` or `false`.","steps":"```\nboolean checked = checkbox.isSelected();\n```\n\nIf checked, the returned value is `true`; otherwise, it is `false`.","concept":"`isSelected()` is intended for checking selection state, including checkboxes and radio buttons.","optionReview":"- A — Incorrect: checks visibility.\n- B — Incorrect: checks enabled state.\n- C — Correct: checks selection state.\n- D — Incorrect: retrieves the current browser URL.","takeaway":"For checked/unchecked questions, identify `isSelected()`."},
    {"id":"WDM-069","topic":"WebDriver methods","batch":6,"title":"List traversal and output","multi":true,"question":"Assume two matching elements exist, with texts `First` and `Second`.\n\n```\nList<WebElement> links =\n    driver.findElements(By.tagName(\"a\"));\n\nSystem.out.println(links.get(0).getText());\nSystem.out.println(links.get(1).getText());\nSystem.out.println(links.size());\n```\n\nWhich statements are correct?","options":[["A","The first output is `First`.\\"],["B","The second output is `Second`.\\"],["C","The third output is `2`.\\"],["D","The list's first index is `1`."]],"answer":["A","B","C"],"expected":"```\nFirst\nSecond\n2\n```","steps":"1. `findElements()` returns two matching elements.\n2. Index 0 contains First.\n3. Index 1 contains Second.\n4. `size()` returns 2.","concept":"Java lists use zero-based indexing. The first element is at index 0.","optionReview":"- A — Correct.\n- B — Correct.\n- C — Correct.\n- D — Incorrect: the first index is 0.","takeaway":"Remember the difference between an element's position and its index: first position corresponds to index 0."},
    {"id":"WDM-070","topic":"WebDriver methods","batch":6,"title":"Integrated Selenium scenario","multi":true,"question":"Assume the browser is on a page containing:\n\n```\n<input id=\"search\" value=\"Bank\">\n<button id=\"find\">Find</button>\n```\n\nJava:\n\n```\nWebElement search = driver.findElement(By.id(\"search\"));\nWebElement find = driver.findElement(By.id(\"find\"));\n\nsearch.clear();\nsearch.sendKeys(\"Selenium\");\n\nSystem.out.println(search.getAttribute(\"value\"));\nSystem.out.println(find.getText());\n\ndriver.navigate().refresh();\n\nSystem.out.println(driver.getCurrentUrl());\n```\n\nWhich statements are correct?","options":[["A","The first printed value is `Selenium`.\\"],["B","The second printed value is `Find`.\\"],["C","`refresh()` reloads the current page.\\"],["D","`getCurrentUrl()` returns a boolean."]],"answer":["A","B","C"],"expected":"The first two lines are:\n\n```\nSelenium\nFind\n```\n\nThe third line is the current page URL, which depends on the page being tested.","steps":"1. Selenium locates the input and button.\n2. `clear()` removes Bank.\n3. `sendKeys(\"Selenium\")` enters Selenium.\n4. `getAttribute(\"value\")` returns Selenium.","concept":"","optionReview":"","takeaway":"5\\. Concept explained\n\nThis combines input handling, text retrieval, browser navigation and return types.\n\n6\\. All options analysed\n\n- A — Correct.\n- B — Correct.\n- C — Correct.\n- D — Incorrect: `getCurrentUrl()` returns String.\n\n7\\. Exam takeaway\n\nWhen a question combines browser and element methods, identify the object each method belongs to and trace the statements in order.\n\n## Final WebDriver methods scorecard\n\n# 73/75\n\nCombined score\n\n# 97.3%\n\nOverall accuracy\n\nAll seven topics covered\n\n1\\. `get()`, `getTitle()`, `getCurrentUrl()`\n\nComplete\n\n2\\. `click()`, `sendKeys()`, `clear()`\n\nComplete\n\n3\\. Element state methods\n\nComplete\n\n4\\. Navigation methods\n\nComplete\n\n5\\. `findElement()` vs `findElements()`\n\nComplete\n\n6\\. `getText()` and `getAttribute()`\n\nComplete\n\n7\\. `close()` vs `quit()`\n\nComplete\n\nAll 70 MCQs reviewed · Seven-part explanations complete · No defective questions\n\n### Revision priorities\n\nYour two earlier practice-batch mistakes were:\n\n1. Return types — especially remembering that `clear()`, `click()` and `sendKeys()` return `void`.\n2. Multiple-select questions — check every option before submitting.\n\nYour final assessment was a perfect 20/20, so there were no errors in the final test.\n\nWebDriver methods are now complete. The question register WDM-001–070 is ready for future PDF compilation."}
  ];
  const LEARN_TOPICS=[
    {id:'xpath-axes',number:4,title:'XPath Axes',intro:'Use an element’s position in the DOM to locate related elements when it has no useful ID, name, or class.',sections:[
      {title:'What are XPath axes?',html:`<p>XPath axes describe relationships between the current element and other elements in the HTML DOM. They are useful when you can identify a nearby label, container, or related control more reliably than the target itself.</p><pre><code>&lt;div&gt;
  &lt;label&gt;Username&lt;/label&gt;
  &lt;input id="username"&gt;
  &lt;button&gt;Login&lt;/button&gt;
&lt;/div&gt;</code></pre>`},
      {title:'Important axes',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Axis</th><th>Meaning</th></tr></thead><tbody><tr><td><code>parent::</code></td><td>Immediate parent of the current element</td></tr><tr><td><code>child::</code></td><td>Direct children only</td></tr><tr><td><code>ancestor::</code></td><td>All parent levels</td></tr><tr><td><code>ancestor-or-self::</code></td><td>Ancestors and the current element</td></tr><tr><td><code>following-sibling::</code></td><td>Later siblings at the same DOM level</td></tr><tr><td><code>preceding-sibling::</code></td><td>Earlier siblings at the same DOM level</td></tr><tr><td><code>following::</code></td><td>Later elements in document order</td></tr><tr><td><code>preceding::</code></td><td>Earlier elements in document order</td></tr><tr><td><code>descendant::</code></td><td>All nested elements below the current element</td></tr><tr><td><code>descendant-or-self::</code></td><td>Descendants and the current element</td></tr></tbody></table></div>`},
      {title:'Common axis examples',html:`<div class="boi-quiz-lesson-example"><h4>Immediate parent</h4><pre><code>//input[@id='username']/parent::div</code></pre><p>Find the input, then select its immediate <code>div</code> parent.</p></div><div class="boi-quiz-lesson-example"><h4>Direct children only</h4><pre><code>//div/child::input</code></pre><p>Select input elements that are direct children of a <code>div</code>.</p></div><div class="boi-quiz-lesson-example"><h4>Any ancestor form</h4><pre><code>//input[@id='username']/ancestor::form</code></pre><p>Find the containing form even if other elements sit between the input and form.</p></div><div class="boi-quiz-lesson-example"><h4>All nested inputs</h4><pre><code>//div/descendant::input</code></pre><p>Select inputs at any depth under the div.</p></div><div class="boi-quiz-lesson-example"><h4>Sibling before or after</h4><pre><code>//label/following-sibling::input
//input/preceding-sibling::label</code></pre><p>Both elements must be at the same DOM level.</p></div>`},
      {title:'Selenium Java and exam distinction',html:`<pre><code>WebElement element = driver.findElement(
    By.xpath("//input[@id='username']/parent::div")
);</code></pre><div class="boi-quiz-callout"><strong>Remember:</strong> <code>following-sibling</code> and <code>preceding-sibling</code> stay at the same level. <code>following</code> and <code>preceding</code> move through document order and can match elements at other levels.</div>`}
    ]},
    {id:'xpath-functions',number:5,title:'XPath Functions',intro:'Use text and attribute functions when exact locator values are unavailable or dynamic.',sections:[
      {title:'text() — exact visible text',html:`<p><code>text()</code> matches the element’s exact text.</p><pre><code>//button[text()='Login']</code></pre><p>This matches a button containing exactly <strong>Login</strong>. It does not match <strong>Login Now</strong>.</p>`},
      {title:'contains() — partial value',html:`<p>Use <code>contains()</code> when you know only part of the text or attribute.</p><pre><code>//button[contains(text(),'Login')]
//input[contains(@id,'user')]</code></pre><p>The first matches button text containing “Login”. The second can match IDs such as <code>user123</code> or <code>login-user</code>.</p>`},
      {title:'starts-with() — known prefix',html:`<p>Use <code>starts-with()</code> when the value begins with known text.</p><pre><code>//input[starts-with(@id,'user')]</code></pre><p>For <code>&lt;input id="user_login_123"&gt;</code>, this matches because the ID starts with <code>user</code>.</p>`},
      {title:'Compare the functions',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Function</th><th>Use</th><th>Example</th></tr></thead><tbody><tr><td><code>text()</code></td><td>Exact text</td><td><code>//button[text()='Login']</code></td></tr><tr><td><code>contains()</code></td><td>Partial value anywhere</td><td><code>//button[contains(text(),'Login')]</code></td></tr><tr><td><code>starts-with()</code></td><td>Value begins with text</td><td><code>//input[starts-with(@id,'user')]</code></td></tr></tbody></table></div><div class="boi-quiz-callout"><strong>Exam trap:</strong> <code>contains()</code> can match text anywhere in the value. <code>starts-with()</code> only matches at the beginning. For “Submit Application”, both <code>contains(text(),'Submit')</code> and <code>starts-with(text(),'Submit')</code> match; exact <code>text()='Submit'</code> does not.</div>`}
    ]},
    {id:'css-selectors',number:6,title:'CSS Selectors',intro:'Locate elements with CSS syntax for IDs, classes, attributes, tags, and relationships.',sections:[
      {title:'CSS selector basics',html:`<p>CSS selectors are a Selenium locator strategy. In Java, pass the selector to <code>By.cssSelector()</code>.</p><pre><code>driver.findElement(By.cssSelector("input"));</code></pre><div class="boi-quiz-table-wrap"><table><thead><tr><th>Syntax</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>#</code></td><td>ID</td><td><code>#username</code></td></tr><tr><td><code>.</code></td><td>Class</td><td><code>.login-button</code></td></tr><tr><td>tag name</td><td>Tag</td><td><code>input</code></td></tr><tr><td><code>[attribute='value']</code></td><td>Attribute value</td><td><code>[name='email']</code></td></tr><tr><td><code>tag#id</code></td><td>Tag with ID</td><td><code>input#username</code></td></tr><tr><td><code>tag.class</code></td><td>Tag with class</td><td><code>button.primary</code></td></tr><tr><td><code>*</code></td><td>Any element</td><td><code>div *</code></td></tr></tbody></table></div>`},
      {title:'IDs, classes, and attributes',html:`<div class="boi-quiz-lesson-example"><h4>ID</h4><pre><code>&lt;input id="email"&gt;
By.cssSelector("#email")</code></pre></div><div class="boi-quiz-lesson-example"><h4>Classes</h4><pre><code>&lt;button class="login primary"&gt;Login&lt;/button&gt;
By.cssSelector(".login")
By.cssSelector(".login.primary")</code></pre><p>There is no space between class selectors when both classes must match.</p></div><div class="boi-quiz-lesson-example"><h4>One or more attributes</h4><pre><code>By.cssSelector("input[name='username']")
By.cssSelector("input[type='text'][name='username']")</code></pre><p>With multiple attributes, all conditions must match.</p></div>`},
      {title:'Relationship selectors',html:`<pre><code>&lt;div id="parent"&gt;
  &lt;input id="first"&gt;
  &lt;span&gt;&lt;input id="second"&gt;&lt;/span&gt;
&lt;/div&gt;</code></pre><div class="boi-quiz-table-wrap"><table><thead><tr><th>Selector</th><th>Meaning</th></tr></thead><tbody><tr><td><code>div &gt; input</code></td><td>Direct child inputs</td></tr><tr><td><code>div input</code></td><td>All descendant inputs</td></tr><tr><td><code>div + span</code></td><td>Immediately following sibling span</td></tr><tr><td><code>div ~ span</code></td><td>All following sibling spans</td></tr></tbody></table></div><div class="boi-quiz-callout"><strong>Remember:</strong> <code>&gt;</code> is direct child; a space is any descendant; <code>+</code> is the next sibling; <code>~</code> selects following siblings, not necessarily the next one.</div>`},
      {title:'Attribute matching operators',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>=</code></td><td>Exact match</td><td><code>[id='user']</code></td></tr><tr><td><code>*=</code></td><td>Contains</td><td><code>[id*='user']</code></td></tr><tr><td><code>^=</code></td><td>Starts with</td><td><code>[id^='user']</code></td></tr><tr><td><code>$=</code></td><td>Ends with</td><td><code>[id$='123']</code></td></tr></tbody></table></div><p>For <code>id="user_login_123"</code>, <code>[id='user_login_123']</code> is exact, <code>[id*='login']</code> contains, <code>[id^='user']</code> starts with, and <code>[id$='123']</code> ends with.</p>`},{title:'Quick revision',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Concept</th><th>Remember</th></tr></thead><tbody><tr><td>XPath parent / ancestor</td><td>Immediate parent / all ancestor levels</td></tr><tr><td>XPath child / descendant</td><td>Direct children / all nested descendants</td></tr><tr><td>following-sibling</td><td>Later siblings at the same level</td></tr><tr><td>text() / contains() / starts-with()</td><td>Exact text / partial value / known prefix</td></tr><tr><td>CSS # / .</td><td>ID / class</td></tr><tr><td>CSS &gt; / space</td><td>Direct child / descendant</td></tr><tr><td>CSS + / ~</td><td>Immediately next sibling / later siblings</td></tr></tbody></table></div>`}
    ]}
    ,{id:'css-vs-xpath',number:7,block:3,title:'CSS vs XPath',intro:'Choose a locator strategy based on the element details and DOM relationship you can reliably target.',sections:[
      {title:'Compare the capabilities',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Feature</th><th>CSS</th><th>XPath</th></tr></thead><tbody><tr><td>ID, class, attribute</td><td>Yes</td><td>Yes</td></tr><tr><td>Visible text</td><td>No standard direct text selector</td><td>Yes</td></tr><tr><td>Parent navigation</td><td>No general ancestor axis</td><td>Yes</td></tr><tr><td>Child and sibling relationships</td><td>Yes</td><td>Yes</td></tr><tr><td>Partial attribute matching</td><td>Yes</td><td>Yes</td></tr></tbody></table></div><div class="boi-quiz-callout"><strong>Exam trap:</strong> CSS has no standard <code>text()</code> selector or general XPath-style <code>ancestor::</code> axis. Modern CSS has selectors such as <code>:has()</code>, so avoid the overbroad claim that CSS can never express a parent-related relationship.</div>`},
      {title:'Examples and when to use each',html:`<pre><code>&lt;div id="login"&gt;
  &lt;input id="username" class="field"&gt;
  &lt;button&gt;Submit&lt;/button&gt;
&lt;/div&gt;</code></pre><div class="boi-quiz-lesson-example"><h4>CSS for straightforward attributes</h4><pre><code>By.cssSelector("#username")
By.cssSelector(".field")
By.cssSelector("input[id='username']")</code></pre></div><div class="boi-quiz-lesson-example"><h4>XPath for text or traversal</h4><pre><code>By.xpath("//*[@id='username']")
By.xpath("//button[text()='Submit']")
By.xpath("//input[@id='username']/parent::div")</code></pre><p>Use CSS for simple ID, class, and attribute locators. Use XPath when visible text, parent traversal, or a more complex relationship is needed.</p></div>`}
    ]},
    {id:'dynamic-elements',number:8,block:3,title:'Dynamic elements and locators',intro:'Build stable locators from the parts of an element that remain consistent across page loads and interactions.',sections:[
      {title:'Recognise dynamic values',html:`<p>An application may generate a different ID on each visit:</p><pre><code>&lt;input id="user_12345"&gt;
&lt;input id="user_67890"&gt;</code></pre><p>A hard-coded locator for one generated ID can stop working. Identify a stable prefix, suffix, attribute, or nearby relationship instead.</p>`},
      {title:'Match stable attribute portions',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>CSS operator</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>^=</code></td><td>Starts with</td><td><code>input[id^='user_']</code></td></tr><tr><td><code>*=</code></td><td>Contains</td><td><code>input[id*='user']</code></td></tr><tr><td><code>$=</code></td><td>Ends with</td><td><code>input[id$='_name']</code></td></tr></tbody></table></div><pre><code>By.xpath("//input[starts-with(@id,'user_')]")
By.cssSelector("input[id^='user_']")</code></pre><p>You can combine CSS conditions when both ends are stable: <code>input[id^='emp_'][id$='_name']</code>.</p><div class="boi-quiz-callout"><strong>XPath version note:</strong> <code>ends-with()</code> is XPath 2.0 and is not supported by Selenium’s usual XPath 1.0 engine. Prefer a CSS <code>$=</code> selector or another XPath 1.0 compatible approach.</div>`},
      {title:'Dynamic text and avoid brittle paths',html:`<pre><code>By.xpath("//button[contains(text(),'Continue')]")

// Prefer a stable attribute over a long absolute path:
//button[@data-testid='submit']</code></pre><p>Avoid depending on a changing value or a long positional path such as <code>/html/body/div[2]/div[1]/button[3]</code>; small DOM changes can break it.</p>`}
    ]},
    {id:'multiple-matches',number:9,block:3,title:'Multiple matching elements',intro:'Understand what Selenium returns when a locator matches one, many, or no elements, and how Java list indexing affects the result.',sections:[
      {title:'findElement() and findElements()',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Matches</th><th><code>findElement()</code></th><th><code>findElements()</code></th></tr></thead><tbody><tr><td>None</td><td>Throws <code>NoSuchElementException</code></td><td>Returns an empty list</td></tr><tr><td>One</td><td>Returns that element</td><td>Returns a list of one</td></tr><tr><td>Many</td><td>Returns the first in document order</td><td>Returns all in a list</td></tr></tbody></table></div><pre><code>List&lt;WebElement&gt; buttons = driver.findElements(By.className("action"));
System.out.println(buttons.size());</code></pre><p>For three matching buttons, the size is <code>3</code>. The list holds the elements found at lookup time; it is not necessarily live.</p>`},
      {title:'Read list positions and text',html:`<pre><code>buttons.get(0); // first element
buttons.get(1); // second element
buttons.get(2); // third element</code></pre><p>Java lists start at zero. For a list of size <code>n</code>, valid indexes are <code>0</code> through <code>n - 1</code>. An invalid index throws <code>IndexOutOfBoundsException</code>.</p><pre><code>for (WebElement button : buttons) {
    System.out.println(button.getText());
}</code></pre>`},
      {title:'DOM updates and stale elements',html:`<p>If the page replaces an element after Selenium has stored its <code>WebElement</code> reference, that old reference does not automatically point to the replacement. Interacting with it can raise <code>StaleElementReferenceException</code>; locate the element again after the DOM update.</p><div class="boi-quiz-callout"><strong>Quick recall:</strong> <code>findElement()</code> returns the first match; <code>findElements()</code> returns all matches or an empty list; list indexes start at zero; a replaced DOM element can make an old reference stale.</div>`}
    ]}
    ,{id:'webdriver-methods',number:10,block:4,title:'WebDriver methods',intro:'Seven essential Selenium method groups: browser navigation, element actions and state, locating, text and attributes, and session cleanup.',sections:[
      {title:'1. get(), getTitle() and getCurrentUrl()',html:`<p>These belong to the <code>WebDriver</code> interface.</p><pre><code>driver.get("https://www.amazon.in");
String title = driver.getTitle();
String url = driver.getCurrentUrl();
System.out.println(title);
System.out.println(url);</code></pre><div class="boi-quiz-table-wrap"><table><thead><tr><th>Method</th><th>Purpose</th><th>Return</th></tr></thead><tbody><tr><td><code>get(url)</code></td><td>Opens the specified URL</td><td><code>void</code></td></tr><tr><td><code>getTitle()</code></td><td>Current page title</td><td><code>String</code></td></tr><tr><td><code>getCurrentUrl()</code></td><td>Current page URL</td><td><code>String</code></td></tr></tbody></table></div><p><code>get()</code> normally waits for the configured page load strategy readiness condition. It does not return the title or URL.</p>`},
      {title:'2. click(), sendKeys() and clear()',html:`<p>These belong to <code>WebElement</code>.</p><pre><code>WebElement username = driver.findElement(By.id("username"));
username.sendKeys("Deepanshi");
username.clear();
username.sendKeys("Admin");
WebElement login = driver.findElement(By.id("login"));
login.click();</code></pre><div class="boi-quiz-table-wrap"><table><thead><tr><th>Method</th><th>Purpose</th><th>Return</th></tr></thead><tbody><tr><td><code>click()</code></td><td>Clicks an element</td><td><code>void</code></td></tr><tr><td><code>sendKeys()</code></td><td>Types text or key input</td><td><code>void</code></td></tr><tr><td><code>clear()</code></td><td>Clears an editable value</td><td><code>void</code></td></tr></tbody></table></div><p>Repeated <code>sendKeys()</code> calls generally append: sending Hello and then World yields HelloWorld. Use <code>clear()</code> first when replacing existing input. Click works on buttons, links, checkboxes, and other clickable elements.</p>`},
      {title:'3. isDisplayed(), isEnabled() and isSelected()',html:`<p>All three return <code>boolean</code>.</p><div class="boi-quiz-table-wrap"><table><thead><tr><th>Method</th><th>Checks</th></tr></thead><tbody><tr><td><code>isDisplayed()</code></td><td>Whether the element is displayed</td></tr><tr><td><code>isEnabled()</code></td><td>Whether it is enabled for interaction</td></tr><tr><td><code>isSelected()</code></td><td>Whether an option is selected</td></tr></tbody></table></div><p>A visible element can be disabled. An enabled checkbox can be unchecked. <code>isSelected()</code> is useful for checkboxes, radio buttons, and select options.</p><div class="boi-quiz-callout"><strong>Remember:</strong> displayed = visible; enabled = can interact; selected = checked or chosen.</div>`},
      {title:'4. Navigation methods',html:`<p>Navigation methods are accessed through <code>driver.navigate()</code>.</p><pre><code>driver.navigate().to("https://amazon.in");
driver.navigate().back();
driver.navigate().forward();
driver.navigate().refresh();</code></pre><div class="boi-quiz-table-wrap"><table><thead><tr><th>Method</th><th>Purpose</th><th>Return</th></tr></thead><tbody><tr><td><code>back()</code></td><td>Previous page in browser history</td><td><code>void</code></td></tr><tr><td><code>forward()</code></td><td>Next history entry</td><td><code>void</code></td></tr><tr><td><code>refresh()</code></td><td>Reload current page</td><td><code>void</code></td></tr><tr><td><code>to(url)</code></td><td>Navigate to a URL</td><td><code>void</code></td></tr></tbody></table></div><p><code>driver.get(url)</code> and <code>driver.navigate().to(url)</code> both navigate to a URL. The Navigation interface also provides back and forward history operations.</p>`},
      {title:'5. findElement() vs findElements()',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th></th><th><code>findElement()</code></th><th><code>findElements()</code></th></tr></thead><tbody><tr><td>Return type</td><td><code>WebElement</code></td><td><code>List&lt;WebElement&gt;</code></td></tr><tr><td>Matches</td><td>First match</td><td>All matches</td></tr><tr><td>No match</td><td><code>NoSuchElementException</code></td><td>Empty list</td></tr></tbody></table></div><pre><code>List&lt;WebElement&gt; buttons = driver.findElements(By.className("btn"));
System.out.println(buttons.size());</code></pre><p>If three buttons match, size is 3. <code>findElements(By.id("missing"))</code> returns an empty list; it does not throw <code>NoSuchElementException</code>.</p>`},
      {title:'6. getText() and getAttribute()',html:`<pre><code>&lt;input id="username" value="Admin"&gt;
&lt;button id="login"&gt;Login Now&lt;/button&gt;</code></pre><pre><code>WebElement button = driver.findElement(By.id("login"));
System.out.println(button.getText());
WebElement input = driver.findElement(By.id("username"));
System.out.println(input.getAttribute("value"));</code></pre><p>Output: <code>Login Now</code>, then <code>Admin</code>.</p><div class="boi-quiz-table-wrap"><table><thead><tr><th>Method</th><th>Purpose</th><th>Return</th></tr></thead><tbody><tr><td><code>getText()</code></td><td>Visible element text</td><td><code>String</code></td></tr><tr><td><code>getAttribute(name)</code></td><td>Attribute/property value</td><td><code>String</code> or <code>null</code></td></tr></tbody></table></div><p>Use <code>getText()</code> for visible text and commonly <code>getAttribute("value")</code> for an input value. Selenium 4 also provides <code>getDomAttribute()</code> for the actual DOM attribute and <code>getDomProperty()</code> for the DOM property.</p>`},
      {title:'7. close() vs quit()',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Method</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>close()</code></td><td>Closes the current browser window</td></tr><tr><td><code>quit()</code></td><td>Closes all windows associated with the WebDriver session and ends it</td></tr></tbody></table></div><p>A session can manage multiple windows or tabs. Closing the current window does not necessarily terminate the session. <code>quit()</code> ends it and is commonly used for test cleanup.</p>`},
      {title:'Quick revision: return types',html:`<div class="boi-quiz-table-wrap"><table><thead><tr><th>Method(s)</th><th>Return type</th></tr></thead><tbody><tr><td><code>get()</code>, <code>click()</code>, <code>sendKeys()</code>, <code>clear()</code>, navigation, <code>close()</code>, <code>quit()</code></td><td><code>void</code></td></tr><tr><td><code>getTitle()</code>, <code>getCurrentUrl()</code>, <code>getText()</code>, <code>getAttribute()</code></td><td><code>String</code></td></tr><tr><td><code>isDisplayed()</code>, <code>isEnabled()</code>, <code>isSelected()</code></td><td><code>boolean</code></td></tr><tr><td><code>findElement()</code></td><td><code>WebElement</code></td></tr><tr><td><code>findElements()</code></td><td><code>List&lt;WebElement&gt;</code></td></tr></tbody></table></div>`}
    ]}
    ,{id:'waits-synchronization',number:11,block:1,group:'WAITS AND SYNCHRONIZATION',title:'Waits and Synchronization',intro:'Eight subtopics on Selenium waits, synchronization, and common interaction exceptions.',sections:[
      {title:'1. Implicit, explicit and fluent waits',html:`<p>A wait gives the browser time to reach the state the next test step depends on.</p><ul><li><strong>Implicit wait:</strong> session-wide setting for finding elements. Selenium retries lookup until the time limit; it does not wait for a particular state such as visible or clickable.</li><li><strong>Explicit wait:</strong> waits for a specific condition at a specific point. <code>WebDriverWait</code> is the common Java class.</li><li><strong>Fluent wait:</strong> configurable explicit wait with a timeout, polling interval, and optional ignored exceptions.</li></ul><pre><code>driver.manage().timeouts()
    .implicitlyWait(Duration.ofSeconds(5));

WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
wait.until(ExpectedConditions.visibilityOfElementLocated(
    By.id("message")));</code></pre><p>Prefer explicit waits when you know the state needed. Selenium warns against mixing implicit and explicit waits because combined timing can be unpredictable.</p>`},
      {title:'2. ExpectedConditions and polling interval',html:`<p><code>ExpectedConditions</code> are ready-made conditions for explicit waits. Examples include presence, visibility, clickability, text, title, or an alert.</p><pre><code>wait.until(ExpectedConditions.elementToBeClickable(
    By.id("submit"))).click();

Wait&lt;WebDriver&gt; wait = new FluentWait&lt;&gt;(driver)
    .withTimeout(Duration.ofSeconds(10))
    .pollingEvery(Duration.ofMillis(500));</code></pre><p>The polling interval controls how often the wait checks. A shorter interval checks more often; it does not make the page ready sooner. Choose a sensible interval and the condition that matches the action.</p>`},
      {title:'3. TimeoutException',html:`<p>A <code>TimeoutException</code> means a wait or timed browser operation did not finish before its limit. An explicit wait throws it if the condition never becomes true.</p><pre><code>wait.until(ExpectedConditions.visibilityOfElementLocated(
    By.id("result")));</code></pre><p>If the result never appears, check the locator, whether the expected state can occur, and whether the timeout suits the application. Increasing the timeout alone will not fix a wrong locator or impossible condition.</p>`},
      {title:'4. StaleElementReferenceException',html:`<p>A <code>WebElement</code> refers to an element found earlier. It becomes stale when that element is no longer attached to the current DOM, such as after a refresh, navigation, or dynamic update.</p><pre><code>WebElement save = driver.findElement(By.id("save"));
// The page updates and replaces the button
save.click(); // May throw StaleElementReferenceException</code></pre><p>Locate the element again after the page changes, then interact with the fresh reference. Waiting for the updated page state first can help.</p>`},
      {title:'5. NoSuchElementException',html:`<p>This means Selenium could not find an element when it tried to locate it. Causes include a wrong locator, the wrong page/frame, or looking before a dynamic element is added.</p><pre><code>WebElement result = wait.until(
    ExpectedConditions.presenceOfElementLocated(By.id("result")));</code></pre><p>Presence means the element exists in the DOM; it does not guarantee visibility or clickability. Choose the condition that matches the next action.</p>`},
      {title:'6. ElementNotInteractableException',html:`<p>This means the element was found, but Selenium could not interact with it in its current state. It may be hidden, disabled, outside the viewport, or the locator may identify the wrong element.</p><pre><code>wait.until(ExpectedConditions.elementToBeClickable(
    By.id("continue"))).click();</code></pre><p>Check the locator, whether the element supports the action, and whether it is ready. If another element covers the target, Selenium may instead raise <code>ElementClickInterceptedException</code>.</p>`},
      {title:'7. Synchronization problems and solutions',html:`<p>A synchronization problem occurs when the test acts before the page is ready. Modern pages update asynchronously, so assuming every change is immediate can make tests flaky.</p><ol><li>Identify the state the next action needs.</li><li>Wait for that specific state with an explicit wait.</li><li>Check the locator and whether the element is in the right frame or window.</li><li>If the DOM changed, locate the element again.</li><li>Avoid mixing implicit and explicit waits.</li></ol><p>Wait for a message to become visible before reading it instead of sleeping for an arbitrary duration.</p>`},
      {title:'8. Why Thread.sleep is discouraged',html:`<pre><code>Thread.sleep(5000);</code></pre><p><code>Thread.sleep</code> pauses for the full fixed duration whether the page is ready immediately or still needs longer. This wastes time when five seconds are unnecessary and remains unreliable when the page takes longer. An explicit wait checks the needed condition and continues as soon as it becomes true, or times out if it never does.</p>`}
    ]}
  ];
  let selectedLearnTopic='xpath-axes';
  const KEY = 'quantPracticeBoiQuizLocatorsBatch1';
  const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const getSaved = () => { try { const x=JSON.parse(localStorage.getItem(KEY)||'{}'); return x&&typeof x==='object'?x:{}; } catch { return {}; } };
  const saved=getSaved();
  const groupKey=q=>`${q.topic||'Locators'}::${Number(q.batch)||1}`;
  const groups=[...new Set(QUESTIONS.map(groupKey))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
  const groupLabel=key=>{const [topic,batch]=key.split('::');return `${topic} · Batch ${batch}`;};
  let selectedGroups=Array.isArray(saved.groups)?saved.groups.filter(g=>groups.includes(g)):[];
  let solved=new Set(Array.isArray(saved.solved)?saved.solved:[]);
  let bookmarks=new Set(Array.isArray(saved.bookmarks)?saved.bookmarks:[]);let bookmarkUpdates=saved.bookmarkUpdates&&typeof saved.bookmarkUpdates==='object'?{...saved.bookmarkUpdates}:Object.fromEntries([...(saved.bookmarks||[])].map(id=>[id,{value:true,updatedAt:saved.updatedAt||0}]));
  let history=Array.isArray(saved.history)?saved.history:[];for(const id of solved){if(!history.some(a=>a.id===id))history.push({id,correct:true,seconds:null,timestamp:0,legacy:true});}
  let run=saved.run&&typeof saved.run==='object'?saved.run:{results:{},skipped:[],visited:[],counts:{},wrong:0,started:false,ended:false};
  run.results=run.results||{};run.answers=run.answers||{};run.skipped=Array.isArray(run.skipped)?run.skipped:[];run.visited=Array.isArray(run.visited)?run.visited:[];run.counts=run.counts||{};run.wrong=Number(run.wrong)||0;
  let order=Array.isArray(saved.order)?saved.order.filter(id=>QUESTIONS.some(q=>q.id===id)):[];
  let index=Math.max(0,Number(saved.index)||0),selection=new Set(),submitted=false,revealSolved=false,hasStarted=Boolean(run.started),practiceEnded=Boolean(run.ended),activeView='practice',focusedId=null;
  let timedQuestionId=saved.timedQuestionId||null,questionOpenedAt=Number(saved.questionOpenedAt)||0;
  const root=document.getElementById('boiQuizContent'),progress=document.getElementById('boiQuizProgress'),bar=document.getElementById('boiQuizBar');
  const toggle=document.getElementById('boiQuizTopicToggle'),menu=document.getElementById('boiQuizTopicMenu'),label=document.getElementById('boiQuizTopicLabel'),options=document.getElementById('boiQuizTopicOptions'),allBox=document.getElementById('boiQuizAllTopics');
  function chosenQuestions(){return focusedId?QUESTIONS.filter(q=>q.id===focusedId):QUESTIONS.filter(q=>selectedGroups.length===0||selectedGroups.includes(groupKey(q)));}
  function shuffle(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
  function syncPicker(){allBox.checked=selectedGroups.length===0;options.innerHTML=groups.map(g=>`<label class="boi-quiz-topic-option"><input type="checkbox" value="${escape(g)}" ${selectedGroups.includes(g)?'checked':''}><span>${escape(groupLabel(g))}</span></label>`).join('');label.textContent=selectedGroups.length===0?'All topics':selectedGroups.length===1?groupLabel(selectedGroups[0]):`${selectedGroups.length} batches selected`;document.getElementById('boiQuizTopicTitle').textContent=selectedGroups.length===0?'All topics':selectedGroups.length===1?groupLabel(selectedGroups[0]):'Selected BOI batches';document.getElementById('boiQuizSidebarTitle').textContent=selectedGroups.length===0?'BOI Quiz':selectedGroups.length===1?groupLabel(selectedGroups[0]):'Selected BOI batches';options.querySelectorAll('input').forEach(box=>box.onchange=()=>{selectedGroups=[...options.querySelectorAll('input:checked')].map(x=>x.value);if(selectedGroups.length===groups.length)selectedGroups=[];focusedId=null;activeView='practice';beginRun();});}
  function save(){localStorage.setItem(KEY,JSON.stringify({topic:selectedGroups.length===1?selectedGroups[0].split('::')[0]:'__all',groups:selectedGroups,order,index,solved:[...solved],bookmarks:[...bookmarks],history:history.slice(-10000),run,timedQuestionId,questionOpenedAt,bookmarkUpdates,updatedAt:Date.now()}));}
  function renderStats(){const legacy=[...solved].filter(id=>!history.some(a=>a.id===id)).length,answered=history.length+legacy,correct=history.filter(a=>a.correct).length+legacy,timed=history.filter(a=>Number.isFinite(a.seconds)),avg=timed.length?Math.round(timed.reduce((n,a)=>n+a.seconds,0)/timed.length):null;let streak=0,best=0;for(const a of history){streak=a.correct?streak+1:0;best=Math.max(best,streak);}best=Math.max(best,Number(saved.bestStreak)||0);document.getElementById('boiQuizBookmarkCount').textContent=bookmarks.size;const sideStart=document.getElementById('boiQuizStartPractice');sideStart.textContent=activeView!=='practice'&&hasStarted&&!practiceEnded?'Back to practice →':'Start practicing →';document.getElementById('boiQuizStats').innerHTML=`<div class="boi-quiz-stat"><strong>${answered}</strong><span>ANSWERED</span></div><div class="boi-quiz-stat"><strong>${answered?Math.round(correct/answered*100)+'%':'—'}</strong><span>ACCURACY</span></div><div class="boi-quiz-stat"><strong>${avg===null?'—':`${String(Math.floor(avg/60)).padStart(2,'0')}:${String(avg%60).padStart(2,'0')}`}</strong><span>AVG. TIME</span></div><div class="boi-quiz-stat"><strong>${best}</strong><span>BEST STREAK</span></div>`;}
  function beginRun(){focusedId=null;const pool=chosenQuestions();order=shuffle(pool.map(q=>q.id));index=0;selection.clear();submitted=false;revealSolved=false;hasStarted=false;practiceEnded=false;run={results:{},answers:{},skipped:[],visited:[],counts:{},wrong:0,started:false,ended:false};timedQuestionId=null;questionOpenedAt=0;save();syncPicker();render();}
  if(!order.length||order.some(id=>!chosenQuestions().some(q=>q.id===id)))order=shuffle(chosenQuestions().map(q=>q.id));
  if(!saved.run){hasStarted=false;practiceEnded=false;run={results:{},answers:{},skipped:[],visited:[],counts:{},wrong:0,started:false,ended:false};}
  function activeQuestion(){return QUESTIONS.find(q=>q.id===order[index]);}
  function startQuiz(){document.getElementById('boiQuizTab').classList.add('active');document.getElementById('boiQuizTab').setAttribute('aria-pressed','true');const examTab=document.getElementById('examTab');examTab.classList.remove('active');examTab.setAttribute('aria-pressed','false');document.querySelector('.shell').classList.remove('exam-mode');const layout=document.querySelector('.layout');layout.classList.remove('exam-mode');layout.classList.add('quiz-mode','boi-practice-mode');document.getElementById('boiQuizSidebarTopic').appendChild(document.querySelector('.boi-quiz-topic-filter'));['practiceView','learnView','bookmarksView','notesView','notebookView','examView','boiView','finalBoiView'].forEach(id=>{const el=document.getElementById(id);if(el)el.style.display='none';});document.getElementById('boiQuizView').style.display='block';render();}
  function setActiveView(view){activeView=view;document.getElementById('boiQuizPracticeTab').classList.toggle('active',view==='practice');document.getElementById('boiQuizLearnTab').classList.toggle('active',view==='learn');document.getElementById('boiQuizBookmarksTab').classList.toggle('active',view==='bookmarks');render();}
  function bookmarkToggle(id){if(bookmarks.has(id))bookmarks.delete(id);else bookmarks.add(id);bookmarkUpdates[id]={value:bookmarks.has(id),updatedAt:Date.now()};save();render();}
  function renderBookmarks(){const list=QUESTIONS.filter(q=>bookmarks.has(q.id));root.innerHTML=`<section class="boi-quiz-bookmark-page"><div class="boi-quiz-page-title"><div><span class="pill">SAVED QUESTIONS</span><h3>Bookmarks</h3><p>${list.length} BOI question${list.length===1?'':'s'} saved for review.</p></div></div>${list.length?`<div class="boi-quiz-bookmark-list">${list.map(q=>`<article class="boi-quiz-bookmark-card"><div><span class="pill">${escape(groupLabel(groupKey(q)))}</span><h4>${escape(q.id)} · ${escape(q.title)}</h4><p>${escape(q.question)}</p></div><div class="boi-quiz-bookmark-actions"><button type="button" data-practice-bookmark="${escape(q.id)}" class="boi-quiz-next">Practice question</button><button type="button" data-remove-bookmark="${escape(q.id)}" class="boi-quiz-utility is-bookmarked" aria-label="Remove bookmark">★</button></div></article>`).join('')}</div>`:'<div class="boi-quiz-empty-bookmarks">No bookmarked questions yet. Use the Bookmark button while practicing to save one here.</div>'}</section>`;root.querySelectorAll('[data-remove-bookmark]').forEach(b=>b.onclick=()=>bookmarkToggle(b.dataset.removeBookmark));root.querySelectorAll('[data-practice-bookmark]').forEach(b=>b.onclick=()=>{const q=QUESTIONS.find(x=>x.id===b.dataset.practiceBookmark);focusedId=q.id;selectedGroups=[groupKey(q)];syncPicker();order=[q.id];index=0;run={results:{},answers:{},skipped:[],visited:[],counts:{},wrong:0,started:true,ended:false};hasStarted=true;practiceEnded=false;activeView='practice';document.getElementById('boiQuizPracticeTab').classList.add('active');document.getElementById('boiQuizLearnTab').classList.remove('active');document.getElementById('boiQuizBookmarksTab').classList.remove('active');save();render();});}
  function renderLearn(){const topic=LEARN_TOPICS.find(x=>x.id===selectedLearnTopic)||LEARN_TOPICS[0];root.innerHTML=`<section class="boi-quiz-learn"><nav class="boi-quiz-learn-topics" aria-label="Choose a BOI locator lesson">${LEARN_TOPICS.map(x=>`<button type="button" class="boi-quiz-learn-topic ${x.id===topic.id?'active':''}" data-learn-topic="${x.id}" aria-pressed="${x.id===topic.id}">${escape(x.title)}</button>`).join('')}</nav><article class="boi-quiz-lesson"><span class="pill">${escape(topic.group||'LOCATORS')} · STUDY BLOCK ${topic.block||2}</span><h3>${escape(topic.title)}</h3><p class="boi-quiz-lesson-intro">${escape(topic.intro)}</p>${topic.sections.map(section=>`<section class="boi-quiz-lesson-section"><h4>${escape(section.title)}</h4>${section.html}</section>`).join('')}</article></section>`;root.querySelectorAll('[data-learn-topic]').forEach(button=>button.onclick=()=>{selectedLearnTopic=button.dataset.learnTopic;renderLearn();});}
  function analysisHtml(pool){const practiced=run.visited.length,correct=Object.values(run.results).filter(x=>x==='correct').length,skipped=run.skipped.length,notAttempted=Math.max(0,pool.length-practiced);return `<section class="boi-quiz-finish"><span class="pill">${escape(selectedGroups.length?selectedGroups.map(groupLabel).join(', ').toUpperCase():'ALL TOPICS')}</span><h3>${practiceEnded?'Practice ended':'Set complete'}</h3><p>Set analysis · ${practiced} of ${pool.length} questions practiced in this set.</p><div class="boi-quiz-analysis-stats"><div><strong>${correct}</strong><span>CORRECT</span></div><div><strong>${run.wrong}</strong><span>WRONG ATTEMPTS</span></div><div><strong>${skipped}</strong><span>SKIPPED</span></div><div><strong>${notAttempted}</strong><span>NOT ATTEMPTED</span></div></div><h4 class="boi-quiz-analysis-heading">Question-by-question analysis</h4><div class="boi-quiz-analysis-list">${order.map(id=>{const q=QUESTIONS.find(x=>x.id===id),state=run.results[id]|| (run.skipped.includes(id)?'skipped':'not-attempted'),count=Number(run.counts[id])||0;return `<div class="boi-quiz-analysis-row"><span class="boi-quiz-result-tag" data-result="${state}">${state==='correct'?'Correct':state==='skipped'?'Skipped':count?'Needs review':'Not attempted'}</span><span class="boi-quiz-analysis-q"><strong>${escape(q.id)} · ${escape(q.title)}</strong><small>${count}× practiced</small></span><button type="button" class="boi-quiz-utility ${bookmarks.has(id)?'is-bookmarked':''}" data-analysis-bookmark="${escape(id)}" aria-label="${bookmarks.has(id)?'Remove bookmark':'Bookmark question'}">${bookmarks.has(id)?'★':'☆'}</button></div>`;}).join('')}</div><button type="button" class="boi-quiz-start" id="boiQuizRestart">Practice another set <span>→</span></button></section>`;}
  function render(){const pool=chosenQuestions(),completed=Object.values(run.results).filter(x=>x==='correct').length+run.skipped.length;renderStats();progress.textContent=hasStarted?`${groupLabel(groupKey(QUESTIONS.find(q=>q.id===order[index])||pool[0]))} · ${Math.min(index+1,pool.length)} of ${pool.length}`:'Ready when you are';document.getElementById('boiQuizPreviousProgress').textContent=`${pool.filter(q=>solved.has(q.id)).length} of ${pool.length} previously completed`;document.getElementById('boiQuizSetCount').textContent=`${pool.length} questions · ${new Set(pool.map(groupKey)).size} batches in this set`;bar.style.width=`${pool.length?Math.min(100,completed/pool.length*100):0}%`;syncPicker();if(activeView==='bookmarks'){renderBookmarks();return;}if(activeView==='learn'){renderLearn();return;}if(practiceEnded||index>=order.length&&hasStarted){practiceEnded=practiceEnded||index>=order.length;run.ended=practiceEnded;save();root.innerHTML=analysisHtml(pool);document.getElementById('boiQuizRestart').onclick=()=>beginRun();root.querySelectorAll('[data-analysis-bookmark]').forEach(b=>b.onclick=()=>bookmarkToggle(b.dataset.analysisBookmark));return;}if(!hasStarted){root.innerHTML=`<section class="boi-quiz-launch"><h3>Your next question is waiting.</h3><p>Choose a batch on the left, then start a practice set.</p></section>`;return;}const q=activeQuestion();if(!q){root.innerHTML='<section class="boi-quiz-finish"><h3>No questions in this selection</h3></section>';return;}if(timedQuestionId!==q.id||!questionOpenedAt){timedQuestionId=q.id;questionOpenedAt=Date.now();save();}const isSolved=solved.has(q.id),answeredText=ids=>ids.map(id=>`${id}: ${q.options.find(o=>o[0]===id)?.[1]||''}`).join('; '),reviews=[['2. Your answer vs correct answer',`Your answer: ${answeredText(run.answers[q.id]||q.previousAnswer||q.answer)}<br>Correct answer: ${answeredText(q.answer)}`],['3. Exact expected output',q.expected],['4. Step-by-step execution',q.steps],['5. Concept explained from basics',q.concept],['6. Explanation of every option',q.optionReview],['7. Exam takeaway',q.takeaway]],optionsHtml=q.options.map(([id,text])=>`<button type="button" class="boi-quiz-option ${revealSolved&&q.answer.includes(id)?'is-correct':''}" data-quiz-option="${id}" aria-pressed="false"><span class="boi-quiz-letter">${id}</span><span>${escape(text)}</span></button>`).join('');root.innerHTML=`<article class="boi-quiz-question"><div class="boi-quiz-qhead"><span class="pill">${escape(q.id)} · ${escape(q.title)}</span><span>${escape(groupLabel(groupKey(q)))} · ${index+1} of ${pool.length}</span></div><button type="button" class="boi-quiz-utility boi-quiz-question-bookmark ${bookmarks.has(q.id)?'is-bookmarked':''}" id="boiQuizBookmark" aria-label="${bookmarks.has(q.id)?'Remove bookmark':'Bookmark question'}">${bookmarks.has(q.id)?'★ Bookmarked':'☆ Bookmark'}</button><h3 class="boi-quiz-prompt">${escape(q.question)}</h3>${q.multi?'<p class="boi-quiz-hint">Select all that apply, then check your answer.</p>':''}<div class="boi-quiz-options">${optionsHtml}</div>${q.multi?'<button type="button" class="boi-quiz-next" id="boiQuizCheck">Check answer</button>':''}<div id="boiQuizFeedback" aria-live="polite">${revealSolved?`<p class="boi-quiz-correct-note">Correct — your seven-point review:</p><div class="boi-quiz-reviews">${reviews.map(([title,body])=>`<section><h4>${escape(title)}</h4><p>${body.includes('<br>')?body:escape(body).replace(/\n/g,'<br>')}</p></section>`).join('')}</div>`:''}</div><div class="boi-quiz-practice-actions">${revealSolved?'':'<button type="button" class="boi-quiz-utility" id="boiQuizSkip">Skip</button>'}<button type="button" class="boi-quiz-utility" id="boiQuizEnd">End practice</button>${revealSolved?'<button type="button" class="boi-quiz-next" id="boiQuizNext">Next question →</button>':''}</div></article>`;document.getElementById('boiQuizBookmark').onclick=()=>bookmarkToggle(q.id);if(document.getElementById('boiQuizSkip'))document.getElementById('boiQuizSkip').onclick=()=>{run.skipped=[...new Set([...run.skipped,q.id])];run.visited=[...new Set([...run.visited,q.id])];index++;selection.clear();submitted=false;revealSolved=false;timedQuestionId=null;questionOpenedAt=0;save();render();};document.getElementById('boiQuizEnd').onclick=()=>{practiceEnded=true;run.ended=true;save();render();};root.querySelectorAll('[data-quiz-option]').forEach(button=>button.onclick=()=>{if(revealSolved||submitted)return;const id=button.dataset.quizOption;if(q.multi){if(selection.has(id))selection.delete(id);else selection.add(id);button.classList.toggle('is-selected',selection.has(id));button.classList.remove('is-wrong');button.setAttribute('aria-pressed',String(selection.has(id)));}else check([id]);});if(q.multi)document.getElementById('boiQuizCheck').onclick=()=>check([...selection]);if(revealSolved)document.getElementById('boiQuizNext').onclick=()=>{index++;selection.clear();submitted=false;revealSolved=false;timedQuestionId=null;questionOpenedAt=0;save();render();};}
  function check(chosen){const q=activeQuestion(),correct=[...q.answer].sort().join('|')===[...chosen].sort().join('|'),seconds=questionOpenedAt?Math.max(0,Math.round((Date.now()-questionOpenedAt)/1000)):null;run.answers[q.id]=[...chosen];history.push({id:q.id,correct,seconds,timestamp:Date.now(),attemptId:`${Date.now()}-${Math.random().toString(36).slice(2)}`});run.visited=[...new Set([...run.visited,q.id])];run.counts[q.id]=(Number(run.counts[q.id])||0)+1;if(!correct){run.wrong++;submitted=false;questionOpenedAt=Date.now();document.querySelectorAll('[data-quiz-option]').forEach(button=>{if(chosen.includes(button.dataset.quizOption))button.classList.add('is-wrong');});document.getElementById('boiQuizFeedback').innerHTML='<p class="boi-quiz-retry">Not quite. Review the choices and try again; the seven-point review appears after the correct answer.</p>';save();renderStats();return;}submitted=true;revealSolved=true;run.results[q.id]='correct';solved.add(q.id);save();render();}
  allBox.onchange=()=>{selectedGroups=[];focusedId=null;activeView='practice';beginRun();};toggle.onclick=()=>{const open=menu.hidden;menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));};document.getElementById('boiQuizStartPractice').onclick=()=>{if(activeView!=='practice'&&hasStarted&&!practiceEnded){setActiveView('practice');return;}activeView='practice';document.getElementById('boiQuizPracticeTab').classList.add('active');document.getElementById('boiQuizLearnTab').classList.remove('active');document.getElementById('boiQuizBookmarksTab').classList.remove('active');if(hasStarted||practiceEnded){focusedId=null;order=shuffle(chosenQuestions().map(q=>q.id));index=0;selection.clear();revealSolved=false;practiceEnded=false;run={results:{},answers:{},skipped:[],visited:[],counts:{},wrong:0,started:true,ended:false};hasStarted=true;}else{activeView='practice';document.getElementById('boiQuizPracticeTab').classList.add('active');document.getElementById('boiQuizLearnTab').classList.remove('active');document.getElementById('boiQuizBookmarksTab').classList.remove('active');hasStarted=true;run.started=true;run.ended=false;}save();render();};document.getElementById('boiQuizPracticeTab').onclick=()=>setActiveView('practice');document.getElementById('boiQuizLearnTab').onclick=()=>setActiveView('learn');document.getElementById('boiQuizBookmarksTab').onclick=()=>setActiveView('bookmarks');document.addEventListener('click',e=>{if(!e.target.closest('.boi-quiz-topic-filter')){menu.hidden=true;toggle.setAttribute('aria-expanded','false');}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.hidden=true;toggle.setAttribute('aria-expanded','false');}});
  window.refreshBoiQuizProgress=()=>{const restored=getSaved();selectedGroups=Array.isArray(restored.groups)?restored.groups.filter(g=>groups.includes(g)):[];solved=new Set(Array.isArray(restored.solved)?restored.solved:[]);bookmarks=new Set(Array.isArray(restored.bookmarks)?restored.bookmarks:[]);bookmarkUpdates=restored.bookmarkUpdates&&typeof restored.bookmarkUpdates==='object'?{...restored.bookmarkUpdates}:{};history=Array.isArray(restored.history)?restored.history:[];run=restored.run&&typeof restored.run==='object'?restored.run:{results:{},answers:{},skipped:[],visited:[],counts:{},wrong:0,started:false,ended:false};run.results=run.results||{};run.answers=run.answers||{};run.answers=run.answers||{};run.skipped=Array.isArray(run.skipped)?run.skipped:[];run.visited=Array.isArray(run.visited)?run.visited:[];run.counts=run.counts||{};order=Array.isArray(restored.order)?restored.order.filter(id=>QUESTIONS.some(q=>q.id===id)):[];index=Math.max(0,Number(restored.index)||0);hasStarted=Boolean(run.started);practiceEnded=Boolean(run.ended);timedQuestionId=restored.timedQuestionId||null;questionOpenedAt=Number(restored.questionOpenedAt)||0;if(!order.length||order.some(id=>!chosenQuestions().some(q=>q.id===id)))order=shuffle(chosenQuestions().map(q=>q.id));syncPicker();renderStats();render();};document.getElementById('boiQuizTab').onclick=startQuiz;window.startBoiQuiz=startQuiz;syncPicker();renderStats();
})();
